/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230704-9","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"文教委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)城南第二小学校改築工事","agenda":"はじめに、(1)城南第二小学校改築工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"最初、細かいところで申し訳ないですが、コンセプトの３のところに、「環境配慮手法の見える化」と「施設全体が環境教材となる計画」というのがあるのですが、これ、吹き抜け活用の自然採光と自然通風というのは、どれだけの、具体的には、実際には省エネ効果があるものなのかというところを伺いたいのが１つと、それともう一つは、今回、総務委員会のほうで契約関係が審査されましたが、この設計ですが。","respondent":"森学校施設担当課長","answer":"教育委員会との関わり方ですけれども、基本設計、実施設計ともに、定期的に会議を行いまして、定例会議を行って、設計を詰めていくです。ご意見の中で、建設準備懇談会の皆様の意見等もございましたので、そういうのを盛り込みながら、設計をつくり上げていったです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"定期的に会議を持っているということですが、今回の区教委からの、この城南第二小学校の設計についての一番事業者に伝えたことというのですか、重要視したことというのは幾つかあったのでしょうか。それを伺いたいと思います。","respondent":"森学校施設担当課長","answer":"幾つかオーダーは当然で出しておりまして、まず１つは、体育館を２階に配置、このことにつきましては、過去に水害が発生している地域ですので、体育館を２階にしてほしいというところ。","voiceIndex":7,"id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"何点か質問させていただきたいと思います。前回の源氏前小学校のときにも質疑させてもらったのですけれども、図面からすまいるスクールの位置が確認できなかったので、そちらをお示ししていただければと思います。教室の廊下部分ですけれども、こちらも車椅子とかが通れる十分な距離が、図面だけからだと分かりにくいので、十分な幅があるのかといったところもお伺いしたいと思います。","respondent":"森学校施設担当課長","answer":"バリアフリーの状況はどうですかというところですけれども、基本的にはバリアフリー対応になっておりまして、各階に車椅子対応のトイレを設置しておりまして、１階には、特にチャイルドシートであったり、おむつ替えのシートも含めましたバリアフリートイレを設置しております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけお伺いをします。その軽減というか、何か子どもたちに対して特別に、こういう工事があるから、何だろう、僕も今、では何が具体的にというのは出てきていないですが、何か特別に彼らに対して、そういったストレスを少しでも解消してあげられるようなシステムというか、サービスというか、そういうのはないのかなと思っているのですが、その辺で何かあれば教えてください。","respondent":"森学校施設担当課長","answer":"それと、どの部分かは今検討中ですけれども、児童の皆様に、どこかの部屋の壁の色であったり、何か工事に参画できないかというのを検討しておりまして、工事があることでの新たな学びについても検討しています。","voiceIndex":14,"id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わりますが、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"提案","question":"それで、コンセプトの中の３、子どもたちの豊かな居場所づくりで、観客席のような「わいわいテラス」と書いてあるのですが、この鳥瞰イメージを見ると、まさに観客席のようなという、これはすごい、区内の学校で、何かこういう複合施設みたいな感じで、意匠がすごくいいなと思っているのですけれども、これは設計事業者からの提案もあると思うのですけれども。","respondent":"森学校施設担当課長","answer":"バルコニーの部分ですけれども、これは設計者からの提案だったのですけれども、やはり運動会のとき、非常に保護者の方々も、今、コロナ禍が終わり通常化に戻りましたので、多くなってまいりますので、運動会をこのバルコニーのところから見ていただきたいということも。","voiceIndex":18,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうございました。分かりました。城南第二小学校の改築をぜひ推し進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"何点かお聞きしたいのが、まず、コンセプトの３番の「身体能力に差がある子どもたちのための運動スペース「キッズグラウンド」を整備し」というところで、これを整備することになった経緯というか、そういったところをお聞かせいただきたいのと、具体的にどういった遊具があるのか、お聞かせください。そういったところと、全体の品川区の学校の考え方として、部屋の数というのはどういったお考えなのか。","respondent":"森学校施設担当課長","answer":"さらに増えた場合には対応ができるようにも、案としてはあります。基本的には、学校の教室数は、地域の児童・生徒が通える学校を用意していくという考え方で設計をしています。","voiceIndex":22,"id":"exchange-008"},{"speaker":"せお委員","kind":"意見","question":"前から、昔からあるような遊具も、それはそれで必要だったりして、なかなか場所が取れない中でなかなか難しいなとは思うのですが、そういったところも総合的に今後も検討してほしいなと、そういったところは考えているところです。部屋数は理解いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご説明ありがとうございました。幾つか質問します。１つ目は、これ、特別支援と書いてあるのは、特別支援教室だという理解でよろしいでしょうか。そして、この１階のここの端に置いた理由を教えてください。それが２つ目です。それから、最後、これはどうなのだろう。","respondent":"森学校施設担当課長、柏木学務課長","answer":"なぜこの場所かというところは、基本的に特別支援教室ですので、通常は通常の普通教室にいる児童の方が、週に１回か２回ほど行くところですので、少し離れて落ち着いたところというふうに考えて、この場所に設定しております。工事期間中の他校への学校選択の関係ですけれども、先ほど委員からありましたように、城南小学校につきましては、就学人口を考えると、学校選択で入るのは非常に厳しいかなと考えています。","voiceIndex":26,"id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうございました。それから、選挙も分かりました。吹き抜けというか、廊下の階段といいますか、そこが少し心配なところがあるのですが、大丈夫とおっしゃっているので、そういうふうにご答弁をいただいたので、伺ったということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"吉田副委員長","kind":"提案","question":"何点かご質問させていただきたいのですが、最初に、このコンセプトの３番目の３つ目に「環境配慮手法の見える化」として自然採光というのがあって、「施設全体が環境教材となる計画とします」とあるのですけれども、以前、環境課に問合せをしたとき、別に教育委員会とかいう問題だけではなくて、環境課としては幾つか、例えば太陽光パネルとか、それから雨水利用とか、提案はするけれども。","respondent":"森学校施設担当課長","answer":"幾つかご質問をいただきまして、まず環境教材です。こちらも資料に表現がないのですけれども、雨水の利用も計画しております。それと、太陽光パネルもそうですし、あと風力と太陽光が合わさった照明器具、そちらも外部に設置はする予定です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"吉田副委員長","kind":"確認","question":"ありがとうございました。ここではないのかもしれないですが、安全の確保だけは何か確認しておきたいなと思って、お答えになれる範囲で伺いたいと思います。","respondent":"森学校施設担当課長","answer":"それと、近隣の皆様、それから、児童、保護者の皆様にも、工事の説明会を、契約が決まった後に速やかに開催する予定です。","voiceIndex":33,"id":"exchange-013"}]},{"id":"topic-02","title":"令和６年度新入学者の受入枠","agenda":"令和６年度新入学者の受入枠","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"（１）の４段落目の部分に書いているところですが、学校選択による希望生徒を受け入れ、新入学までの区内転居者または区外転入者による通学区域内の新入学者数の増に対応するということで、これを設定するということですが、この新入学までの区内転居者というのが、この４月でも、先日の文教委員会では小学校で６６人と、中学校では４２人ということだったと思うのですが。","respondent":"柏木学務課長","answer":"区内転居ですが、言葉どおり、区内の中で、通学区域が変わったところに引っ越した方です。ですので、例は、城南小学校の学区域に住んでいて、城南小学校が指定されていたのですが、その後、城南第二小学校の学区域に引っ越しをされたとかという方になります。","voiceIndex":39,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"それはそうです。この区内転居の理由とかというのは、つかんでいたりするのでしょうか。何か主な傾向とかがあれば、それを伺いたいと思います。","respondent":"柏木学務課長","answer":"理由ですが、すみません、そこまでは把握はしておりません。要は各ご家庭の事情としか、すみませんが申し訳ございません。","voiceIndex":41,"id":"exchange-015"}]},{"id":"topic-03","title":"「品川区学事制度審議会」の設置","agenda":"「品川区学事制度審議会」の設置","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"目的のところの、区立学校における良い教育環境を確保とありますが、具体的には、区教委としてはどういう環境のことを考えているのか、お伺いしたいと思います。それと併せて、諮問を７月にするとありますが、諮問の内容について伺いたいと思います。","respondent":"柏木学務課長","answer":"よりよい環境ですが、今で言いますと、限られた教室数のところに、正直ぎゅうぎゅうにという、少し言い方は悪いですけれども、子どもたちが多く過ごしているという状況が学校によってはありますので、そういう部分を排除していくという部分が、まず１つ目かと考えています。","voiceIndex":50,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"そうですね。やはり非常に大事な教育環境の確保だなというふうに、説明を聞いても思いました。就学人口のさらなる増加というのを書いているのですが、この原因というのは区教委としてはどういうふうに考えているのか、伺いたいと思いますし、あと、増えているところと増えていないところがあると思うのですが、特に増加している地域というのは、区教委としては今どこだと考えていらっしゃるのか伺います。","respondent":"柏木学務課長","answer":"児童・生徒、就学人口が増えている原因ですが、まずは品川区が住みやすい、子育てしやすいということが原因の１つかと考えています。正直、増えること自体は、区としては非常に喜ばしいことと考えています。","voiceIndex":52,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"その学区ですが、この問題というのは、地域や区民にとっても、ひいては親子三代を含めた、そういう地域の文化とか伝統にも関わってくる案件ですから、そして、学区のことも考えるということを通して、今の学校の現状というのも、地域の方も含めて知って考えてもらういい機会ともなりますし、この審議会の議題が通学区域、つまり学区の変更であるということとともに。","respondent":"柏木学務課長","answer":"非公開の理由ですが、審議会等については、公開を前提としてまずは検討いたしました。しかしながら、具体的な事例、先ほども言いましたが学校名等を挙げて審議をいただくことが予想されます。","voiceIndex":54,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"非常に選択制が、さらに話をややこしくしているといいますか、区が言うところの安定的に児童・生徒を受け入れる体制の確保ですとか、そういったところに対してやはり弊害が出ていると私は思うので、そこはぜひ、そこも含めて審議の対象にしていただきたいと、改めて要望したいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-019"},{"speaker":"ゆきた委員","kind":"質問","question":"この審議期間の中で、パブリックコメント実施となっていますけれども、私の認識が間違っていれば言っていただければと思いますが、パブリックコメントの周知で、ホームページとか広報しながわ、ＳＮＳ発信とかをされると思うのですけれども、このパブリックコメントを実施するという事前の周知といったところではどのようにされているのか、またどんな工夫をされているのか、お伺いしたいと思います。","respondent":"柏木学務課長","answer":"事前にパブリックコメントをしますという周知というのは、あまり記憶がないのですけれども、ただ、ホームページ等で要点筆記等の形になりますけれども、そういう部分で事前に、当審議会につきましては周知ができるのかなとは考えてあります。","voiceIndex":58,"id":"exchange-020"},{"speaker":"ゆきた委員","kind":"質問","question":"パブリックコメントについては、ホームページで発信された際に、区民はその際に認識されるということで間違いないでしょうか。お伺いしたいと思います。","respondent":"柏木学務課長","answer":"私もそのように認識をしています。","voiceIndex":60,"id":"exchange-021"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"工夫として、より多くの方に幅広くパブリックコメントで周知はされていると思われますが、例えばこれから小学校に上がる幼稚園とか保育園の方々とか、そういった方にも幅広く周知はされていると思うのですけれども、よりこのニーズが求められているところに対してパブリックコメントが周知されますよということで、そういった保護者の方々にとか、チラシとか掲示とかができればと思いますので、要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"以前の学事制度審議会だと、ちょうど中間報告みたいなものをしたことがあったかもしれないですが、その点について今回はどうなのでしょうかというのが１つ。それから、今、委員の方が、学区の人口が増えている鮫浜小学校学区、城南小学校学区、大井第一小学校学区に来る方は、住みたいとか子育てをしたいというわけで移り住んできているのではないというふうにおっしゃったのですが、そうなのですか。","respondent":"柏木学務課長","answer":"１つは、中間報告ですが、適宜、委員会には、審議の状況等についてはご報告をしたいと考えています。","voiceIndex":64,"id":"exchange-023"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"できるだけ長く期間を取っていただきたいなというのが１点と、それから、やはり周知は、私たちの見解としては地味だなと思っていて、しかるべき方たちには、「今、パブリックコメントを募集中ですよ。ですので、できたら長く取っていただきたいというのと、そういう、今、パブリックコメントを募集中ですというのがいろいろなところで分かるといいなと思うのですが、その辺についていかがでしょうか。","respondent":"柏木学務課長","answer":"最初にパブリックコメントの時期ですが、今、１２月中を予定しているということで、まだ時期等については決定はしてございません。パブリックコメントの期間を長くということと、あと周知の方法については、審議会等も含めて少し検討させていただきたいと思います。","voiceIndex":68,"id":"exchange-024"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"たしか品川区の場合、教育委員会とかに限らず、長くて１か月ぐらいかなと認識しているのですけれども、できるだけ長く取っていただきたいというのと、皆さんがそこにアクセスしやすいような方法は、ぜひ考えていただきたいと思います。それと、これはもう意見です。先ほど安藤委員からもありましたが、私たちもこれは公開されるべきものなのではないかなと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"}]},{"id":"topic-04","title":"自閉症・情緒障害特別支援学級の新設","agenda":"自閉症・情緒障害特別支援学級の新設","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そういった家庭や児童にも手だてを講じるべきではないかと思うのですが、いかがでしょうか。","respondent":"唐澤特別支援教育担当課長","answer":"送迎が保護者の方にとっての負担になるというところにつきましては、こちらは、障害者支援課の移動サポート、そうしたものなども連携しながら対応していく必要があると認識しておりますので、いずれにしましても、保護者の方に丁寧な説明をしながら進めていきたいと考えています。","voiceIndex":75,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。かなり個別なケースでの検討になるとは思うのですが、そういったサポートなども含めて、子どもにとって一番、そこに通いたいのだけれども、なかなか親の状況が許さないとかという場合もあるかもしれないので、そこは子どもの利益最優先で、ぜひ進めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"だから、そういう特別な支援なのだから、そこは本当にその移動支援を、何とかうまく組み合わせていただきたいなと思います。もちろん原則は保護者の送迎というのは、持っておいてもらってもいいと思うのですが、そういう様々な場面で対応をする際には、本当に連携をしていただければなと思いますが、もし最後何かあれば、そこだけ教えてください。","respondent":"唐澤特別支援教育担当課長","answer":"新設するに当たって、就学相談、転学相談等々で説明することにはなっているのですが、特別支援教室も、この対象となるお子さんというのはまず利用する可能性もありますので、そうしたところ含めて、丁寧に説明できればと考えています。","voiceIndex":79,"id":"exchange-028"},{"speaker":"せお委員","kind":"質問","question":"対象者のところで、２番目のところですが、上記の該当があって、それで、「就学相談で自閉症・情緒障害支援学級での指導が必要である」とあるのですが、これが、就学相談で特別支援学校相当だという判断で、でも、保護者が支援学級がいいと言った場合とかはどういった対応になるのか、そこを教えてください。それをお願いします。","respondent":"唐澤特別支援教育担当課長","answer":"ご質問につきましては、知的障害特別支援学級につきましては、特別支援学校に適になった際に、保護者のニーズに応じて学級というような話は出てくるかと思いますので、そちらにつきましては、保護者の方とやはり丁寧な説明、話をしながら進めていければと考えております。","voiceIndex":82,"id":"exchange-029"},{"speaker":"せお委員","kind":"質問","question":"ごめんなさい。少し私の理解がないので申し訳ないのですが、自閉症の方でも知的があったりで、結構そういう方でも特別支援学校ですと言われる方もいらっしゃると思うのですが、そういった方は全然いないという理解でいいでしょうか。ごめんなさい。知的と自閉症、両方持っていらっしゃるお子さんで特別支援学校と言われる方もいらっしゃると思うので、そういったパターンはどういうことになるのですか。","respondent":"唐澤特別支援教育担当課長","answer":"その際は、保護者の方が学級等々を希望する場合については、丁寧な説明をしながら、保護者のニーズに寄り添いながら対応していく、このような形になってまいります。","voiceIndex":84,"id":"exchange-030"},{"speaker":"せお委員","kind":"質問・要望","question":"ごめんなさい、ここの１行目に書いてあるところの知的発達の遅れがないお子さんが、宮前小学校では対象になるということですね。すみません。ありがとうございました。ここは要望しておきますが、そこのところを相談できなかったとか、そこの解決がされないままみたいな方というのは本当に多いので、そこはぜひ丁寧に相談に乗っていただけたらと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"だから、６年になるときに、つまり今度の異動で、もう本当にそういった方が品川区にとどまっていただけるように、教育委員会としてはどのような対応というか、区、都のほうに言っていくのかというところを少しお尋ねしたいのと、現状どういう教員の体制づくりを進めていっているのかという、その２点をお願いします。","respondent":"中谷指導課長","answer":"体制づくりとしましては、やはり今いらっしゃる先生方に、特別支援教育に係る知識をしっかりと研修などの体制でもって身につけていただくということ、また、研修だけでなく、今、免許を取得助成できるという制度もかなり出てきておりますので。","voiceIndex":88,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。最後に１つだけ。今、最後の後段でお話しされた、いわゆる公募制で、品川区で特別支援教育を頑張ってやっていただける方みたいな公募をかけることも可能だと思います。ですから、今度は逆の話ですが、今、課長がおっしゃったように、ぜひそういう指導力のある他区の、他市の先生方を、そういった公募等で呼び寄せるなど、品川区に来ていただくようなことをお願いしたいのですが、最後にそれだけ。","respondent":"中谷指導課長","answer":"先ほど申し上げましたが、他地区から優秀な先生を迎え入れるということは、今お話しいただいた公募制もありますし、いろいろと東京都教育委員会のほうに事前に異動事務の関係で要望を出しまして、そこでかなうというところもありますので、１つの選択肢だけではなく。","voiceIndex":92,"id":"exchange-033"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私もこの送迎のところです。そこに行って、区教委としては保護者の付添いは求めないというのを約束していただいたというふうに認識しております。これは送迎ではありますけれども、付添いと同じように、やはり保護者の負担というのはかなりのものになると思います。生活者ネットワークとしてずっとインクルーシブ教育を求めてまいりました。もし何かコメントがあったら、いただきたいと思います。","respondent":"唐澤特別支援教育担当課長","answer":"やはり安全面を第一に考えてというところで、ここは考えていければと考えています。ただ、保護者の方の不安等につきましては、やはり引き続きこうした就学相談、転学相談の場で丁寧な説明をしながら、対応していきたいと考えています。","voiceIndex":95,"id":"exchange-034"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"もうこれ以上言っても水かけ論になると思いますので、そういうお考えは分かりました。ただ、やはり学校での付添いとかそういうことも求められながら、保護者の方が、自分が付き添いたいとおっしゃるケースもあるのは把握しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-035"}]},{"id":"topic-05","title":"大原児童センターの休館","agenda":"大原児童センターの休館","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改修工事の内容について、もう少し教えていただきたいのですが、よろしくお願いします。","respondent":"大澤子ども育成課長","answer":"今回の改修は、中身だけの改修になりますけれども、大きなところとしては、エレベーターの設置を予定しています。","voiceIndex":102,"id":"exchange-036"}]},{"id":"topic-06","title":"令和４年度子ども・子育て会議","agenda":"令和４年度子ども・子育て会議","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"参考までに、第３回で、その他のところですが、あとは直近の、今年度の第１回にもこういった報告もあったようですが、「今後の子ども家庭政策の方向性と課題～包括的な子ども・子育て支援へ～」とは、ざっと言うとどんな報告をしたのか、どんな内容だったのかというのを、少しお聞かせいただければと思います。","respondent":"今井保育教育運営担当課長","answer":"こちらにつきましては、子ども・子育て会議の副会長の方に、子ども・子育てに関する新制度の説明、国の動向ですとか、こども大綱の策定に向けた動向、その他の保育の役割についての説明など、区で作成する子ども・子育て支援事業計画全般的に関わる今後の動きなどについて。","voiceIndex":108,"id":"exchange-037"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"せお委員","kind":"質問","question":"質問ですが、行政視察において、多様な家族の形だったりライフスタイルの形だったりに合わせて、１泊にするとか、そういった対応というのは可能なのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"視察の先の検討など、これから具体的にはあるわけですし、先に２泊３日というのを無理に決めなくても、その視察先の検討の議論の中で、これは１泊でもいいなとかそういうことになれば、それはそれで、そういうふうな対応、話の議論の中で、正副の最後は決定になるわけですが、決めていくということも、私はやっていただきたいと思いますし、その議論の中で様々な委員の事情などもあるでしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-039"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今、委員長も質問の概要をまとめていただいて、昨日も言ったので、あえて繰り返す必要はあるのかなと思うのですが、言うにはいいのですが、繰り返さなくていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"この学校いじめ対策委員会というのは、ふだんから設置をされていたということなのか。そこはどうなのかというのを伺います。やめるどころか逆にエスカレートしていくことにもなりかねないので、その説諭の内容についてもっと検証すべきだという質問もあったのですが、そういう考えというのはないのでしょうか。もうこれで終わりということなのでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"しっかりと一人一人の教員に対応方針が行き渡らなかったがために、教員個々が、それぞれが対応している、自分の考えで動いているというところが見られましたので、この学校いじめ対策委員会で決めた方針がしっかりと一人一人の教員まで伝わるような対応ということが。","voiceIndex":127,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。なので、そういう教員同士の話合いというのを重要視していただきたいと思うのですが、これは要望とともに、そういったことを今後強化していくというお考えというのはあるのでしょうかというのを、最後に伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ベテランの教員や若手の教員、様々学校組織の中である中で、一人一人が共通認識を持って、１人の子ども、または学年、学校全体の生徒たちを守っていくという視点では、非常に重要だと思いますので、そういった教員同士の話合いの中で知恵を見いだしたり。","voiceIndex":129,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"方向性を決定したというのはかなり重いことなので、それが補助執行の範囲を超えていないというのは、少し納得はいかないところがあるのですが、改めて確認させていただきたいのは、つまり今の時点では、伊藤幼稚園等の廃園というのは、あくまで方向性が決まっているだけであって、廃園が決定しているわけではないのですよねということが１つ、それを確認させていただきたいのと、それと。","respondent":"柏木学務課長","answer":"閉園の決定は、正式には幼稚園条例の改正がされるというのが前提でありますので、今は廃園の方向性が示されているという認識でございまして、最終決定につきましては教育委員会に権限がありますので、教育委員会のほうで決定するということになります。","voiceIndex":142,"id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問","question":"正式な決定は教育委員会が条例改正をするということなのですが、一般質問でほかの答弁も聞きましたけれども、正式な決定でないのに、ホームページで発表したり、保護者の方へ説明したり、また、変更して１年延ばすというふうにされたわけですが、正式な決定をしていないのにそういう周知とか、そういうことができるものなのでしょうか。","respondent":"立木保育課長","answer":"ですので、早めに周知した上で、手続的なところは教育委員会で権限を持ってありますので、事務手続上のところは、その権限を持っているところが行うということで、実際の実務の部分、運営の部分に関する条件整備のところは、子ども未来部が補助執行を受けている中で。","voiceIndex":145,"id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、条例を改正して正式に決定する前に、閉園に向けてのいろいろなことは、早めに区民の方に知らせるために、通知というか、周知することができるという認識でよろしいですか。","respondent":"立木保育課長","answer":"方向性を定めておりますので、その方向に進めていくために、順次、その説明とか周知を進めているところです。","voiceIndex":147,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、令和６年度の募集をいつにするのか、いつ周知するかということですね、特に伊藤幼稚園。そのときに、今までの経緯からすると、新４歳の方は中止します。５歳の空きを募集しますという表現になるのかなと思うのですが、それも、教育委員会の条例改正がないままに、ホームページに載せるということでよろしいですか。","respondent":"立木保育課長","answer":"委員がおっしゃるとおり、令和６年度の入園案内に関しましては、例年１０月ぐらいにお知らせを出しておりますが、伊藤幼稚園の新入園児に関しましては、新４歳児は停止で、新５歳児につきましては、空きがある部分に関しましては募集をかけるという形で行うことを考えてあります。","voiceIndex":149,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"提案","question":"ありがとうございました。何でそんなことを言ったかというと、私は、幼稚園の条例改正が、今回の議会に提案されて、それで、その前に教育委員会が決定して、提案されて、それで、ここで、議会で可決か否決かあれですが、それを受けて、１０月のところでお話しすると思っていたのです。次の議会で、募集に間に合わないわけですよね。そこがどうしても納得いかないのですが、すみません、説明をお願いします。","respondent":"立木保育課長","answer":"実際、いつ上程されるかというところは、また今後のお話になるかと思いますが、既に閉園として出させていただいている伊藤幼稚園に関しましては、令和６年度末ということになりますので、それに合わせて区が閉園の手続を取るというふうに認識しています。","voiceIndex":151,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"いつかということは、では、今度なのか、それとも、何でしょうか、閉園してから出すのですかね。分からないですけれども、その辺、どうしても少し、次の議会で間に合うのかなと思ったのですが、今のお話を伺うと無理だと思うので、そうすると、条例の改正をしないまま、また６年度に向けて進んでいくということになると、どういうふうにお考えなのですか。いつ出すのかというところですね。すみません。","respondent":"立木保育課長","answer":"令和６年度末ですので、今の予定でいきますと、私どもが方針を出している部分に関しましては、令和７年の３月末で廃止という形になると思われます。それに合わせた形で決定を取るというような事務手続になるのかなと考えているところです。","voiceIndex":153,"id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、条例で定められていない形の幼稚園がそのまま、消える形としてはそういうことで、そういう形になるということが分かり切っているのに、それが続くという認識になるのですが、現状の形がなくなっているのに、それを条例で改正していないという形で存続していくという認識でよろしいですか。","respondent":"立木保育課長","answer":"令和６年度までは廃止しませんので、運営もそのまま、在園のお子様は修了まできちんと見るという形になります。修了をもって廃止という形を今のところ考えてありますので、それに合わせて廃止の手続を取るという形だと認識しております。","voiceIndex":155,"id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問","question":"委員長がご説明いただいたとおりなのですが、回収の話で、回収をどのようにして、それで回収されたお金はどこに行くのかなというところです。未納分のお話をしましたが、未納分というのは、給食費が足りなかったのですが、足りなかったのはどうしていたのかなというところで、それを戻ってきたので充てるのか、その後どうするのかというところも含めて、すみません、お願いします。","respondent":"柏木学務課長","answer":"ご質問にお答えいたします。未納者の金額、人数についてですが、昨年度、金額で、未納額は１８万７,６０２円、人数としては８人です。今回の未納額を全体の金額のパーセンテージで言いますと、全体の０.０２％が未納となっているという状況です。","voiceIndex":162,"id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、未納分は、言うなれば事業者さんにお支払いしていなかった部分に充てるとかという形になるということですから、出っ張って出てくるわけではなくということでいいですかね。すみません。","respondent":"柏木学務課長","answer":"回収された未納分の金額については、全て給食食材費に入ってくるです。","voiceIndex":164,"id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問","question":"委員長が説明していただいたとおりですが、そこで、恐らく条件の話が出てくると思うのですが、施策として多くの議員や会派から出ている政策なので重要だと思っていますので、先に行くにつれて、全校に展開していくのかどうなのかというところもあるのですが、試行が１校だけだと、小規模、中規模、大規模という学校があると思うので。","respondent":"大澤子ども育成課長","answer":"試行実施後には、保護者と利用した児童へのアンケート、また対応したスタッフへの聞き取りなどを行いまして、課題を整理した上で、その後の展開を検討していく予定です。","voiceIndex":169,"id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"意見","question":"様々、安全にというか、きちんと仕出し弁当を利用者の方が召し上がれるように、幾つか条件を出していただいたので、これがうまくいって流れができていけばいいと思うのですが、そうすると、今の５つが整わない学校には、なかなかすまいるスクールの長期休業中における仕出し弁当はやりにくいというところは、現実的にあるのかと思うのですが、その点については、現時点の判断で結構ですが、どうでしょう。","respondent":"大澤子ども育成課長","answer":"今の条件をクリアできないとなかなか厳しいものがあると今は考えておりますが、そのことも含めまして、試行している中で、今の条件が本当に全てそろわないとできないのかどうかということも含めて、検討してまいりたいと考えております。","voiceIndex":171,"id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"意見","question":"そうですね。そこら辺を検討していただかないと、あそこのすまいるスクールはあるけどここはということにもなる可能性もあるしということと、もう一つは、逆に、これだけの条件ではなくて、ほかにも必要だというのが出てくると思うので、ぜひ試行の最中で施策が円滑に行くように、今お話があったように進めていっていただければよろしいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":173,"id":"exchange-054"},{"speaker":"吉田副委員長","kind":"質問","question":"今の条件は、すまいるスクールの会場となるところの条件なのですが、例えばその仕出しがどういう業者になるのか、そういう選定のことというのは、どこでどういうふうに検討されていくのか。当然、試行に当たっては相手先が決まっていくのだと思うのですが、その選定についてはどのようにお考えなのでしょうか。","respondent":"大澤子ども育成課長","answer":"事業者を決定するに当たってですけれども、他区の学童クラブ等で実績のある事業者、複数業者に打診をしまして、その中から品川区内でも展開できるという事業者に、現在はお願いする予定です。","voiceIndex":175,"id":"exchange-055"},{"speaker":"吉田副委員長","kind":"質問","question":"分かりました。それはたしか出ていたと思うのですが、他区の実績ということで、特に品川区として独自にというようなことは考えておられないのか。例えばこのすまいるスクールの仕出しの中で、やはり原則、そうするとアレルギー対応とかは、他区の場合はどうされているのか。だから、そういうこともできるような業者を選んでいるのか、その辺のことについて伺いたいのですが、いかがでしょうか。","respondent":"大澤子ども育成課長","answer":"他区の実績でも、仕出し弁当業者で今、アレルギー対応ができるところはないので、品川区の場合も、アレルギー対応はできないということで、保護者の方にはご案内をします。","voiceIndex":177,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":39103,"voices":185}},{"id":"r05-20230704-5","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"総務委員会","time":"午前１０時００分～午後 ０時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"なぜ冒頭だけなのか、理由を伺いたいなと思いますけれども、現に今、本会議では冒頭だけでなく、全ての撮影・録画を許可し、しかも、インターネットでも生中継し、ケーブルテレビにも再放送して、本会議質疑に何ら支障は起きておりませんので、委員会についても本会議場の対応と同様に区民に全ての撮影・録画を認めてよいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"松本委員","kind":"意見","question":"私も前例に縛られず、先ほど、中塚委員から本会議の話がありましたけれども、他自治体においては、委員会のインターネット中継をやっているところもあります。より区民の皆様に区の課題を見ていただくということは極めて重要かと思いますので、傍聴されている方が録画されるということも、冒頭のみならず、全体を録画されるのも問題ないかと思いますので、前例に縛られる必要はないと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"品川区議会も、改革はしていきましょうということは必ずやっているわけなので、私は、今日は前例でお願いしますけれども、必ずそのようなところで議題に上げていただいて、そういうところがないわけではないし、門戸を閉ざしているわけでもないので、よく分かっていらっしゃると思うのですけれども、ぜひそれをお願いしたいと思うし、今日は前例でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-003"}]},{"id":"topic-02","title":"説明に入る前に、各所管委員会における審査の結果","agenda":"説明に入る前に、各所管委員会における審査の結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"補正予算の総合審査ということです。今回の補正予算の特徴や狙いについて、どのようにお考えなのか、少しご説明いただきたいと思います。臨時会でも補正を組まれて、今回も補正が出ております。国や都に引っ張られるように区は予算を組んでいるように見えてしまうので、このようなものはいつ頃から検討されているのかも含めて、ご説明いただきたいと思います。","respondent":"遠藤財政課長","answer":"今回は、通常の会期中の本会議ということで、その部分につきましては、基本的に今回の補正予算で出させていただいたところです。検討の時期ですが、３月の後半ぐらいから、それぞれの所管で検討していただいてあります。そのような形で進めたところです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"これも含めて伺いたいと思います。報道のとおり、今、沖縄県でコロナの感染が増え始め、東京も、全国的にも増え始めている時期にあるだけに、補正予算を今の時点でどう組むかは、いろいろ見通しが立ちにくいということはあるのかもしれませんが、区としても十分な警戒を持っていく、区民にも警戒を呼びかけていく、そのような対応が必要だと思うのですけれども、併せていかがでしょうか。","respondent":"遠藤財政課長","answer":"高齢者の方へのクーラー代の助成というお話をいただきましたけれども、こちらにつきましては、前回の５月の補正予算の段階で、住民税非課税の方への横出しなどをしながら支援をさせていただいていますので、そのようなことを含めまして、総合的にご支援はしてきたです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"クーラーのほうですけれども、現状、考えていないということですが、国や都の交付金や補助金で使えるメニューはあるのか、ないのか、そこだけ確認させてください。使える補助金が国や都であるか、ないかだけ教えてください。現状、ご努力されていることは踏まえながらも、豪雨災害でひどい被害が起きているだけに、対応強化が必要だなと思うのですけれども、その点についても一言伺いたいと思います。","respondent":"遠藤財政課長","answer":"災害に対しての予算というところですけれども、当初予算で組ませていただいているのと、また、災害復旧基金なども積ませていただいて、臨機応変にお金のうえでは対応するです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"豪雨災害については、従来の規模を超える被害が起きておりますので、引き続き、十分な警戒をしていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"総合審査なので、１つだけ。１つは、例えば、建築費で耐震があるのだけれども、これも長いことやっているのだと思っています。それぐらいいろいろな形で使えるといえば、あれも１割補助だけれども、進んでいくわけではないですか。そのようなことも考えるなら、せっかくお金が出ているからやるというのではなくて、もう少し実があるような形で、何かうまく結びつけてほしいなということが１つ。","respondent":"遠藤財政課長","answer":"今回、協議会というところで、まず、これから３年間かけて、協議会と実証実験などをやりながら進めていきたいと伺っておりますので、今後、そのような部分で、こちらは財政面での支援という形になりますけれども、進めるようにしたいです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"２３ページの防災費についてお聞きします。この４０組織、７０組織というのは、どこか限定して考えられているのか、それとも、今はまだ取りあえず、当初はここまでの需要しかないからということで、この予算の割当てにしているのか、お聞かせください。","respondent":"遠藤財政課長","answer":"今回のそれぞれの数字ですけれども、こちらの事業につきましては、３年間で実施するという形で進めしています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"今の発電機の内容ですが、どのような発電機なのか、簡単にご説明願いたい。それから、実際、各組織というのは、地域、町会云々を考えられているのか。それを対象にして、今後、どんどん広げていこうという対応で考えられているのか、少し教えてください。","respondent":"遠藤財政課長","answer":"防災区民組織ですけれども、基本的には、町会が多分イコールになっておりますので、それで２００組織と考えているところです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは要望で申し上げておきます。もう一点。先ほどの部活動地域移行検討というところで、協議会というのはどのような組織なのか教えてください。そして、今後、もちろん話合いをして、今回、実証事業経費ということをここに出しているわけですが、継続できる可能性は担保されているのでしょうか。やはり部活動というのは、一時的ではなくてずっと通年ですので、その辺についてご見解をお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"総合審査ということで、総務の所管なので、少しお伺いしたいのです。常時啓発費が寄附金から出ているということかと思うのですけれども、ここの仕組みをお伺いできればと思うのです。今回、ほかにも寄附金で歳入が入ってきているのですけれども、この指定寄附という制度というか、枠組みなのですか。ふるさと納税などとの違いを少しお伺いできればと思います。お願いいたします。","respondent":"遠藤財政課長","answer":"今回の寄附金は、ふるさと納税の寄附金も１つの形になるかと思うのですけれども、こちらは特に選挙に使ってくださいということで、寄附をする方からのお申出があったというところで、今回。","voiceIndex":35,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"これは、税額控除というか、控除等の関係などはどうなっているのですか。品川区にも、ふるさと納税をやろうと思えばできて、それは、多分、税金の先払いという意味もあるかと思うのですけれども、このような指定寄附というものと、税金、税額との関係というのはどうなっているのでしょうか。お願いします。","respondent":"遠藤財政課長","answer":"ふるさと納税は２,０００円の控除という形になろうかと思います。寄附は、一般的に、当然、上限というものがあろうかと思うのですけれども、基本的に２,０００円の控除が受けられると認識しています。","voiceIndex":37,"id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"今回の指定寄附も、そのようなことは可能なのでしょうか。","respondent":"遠藤財政課長","answer":"恐らく、そのような形で認識しております。","voiceIndex":39,"id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。こういった寄附が行われたということはとてもありがたいことだなと考えています。こうしたことについては、可能であれば、できればホームページなどに公開していただいて、ぜひ区民の方にお願いしますということを周知していただければなと思います。要望で終わらせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのですが、先ほど、何度かお話のあった学校地域連携の部活動のところですけれども、見ると、学校教育補助金というところの支出の部分だと教育指導費で、一義的に学校側がこのお金を使って、協議会を立ち上げて進めていくということだと思っています。その中身は、先ほど、少し質問のあった、町会やボランティア、保護者も含めた地域の方々との会議体であると。","respondent":"遠藤財政課長","answer":"当然、やっていく中で、そちらの予算も考えているところですけれども、今回におきましては、まだそこまで固まっていないというところがあるので、協議会の中で、来年度、再来年度に向けて、予算のつけ方も含めて、どのような形にするか、検討されると伺っているところです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"協議会というところで動き出すと理解しているので、来年、再来年というお話がありましたけれども、早く進めていくという意味では、協議会でしっかりご議論されながら、学校が進めていけると、今度は地域でも進めていけるような予算をしっかりと確保していただきたいなと思ったので、これを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほども述べたとおり、個々の事業は必要な事業だと思いますので、賛成したいと思います。その上で、電気代の補助、コロナへの十分な警戒、豪雨対策をしっかりと進めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"}]},{"id":"topic-03","title":"国連を支える世界こども未来会議 ｉｎ ＳＨＩＮＡＧＡＷＡ","agenda":"国連を支える世界こども未来会議 ｉｎ ＳＨＩＮＡＧＡＷＡ","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"当日の予定の中でワークショップをやられると思うのですが、このワークショップではどのような内容をするのかということ。ＳＤＧｓには１７の目標があると思うのですが、２５分という時間の中で、全体の大枠を説明するのか、それとも幾つか内容を絞って子どもたちに特化して説明するのかということを少しお伺いしたいなと思っていますが、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"先ほど、スケジュールについてご質問いただいたのですけれども、まず、ＳＤＧｓの講義というところですが、今、こちらで連携している、一般財団法人ピースコミュニケーション財団と少し打合せをさせていただいて、どういった講義を行うのか。","voiceIndex":60,"id":"exchange-019"},{"speaker":"澤田委員","kind":"質問","question":"講師はまだ特に決まっていらっしゃらない感じですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-020"},{"speaker":"中塚委員","kind":"提案","question":"初めての事業なので、もう少し説明いただきたいと思うのです。主催の一般財団法人ピースコミュニケーション財団とはどのようなものなのかご説明いただきたいということと、ここでの最優秀グランプリ受賞者は、「第４回国連を支える世界こども未来会議」に品川区を代表して参加できるということですけれども、「第４回国連を支える世界こども未来会議」はどのようなものなのか、伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"令和２年度から、こういった財団の下、この事業自体が実施されたです。","voiceIndex":64,"id":"exchange-021"},{"speaker":"中塚委員","kind":"意見","question":"このような取組なのですね。最後に１点だけ。ｉｎ ＳＨＩＮＡＧＡＷＡのこども未来会議と、「第４回国連を支える世界こども未来会議」に品川区を代表して参加するのでしょうけれども、最終的に報告書なるものは作成されるのか。このような発言だったりといった、終わった後の報告書の作成、あと、参加した子どもの感想などを載せてもいいのかなと思うのですけれども、その点だけご説明ください。","respondent":"吉岡政策推進担当課長","answer":"実施後の報告書の作成というところですけれども、子どもたちがどういった話合いを行ったのか、どういった感想をいただけたのか、そういった実施概要もきちんと報告書としてまとめ上げて、やっただけではなくて、こういった成果も出して、周知を図りたいと思います。","voiceIndex":66,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、お願いというか、お話を伺えればと思います。このようなことをやるというのは、私は、せっかく議場も使って、子どもたちが来てくれるのだから、やはり子どもたちにとっての思い出、将来にわたって、あそこに行ったとき、このようなことがあったと記憶に残るようにしてもらいたいなと思っています。お願いだけしておきます。","respondent":"吉岡政策推進担当課長","answer":"今、委員からお話のとおり、せっかく議場を利用させていただいて、このような機会を設けましたので、当然、集合写真という形で収めたいとは思うのですけれども、いい運用もいたしまして、思い出に残るようにしたいと思います。","voiceIndex":69,"id":"exchange-023"}]},{"id":"topic-04","title":"区民アンケート","agenda":"区民アンケート","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その地域性について把握する狙いについても伺いたいと思います。３点目は、いずれにしても、設問では、この羽田新飛行ルートについて、どのような面で影響を受けていますか、どの程度影響を受けていますかという設問ですけれども、この結果次第では、区長は、国に対して、羽田新ルートの中止を求める考えがあるのか、その点も伺いたいと思います。","respondent":"辻広報広聴課長","answer":"羽田新飛行ルートが１項目だという点ですが、全部で１０問ということで、羽田新飛行ルートのところは、項目としては１項目で４問になっております。全体としては４０％ということで、薄まっているという認識は、私どもは持っていないところです。","voiceIndex":76,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺ったのは、これは区長の指示なのかということを確認させていただきたいと思います。やはり影響を聞く以上、全区民アンケートの結果を踏まえて、国に対して中止を求めるという判断を、なぜできないのか、改めて、その点を伺いたいと思います。全区民に対して、誇りを持っているか否か、その程度を質問しているわけですけれども、この設問の目的は何なのかを伺いたいと思います。","respondent":"辻広報広聴課長","answer":"影響について細かく聞くだけで、中止を求めないのかという点ですが、影響といいましても、影響がある、ない、それが地域によってどのぐらいあるのか、それから、職業や年代など、属性によってどのような影響があるのかということを細かく調べることが今回の目的ですので。","voiceIndex":78,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"この誇りについての全区民調査のことを改めて伺いますが、区民の愛着度を測るというご説明だったと思いますが、区民であることに誇りを持っているかどうかを調査する目的がよく分かりません。改めて伺いたいのですけれども、何を誇りに思うか、思わないか、その基準はそれぞれ内心に関わるものであって、それを区が全区民に聞くことにどのような狙いがあるのか、改めて伺いたいと思います。","respondent":"辻広報広聴課長","answer":"それを分かった上で、各個人がどう思っているか。やはり誇りを持つということは幸せの１つであるし、いわゆるウエルビーイングを高める１つの要素ですので、皆様がどのような心持ちでいるのかということを改めてお伺いするということが目的です。","voiceIndex":80,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"課長は誇りに思うことは幸せの１つだとおっしゃいますけれども、それを品川区が全区民に問うことの意味がよく分かりません。なぜかというと、いずれにしても、アンケートを取って、結果が発表されるわけです。どれぐらいの、どのような結果か分かりませんけれども、その結果に対して、品川区は評価をするわけです。誇りの強制はあってはならないと思いますけれども、その点、いかがでしょうか。","respondent":"辻広報広聴課長","answer":"その結果いかんでは、今、問２の（２）のところをおっしゃっていますけれども、まずは問１の最初のところで、どういったことが重要かという感覚をお持ちだということもお聞きしていますので、もしも誇りに思えないという方が多いのであれば。","voiceIndex":82,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、区民アンケートについて、区長の公約とはいえ、今まで、これだけ大勢の３６万人の区民に対して、品川区はどうなのだろうという問いかけをアンケートとして出すということは、私はすばらしいことだと思います。そして、先ほどから話がありますが、羽田新飛行ルートのことです。ぜひできるだけ多くの方の気持ち、意見を集約して、誇れるアンケートを出していただきたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"１つ、やり方ですけれども、アンケートの４ページのところで、幸福実感度や地域愛着度について、１から５まで、丸が３つまでというところで思ったのは、例えば、「大変不満」、「やや不満」と丸をつけて、ご自身で判断して評価していきます。この１００字については、どのように考えて１００字なのかということを教えてください。何かやり方などを考えているものがあれば教えてください。","respondent":"辻広報広聴課長","answer":"３点、ご質問をいただきました。４ページの幸福実現度や地域愛着度の問１のところです。委員がおっしゃいますように、何か１つの項目に対して、不満だけど重要といったら、それは区としてももっと取り組まなければいけないなという判断をするという使い方をする予定です。","voiceIndex":88,"id":"exchange-029"},{"speaker":"大倉委員","kind":"質問・要望","question":"１００字についてというところで、５ページを見ると、下に大分枠があるからもったいないなと思って、１００字しか答えられないという逆の捉え方をされてしまったらもったいないなと思って、少し伺いました。小・中学校のタブレットを使ってというのは、タブレットを使って、インターネットでスマートフォンから簡単アクセスというＱＲコードを読み込んで使うということでいいのでしょうか。教えてください。","respondent":"辻広報広聴課長","answer":"ＱＲコードを読むということではなくて、タブレット上で答えられるようなものをつくる。この区民アンケートではなくて、小・中学生向けに実際にやったことがあるということですので、それを参考にしながらつくり込みをしたいと考えています。","voiceIndex":90,"id":"exchange-030"},{"speaker":"大倉委員","kind":"質問・要望","question":"修正できるようにしたほうがよかったかなと思ったりして、子どもたちがやるのだったら、そのような間違いもあるかなと思って、少し聞いたのと、修正ができない理由は何かあるのか、教えていただきたい。その点について、教えてください。","respondent":"辻広報広聴課長","answer":"インターネットでの回答は修正できないという話ですけれども、今回のつくり込みに関しましては、最後に送信する前に、大丈夫ですかみたいな、途中でも送ったら、申し訳ないのですが、もうそれで終了です。","voiceIndex":92,"id":"exchange-031"},{"speaker":"大倉委員","kind":"意見","question":"いろいろお考えいただいて、このような形になったということで理解しましたので、ぜひ多くの区民の方がアンケートに答えて、これを区に反映できるように、周知を含めてしっかりやっていただいて、１人でも多くの回答を得られるようにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"伺いたいのは、例えば、では、誇れますという人たちが何％いたときに、それにどのような意味があるのかということを把握する必要があると思います。毎年ではなくて、２年ごとにやってきているものなので、比較ができると思うのですけれども、今回は全体でやってみて、何を基準に、何％だったからどうということを判断していく基準が取りにくいと思うのですが、その辺りはどのように考えていらっしゃいますか。","respondent":"辻広報広聴課長","answer":"よそで同じように実施していれば、その比較も考えられますけれども、そういったものもほぼございませんので、全体として見て、今まで世論調査でやったものと、多少聞き方は違いますけれども、それとの評価もできるかなと思いますが、これ自体で何％だから合格とか。","voiceIndex":96,"id":"exchange-033"},{"speaker":"松本委員","kind":"質問","question":"例えば、ほかの自治体や都道府県、国などで似たようなアンケートがあって、それと比較して品川区はこのぐらい高かったからいいですね、低かったからこうしましょうということがあればいいのですけれども、そういったところで比較するということを考えて、このような問いなのかというのは、どうなのでしょうか。","respondent":"辻広報広聴課長","answer":"このアンケートの制度設計のときに、よその自治体と比較してということは特に考えておりませんでした。区として、これからの区政を進めていく上で、どのようなことが必要なのか、それをウエルビーイングという視点から見ても、まず、現状の心持ちをお伺いする。","voiceIndex":98,"id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"「あなたご自身のことについておたずねします」のところとの関係ですけれども、これまで世論調査の区民の回答では、「品川区に何年ぐらい住まれていますか」というアンケートがあって、その上で、定住性などを考えていくと、もとからずっと品川区に住んでいらっしゃる方は定住性がこうで、最近住まれた方はこう思われていますという判断もある程度できたかと思うのですが、今回は。","respondent":"辻広報広聴課長","answer":"定住性をどこまで入れるかということも、なかなか議論になったところなのですけれども、今回、全数調査をするに当たって、あまり複雑にしてしまうと、回答率が悪くなってしまうということもございました。","voiceIndex":100,"id":"exchange-035"},{"speaker":"松本委員","kind":"質問・要望","question":"最後ですけれども、調査票の案のところで外国語の記載があるかと思います。このアンケート調査票を送られるときに説明の紙がほかにもあって、そこにも外国語の表記があるのかというところをお伺いしたい。これは要望も含めてですが、外国語の記載についてどうなっているのか。ないようであれば、送るときに外国語の表記もしていただきたいと思いますが、いかがでしょうか。","respondent":"辻広報広聴課長","answer":"このアンケート調査票の表書きが１枚あるのですが、そちらには特に外国語は書いていないです。今、実態としては、こちらを開けたところでわかるところです。広報の英語版や、ポケット版のアプリですと、外国語対応もしておりますので、そちらでの周知等を考えているところです。","voiceIndex":102,"id":"exchange-036"},{"speaker":"澤田委員","kind":"質問","question":"今、区民アンケートの注目度が高いこともあって、回収率見込も４５％と非常に高い数字であるのですけれども、これは、過去のアンケートなど、いろいろなものを集計してだと思うのですが、どのように算出したのでしょうか。そこをお聞かせください。","respondent":"辻広報広聴課長","answer":"回収率４５％という点です。今まで世論調査をさせていただいたときに、大体４５％から５０％ぐらいが多かったです。２３区の中でも、世論調査等の回収率が大体４５％ということもございまして、それに合わせて４５％とさせていただきました。","voiceIndex":105,"id":"exchange-037"},{"speaker":"澤田委員","kind":"提案","question":"今、４５％の根拠が分かりました。今回は間に合わないかもしれませんが、また次回の参考にしてみたりということはいかがでしょうかというご提案です。回答した後に、申込フォームでもらえるみたいな形にすれば、アンケートの内容と本人がかぶらないで、ばれないで済むというか、身ばれしないで済むのかなということで、そのようなことはいかがでしょうかというご提案です。","respondent":"辻広報広聴課長","answer":"ＳＮＳに関しましては、通常ですと、始まるときに、アンケートを開始しますというのを１回やるだけですけれども、何回かに分けて、Ｔｗｉｔｔｅｒ等ではご案内をしていこうかなと考えています。","voiceIndex":107,"id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問","question":"今回の区民アンケートは初めて全数ということで、これまでもご答弁がございましたけれども、いわゆる目的としては、行政施策の検討・立案の際の基礎的参考資料。このような目的のためであれば、全数までやらなくても、資料というものはこれまでもあると思うのです。その中で、これをやることになっている中での全数ということを活かした今回の調査のメリット、狙いを改めてお伺いしたいと思います。","respondent":"辻広報広聴課長","answer":"今回、品川区では全数調査は初めてです。似たようなもので、国勢調査は全数調査ですけれども、区としては初めてです。全数調査のメリットとしては、誤差が生じないというのが１点です。それと、区民の意見を丁寧にお聞きすることができることかなと感じています。","voiceIndex":110,"id":"exchange-039"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"答えてくださる方は、多分、全員に聞いているということで、私の意見の一つ一つが区に届くのだという思いで、いろいろ回答してくれる方もいらっしゃると思います。最後に１つだけ確認したいのですけれども、インターネットでのアンケート調査というのは、１人の人が何回もできないようになっているとは思いますけれども、その辺の確認をお伺いしたいと思います。","respondent":"辻広報広聴課長","answer":"インターネットでの回答についてです。本日はおつけしていないのですけれども、１枚目の鑑文のところに、１人に１つの番号とパスワードがついておりまして、それを入力して回答していただくということで、１回やると、もうそれは使えなくなりますので、ひもづけされているです。","voiceIndex":112,"id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"確認","question":"１回なら１回で、今みたいに駄目というのなら分かるけれども、何回でもいいというのは、やはりまずいのではないかというので、私も確認した。だから、そういうものを区もやっているわけで、それはそれでお金の問題もあるのだからしようがないと思うけれども、それはまた少し違った話になってしまうからやめておくけれども、今言ったように、１回ではないから、それは確認したから、絶対間違いない。それだけ。","respondent":"辻広報広聴課長","answer":"今回の区民アンケートに関しましては、そういったことではよくないだろうということで、個別にひもづけをしてやっているです。それから、結果に対する、その後の報告等のことです。そこは、しっかり考えていきたいと思っています。","voiceIndex":115,"id":"exchange-041"}]},{"id":"topic-05","title":"品川区ジェンダー平等の推進に関する検討委員会の設置","agenda":"品川区ジェンダー平等の推進に関する検討委員会の設置","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"今、条例をつくるために検討委員会が設置されていると説明がありました。大きく２点伺いたいのです。裏面の会議スケジュールのところで、パブリックコメントが行われますけれども、少なくともこの時点で、条例案そのものが示されるということなのか、策定委員会を設置しながら、条例の案文自体も最終的には落とし込んで、第１回定例会に提案とあります。それと、２点目。","respondent":"加島人権啓発課長","answer":"他区でもこういった条例についてパブリックコメントを行っている区がありますが、議案そのものをパブリックコメントにかけるということはしておりません。区の認識といたしましては、あくまで議案を示すのは議会に対してと考えております。","voiceIndex":122,"id":"exchange-042"},{"speaker":"中塚委員","kind":"提案","question":"中身については、検討会で多様な意見を反映していただきたいのですけれども、議案については、実際の条文を十分検討できる時間を示してほしいなというところを趣旨として、質問いたしました。提案側としての工夫を求めて終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-043"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ質問。財政はそれでいいのだけれども、そうすると、全体の財政を見るのであれば、財政調整には入らないということですか。財政調整は、もう３００から４００でいいのだけれども、それはそれで、もう触れないという了解ですか。触れるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"触れるのですか。触れると、中身に触れてもいいということですか。どこかで１回ぐらいやるのかという質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-045"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"正副でご検討されたということですので、一言だけ、意見を述べさせていただきたいと思います。コロナの感染状況がどうなるか不安定なところもありますので、感染状況によっては中止の判断。いずれにしても、委員会運営のことですので、できる限り協力したいとは思いますけれども、コロナの対策は十分な警戒が必要だと述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2270#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":47925,"voices":182}},{"id":"r05-20230705-14","meetingId":"r05-cm07","date":"2023年7月5日","dateIso":"2023-07-05","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"前例はそういう対応をしてきましたけれども、やはり冒頭のみではなくて、審議中も含めて写真は認めてよいと考えています。昨日の総務委員会でも指摘したことですが、本会議では、全てをインターネット中継までしている時代ですから、委員会についても、全てを写真撮影してよいかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"確認","question":"庁舎の跡地活用検討委員会ということで、幅広く聴取ということでしたけれども、障害者の団体が、手をつなぐ育成会のみになっておりまして、障害は種別が様々ありますので、そこはちょっと幅広くないなというふうに感じたのですが、なぜ育成会だけなのかというのを伺いたい。なので、そうした方向というか例えばという形で、もうこの委員会では示されるということでいいのか、伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"したがいまして、先ほど申し上げた具体的なそういった事業手法につきましては、また、この検討委員会の結果を踏まえまして、段階的に検討を進めるものということで認識をしています。","voiceIndex":13,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちは、この跡地活用については、区の土地は区民の財産ですので、そうした形ではなく、区民の願い実現に求めるものを建設していく、造っていくということが必要だろうと考えていますので、もう既にそうした民間の定期借地で、そして、区民の財産がそうした企業のもうけを生み出すものに使われていくということになっていってしまうのではないかなと思うので、ぜひそういう形ではなく。","respondent":"泉広町事業調整担当課長","answer":"様々いただきましたご意見の中から、まず、福祉のほうからもう少し団体をですけれども、こちらにつきましては、先ほど申し上げましたとおり、こちらの、手をつなぐ育成会の方々を通しまして、そういったところのお声を広く拾っていきますといったことと。","voiceIndex":15,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、この対話型市場調査の実施案も、内容のところに書いてあるので、検討というか実施案をつくっていくということになると思うのですけど、要するに民間に何を聞くかというのも、この検討委員会で話されるということでしょうか。区民ニーズを幅広く聴取する、そこに民間の方に何をやってもらうかを聞く内容を決めるというのが、何で入っているのかなというのは思うのですけど、何でなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査の内容が、この品川区庁舎跡地等活用検討委員会の内容のところに含まれているですけれども、対話型市場調査の内容につきましては、これも民間事業者の方々の意見や提案といったところを把握するためにやっていくという内容になってありますが。","voiceIndex":17,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"ここでは、その跡地の活用をどういうふうに区民の皆さんが望んでいるかというのを純粋に聴取する場ではなく、私も先ほど言いましたけど、メンバーを見ても、周辺開発を進める、それを期待してのメンバーにも思いますので、そうしたことが、跡地活用と言いながら一層進められる委員会になっていくのではないかなと、そういう検討委員会にはすべきではないと思うのですけれども、いかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査につきましては、先ほど申し上げた検討委員会の最終の段階につきましては、こういった対話型市場調査の結果を踏まえて、区民ニーズとの関連性といったところを整理していく形を取りますので、そういったところもありますから、対話型市場調査につきましても。","voiceIndex":19,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"最後にします。やはりこうした庁舎の跡地、区民の財産ですので、企業のもうけを優先する、そして、貸し付けている間は区民が使えない、区民のためには使えないということになりますし、さらに周辺開発を一層進めていくということになっていきますので、そうした活用の仕方は、私はすべきでないと思っています。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"私から３点お伺いをしたいと思います。区民からの広くニーズを集めるために、区民公募の委員は結構数が多いと思うのですけれども、なぜ今回は区議会からの委員を選ばなかったのかということが１つ。それと、８月３０日に１回目があるということですけど、開催頻度はどれぐらいで行うのかということが２つ目です。その辺りを教えていただければと思います。","respondent":"泉広町事業調整担当課長","answer":"そういった観点から考えれば、令和１０年から速やかに事業に入れるようにといったところはしっかり念頭に置きながら、検討を進めてまいる予定としています。","voiceIndex":23,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"令和１０年から着手ができるように速やかに準備を進めていくということですけれども、繰り返しになりますが、新庁舎と一体的に考えないとなかなか、この現庁舎の跡地活用というところも、全体の動線とか、当然、区役所側は考えていらっしゃると思うのですが、そういったこともこれから、この検討委員会の中で一体的に示されるのかどうかというところを確認させてください。","respondent":"泉広町事業調整担当課長","answer":"こちらにつきましては、検討委員会と並行して行ってまいりますワークショップですとか、対話型市場調査、またはアンケート、そういった内容との整合性を図っていきますと、やはり５回が適切ではないかということで、区としては捉えているところです。","voiceIndex":25,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"確認","question":"最後の部分だけもう１回確認ですけれども、この庁舎跡地等活用検討委員会の中で示される資料の中に、それは当然こちらの行財政改革特別委員会の中でも示されるという前提なのですけれども、いわゆる、今の新庁舎とかＪＲとかの広町の跡地と、その一体的な考え方というものがこれから示されるという認識でいいのか教えてください。","respondent":"泉広町事業調整担当課長","answer":"今おっしゃいました、庁舎一体的なまちづくりが示されるのかですけれども、今この第１回の検討委員会の中でも現状の整理ということで、現在進めている民間の開発でございましたり、新庁舎の増強でございましたりといったところは、しっかり共有させていただきまして。","voiceIndex":27,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"前回の策定委員会の早川委員長は、一番よく分かっていらっしゃるのかなと思っているのですけども、跡地等活用検討委員会においても、策定委員会で出たものが当然反映できると思うので、新しい学識経験者が２名委員になられるのですけれども、どういういきさつで大島先生だけが残ったのかということを教えていただきたいと思います。","respondent":"泉広町事業調整担当課長","answer":"こちら、大島教授を今回選定させていただいた経過ですけれども、まず、専門が社会教育、生涯学習といったことで、そういった分野での専門的な視点が、今、区民ニーズを捉えていくという場面では非常に重要になってくるだろうというところの観点から。","voiceIndex":30,"id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それは分かるのですけども、早川教授はすごくそれが反映できると思ったので、私の個人的なことで、それは、前策定委員会の、今までおられた方には、今回の活用検討委員会では当然選出されていませんけども、その前のとはいろいろと反映できるものはあるのですか。前回のメンバーの人たちにも幅広く告知できるような報告というのは考えていらっしゃるのですか。","respondent":"泉広町事業調整担当課長","answer":"現状では今、庁舎の委員の皆様に、こういった情報をお渡しして何かしらの情報を得るといった仕組みは考えてございません。今いただいたご意見を踏まえまして、今後検討してまいりたいということで考えてあります。","voiceIndex":32,"id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ検討をよろしくお願いします。もう１点なのですけども、事務局側で、これまで和氣副区長がメンバーになっていましたが、今後、この活用検討委員会ではどういう体制でいくのか、副区長が不在の中でいくのか、あるいは、これまでのどういうふうな状態でいくのかというのを教えていただきたいと思います。","respondent":"泉広町事業調整担当課長","answer":"事務局側の構成といったところですけれども、今まさに検討しています。事務局側の構成につきましても、整ったところでご報告をさせていただきたいと思ってあります。","voiceIndex":34,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区庁舎跡地等活用検討委員会ということですけれども、この検討委員会が今後は様々検討を進めていくという説明がありましたけども、この検討の前提条件になるものは何かと伺いたいと思います。公共性というのは、この一連の流れを聞くと周辺の再開発に寄与するものを目指すということなのですか。この収益性と公共性とは何を指しているのかも併せて伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"官民連携手法の導入を視野に入れた新庁舎整備に際する区民負担の実質的な軽減といったところで、こういった官民連携手法を導入していくといったことと、区民ニーズをかなえるといったことは、前提条件として進めてまいりたいと思っているところです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"収益性のことについて区民負担の軽減ということですけれども、つまりはこの跡地を活用して、財源を生み出すという考えがあるのかどうかを確認させてください。それとあと、事務局についてですけれども、決まり次第ということですが、８月３０日までには当然決まると思いますので、決まり次第委員会に報告していただきたいと思いますが、いかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"収益性を前提とするならば福祉の機能はそこへ入らないのかといったところのご意見ですけれども、今回は、先ほど申し上げました収益性と公共性の両立を目指していくという中では、今。","voiceIndex":39,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、公共性の中に含まれるというお話がありましたけども、やはりこの前提条件では、特養ホームはつくれない、障害者グループホームはつくれない、そのほか福祉施設はつくれないということになってくると思いますが、いかがかということと、そういう前提はやめるべきだと私は思いますが、いかがでしょうかと。","respondent":"泉広町事業調整担当課長、大友新庁舎建設担当課長","answer":"こちらにつきましては、今後、この検討委員会からの検討業務の中でも、様々、その他自治体の事例調査や対話型市場調査の結果も踏まえまして、検討を進めていくというものでございまして、そういった検討の中で。物価上昇や費用対効果を含めたＺＥＢ対応化などで価格の上昇が見込まれるという現状におきまして、今こちらのほう、設計とともに精査している状況です。","voiceIndex":41,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"現庁舎跡地に福祉施設のことについて、今のご説明ですと、対話型市場調査の中でも検討していきたいというご説明だったと思います。それとも、何か別の方法もあるというのか、ちょっと今の説明を私は初めて聞いたので、どういうことなのか伺いたいと思います。区民の財産を使って、区が財源をいただくだけだというようにしか思えないのですけども、いかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"財源に関わるものですけれども、こちらにつきましても、区民負担の実質的な軽減を目指していくですので、そういった手法を様々検討しています。","voiceIndex":44,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"そうした区民の財産を使って福祉施設を排除するような、こうした計画はやめるべきだと、述べておきたいと思います。それと最後に、第１回の跡地活用検討委員会ということで、これから考えるのだと言いますけども、実際はもう決まっているのではないですか。この現庁舎跡地にこういうものをつくりますということが決まっているのではないかと私は疑っているのです。疑っているだけです。あるのではないかと。","respondent":"泉広町事業調整担当課長","answer":"これまでやってまいりました検討につきましては、まちづくりの観点から進めてきた検討といったところになってございまして、庁舎跡地等の活用に関しましては、まさに今後検討を進めていくところで、現時点で施設が決まったものではございません。","voiceIndex":46,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"現時点では決まっていない、そうですね、品川区としては決定はしていない、それは事実だと思います。私が伺ったのは、日建設計が品川区に示したものがあるのではないかと伺いました。なぜかというと、業務委託ですから、何らかの成果物を品川区に提出しているのです。これは事実です。ではなくて、日建設計が品川区に示したものがあるのではないかと伺いましたので、改めて伺います。","respondent":"泉広町事業調整担当課長","answer":"繰り返しのご答弁になりますけれども、先ほど申し上げましたとおり、まちづくりの観点から検討をこれまでしてきたものでございまして、現在そこのところにつきましては、決まったような施設といったところはございません。","voiceIndex":48,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"そろそろまとめたいと思うのですけど、繰り返しの答弁になるのは、繰り返しのことしか言わないからなのです。だから、区が決まってないのは認めています。区が跡地活用で、アリーナを造りますなんて決定はまだされていません。それは事実です。だから、今の答弁は決まってないということは事実です。私が聞いているのは、日建設計が何か示したものがあるのでしょうと。あるのかないのかを最後に伺いたい。","respondent":"多並広町事業担当部長","answer":"したがいまして、先ほどの、今まで検討したことがあるかないかという話ですが、それはまちづくりを検討する中で種々いろいろな検討をしてきたという中でやってきましたけれども、それは一度令和２年に決定したものでありますので、今後はそれに基づいて具体的な検討をこれから。","voiceIndex":51,"id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"品川区は示されていないとは言わないところが、結局示されているのだと思います。こうした住民不在、開発業者優先、中身も説明もしない、既にもう示されている。こういうのは一からやり直すべきだと思います。しかも、特養ホームとか障害者グループホームを初めから排除する、こんなことは決して許されないと、強く指摘して終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"もう一つ、１０名ということですが、各団体の参加者は１名ずつということでよろしかったでしょうか。もう一つが、区内の関係団体の中に青稜中学校・高等学校と含まれていますが、これは子どもたちからの視点と観点ということから、学校の校長先生なのか、それとも、例えば生徒会とか子どもたちの代表なのか、その辺について伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"こういったところとも連携して進めていきたいということで考えているところです。区内関係団体が１名なのかといったところですけれども、これは各団体１名のご推薦をお願いしています。","voiceIndex":55,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問・要望","question":"理解いたしました。もう一つが、区民公募についてなのですが、これは７月１０日まで募集ということで、もう間もなく締切りになるかと思いますが、今現在、大体何名ぐらいの方から申込がされているのでしょうか。分かる範囲でいいので教えてください。その選定方法ですが、幅広い年齢層の区民の方にご参加していただきたいと思うのですが、区としてどのような形で選定されていくのかお知らせください。","respondent":"泉広町事業調整担当課長","answer":"もう一点、選考の手順ですけれども、今回選考に当たりましては、これまでのこういった委員会での経験でございましたり、また、作文を書いていただいてありますので、そういった作文の内容を踏まえて選考していくです。","voiceIndex":57,"id":"exchange-022"},{"speaker":"松本委員","kind":"質問","question":"改めてなのですけれども、ワークショップ・対話型市場調査を実施するということですけれども、この調査をする場合の、対話する内容、今のところ想定されているところをもう一度お願いできますでしょうか。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査も同様に今後検討といったところになりますけれども、今回何か、業態ですとか事業スキームといったことを限定せず、多くの意見をいただけるような仕組みといったことで展開していきたいと考えているところです。","voiceIndex":61,"id":"exchange-023"},{"speaker":"松本委員","kind":"提案","question":"例えば他の自治体でも、高層ビルの中に福祉施設が入っているというふうなものがあるというのは、もうご承知のとおりかと思いますので、例えばこの、対話の内容の中に、これは実際には、検討委員会の中でご議論いただくことかと思いますけれども、事務局として、このワークショップ・対話型市場調査の実施案をこの検討委員会で検討していただく中で事務局の考えとして。","respondent":"泉広町事業調整担当課長","answer":"ワークショップや対話型市場調査を行うときに、福祉ですとか公共性の高いところも部分的に入るといったところも踏まえた、そういった提案がなされるような仕組みですけれども、今回の内容につきましては。","voiceIndex":63,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"区内関係団体の中で、青稜中学校・高等学校がありますけれども、跡地の近くの学校だと思いますけれども、この私立の青稜中学校・高等学校を区内関係団体の中に入れた理由というのは、何かあるのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"青稜中学校・高等学校を団体に含めたといったところですけれども、こちらにつきましては、やはりこの庁舎周辺の一体的なまちづくりを考えたときには、その一帯のまちづくりの直近にあります、こういった学校を含めまして、そういった子どもたちも。","voiceIndex":66,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"地理的に、一体ということを検討するに当たっては、この青稜中学校・高等学校の方を参加させるということは理由が立つかなと思っているのですけども、教育的観点という意味ではもうちょっと、品川区全体を捉えるところ、青少年問題協議会がありますけれども、そうした全体の教育的観点という意味ではほかの団体とかはあまり検討されなかったのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"教育的な視点での団体といったところのご意見です。教育的な視点ですが、庁内、教育委員会にとっても、この検討を進める中では連携をしながらそういったご意見を補足していくといったことを考えてございまして、その他の教育関係の団体につきましては考えてございません。","voiceIndex":68,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。教育委員については教育委員会、この委員会の中に入っていなくても教育委員会とも連携をされていくと。新庁舎整備でも、ご意見募集フォームだとか、そうしたことを行ってきたかと思います。当然検討委員会が主体となって決めていくのだと思うのですけれども、幅広くいろいろな区民の方々、また、専門的な団体の方々のご意見を取り入れていく、その仕組みというのは検討されているのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"今、新庁舎でやってあります、ご意見フォーム等の取組もありますので、そういったところも参考にしながら、多くのご意見を聴取できるように努めてまいります。","voiceIndex":70,"id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"私からは、１点、追加で聞かせてください。この５回でおのおの何を話すのか、具体的に何を議論するか、話を進めていくかというのは決まっているのでしょうか。決まっていたら概略を教えていただきたいです。","respondent":"泉広町事業調整担当課長","answer":"テーマにつきましては、こちらも検討といったところになってありますので、次回、第１回の検討委員会の内容をご説明する中で、それぞれのテーマにつきましては概要をご説明させていただきたいと考えています。","voiceIndex":73,"id":"exchange-028"},{"speaker":"山本委員","kind":"質問","question":"ぜひ、第１回の後にお聞きできればと考えています。この５回の中で、中身のある議論をしていただいて、各関係団体からの意見を聞いていただくとともに、ほかの委員の方からの発言もありましたけれども、ワークショップやアンケート調査を有効に活用いただいて、多くの区民の皆様の意見を聞いていただくこと、そして適切合理的な判断を導くことを期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-029"},{"speaker":"せお副委員長","kind":"質問","question":"１点だけ、今、ほかの委員からも様々ありました、例えば防災の観点からとか教育の観点、あと、福祉の観点と、そういったところは区内の庁舎内で連携していくというお話だったのですけど、そこの連携の仕方というか具体的に何かありましたら教えてください。","respondent":"泉広町事業調整担当課長","answer":"こちらは今、具体的に庁内の、例えば検討委員会をつくってみたいなところはまだ考えてございませんけれども、いずれにしましても、連携といったところで様々ご意見をいただく場をつくってまいりたいと思ってありますので、これも引き続き検討する中で。","voiceIndex":77,"id":"exchange-030"},{"speaker":"塚本委員","kind":"確認","question":"１点確認なのですけど、ここの旧荏原第四中学校跡地は、もともと、ここにも書いてありますけれども、地域の避難所としての活用がなされているということで、一応、このスケジュールでいくと令和７年度までは暫定活用、そこから先が本格活用のためにということで、令和１１年度、これ併用となっていますけれども、この間、区民避難所としてここは使えなくなるということに恐らくなるのだろうと思うのです。","respondent":"吉岡政策推進担当課長","answer":"地域との説明、施設との話合い、実際の防災訓練、そういったところをしていくということが必要になってくるかと思いますので、こちら、地域、あるいは防災課、そういったところで連携しながら、地域の方にもご理解いただきながら、しっかりと運用できるようにというところで。","voiceIndex":84,"id":"exchange-031"},{"speaker":"塚本委員","kind":"確認","question":"これは、今後はどちらかというと防災課主管で進めるということでよろしいですか。そこだけ最後確認させてください。","respondent":"吉岡政策推進担当課長","answer":"委員のおっしゃるとおり、こちら防災課あるいは地域、地域センター、避難所連絡会議等もありますので、そういったところでしっかりと話し合っていただいて、準備を進めていくというような流れになろうかと思います。","voiceIndex":86,"id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問","question":"ほうさん保育園と一本橋保育園、これが令和６年の３月で移転ということで解体されたときに、大体この解体はどれくらいかかるのかというのが１点と、例えば解体した後にここが、要は更地になるというか何もなくなる状態の中で、令和８年度からいろいろ工事とかある中で、この後はもうそのまま、更地にしていくのか、それを教えてください。","respondent":"吉岡政策推進担当課長","answer":"こちらは解体後更地というところになりまして、その後、何か建つですとかといったものは特に決まっていないのですけども、今後運用する中でうまく、そのまま活用できるようなところがあれば、考えていきたいというふうに考えてあります。","voiceIndex":89,"id":"exchange-033"},{"speaker":"まつざわ委員","kind":"意見","question":"ぜひ、今やられている旧荏原第四中学校の検討委員会でしたか、ああいうところでも、ただ真っさらにしておくだけでは何なので、地域とのコミュニケーションの中で何か活用を見いだしてくれればいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"ご説明あったとおり、令和６年以降も引き続き暫定活用を継続したいということですけども、この点については了解をしたいと思います。１点伺いたいのですけども、資料では令和８年度から本格活用のための設計・整備工事等と書かれておりますが、本格活用の概要が示されるのはいつ頃なのか、令和６年、令和７年、どの時期なのかお伺いしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"令和６年度は基本計画、令和７年度は基本設計、令和８年度は実施設計、令和９年度、令和１０年度のところで整備工事ということで検討しているようなところです。","voiceIndex":93,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"方針は今年度作成されるということですけども、旧荏原第四中学校跡地に何ができるのかという概要はそこで示されるということでよいのか、改めて確認させていただきたいと思います。ぜひ進めていただきたいと要望したいと思いますが、併せていかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"まさに今年度、ワークショップ、あとは跡地活用の方針策定委員会、もちろん、それまでの地域からの要望、そういったものも踏まえまして、基本方針を検討していくという形になりますので、そういったところでしっかりと進めていきたいと考えています。","voiceIndex":95,"id":"exchange-036"},{"speaker":"筒井委員","kind":"確認","question":"この旧荏原第四中学校跡地活用方針策定委員会の区民委員の募集とかは終わっていると思うのですけれども、委員について、どういう方で構成されるのかというのは、まだ発表はされていないでしょうか。確認で伺います。","respondent":"吉岡政策推進担当課長","answer":"発表というところでは、実は来週の７月１０日に第１回の跡地活用方針策定委員会を開催するということで、こちらは広報等にも掲載をさせていただいているところではあるのですけれども、今申し上げすると、学識経験者の方が２名と。","voiceIndex":98,"id":"exchange-037"}]},{"id":"topic-02","title":"令和５年陳情第１４号、広町地区土地区画整理事業に係る品川区合意を事前に区議会に報告するよう求める陳情","agenda":"令和５年陳情第１４号、広町地区土地区画整理事業に係る品川区合意を事前に区議会に報告するよう求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"関連資料であります広町地区のまちづくりについての中で若干伺いたいと思います。土地区画整備事業の概要ということで、事業費が約１１５億円と記載がありますけれども、この１１５億円というのは具体的に何の費用なのか、道路とかインフラとかそういうことなのでしょうか。ちょっとよく分からないのでご説明いただきたいのと、この１１５億円というのは誰が幾ら負担するのか、ご説明いただけますでしょうか。","respondent":"泉広町事業調整担当課長","answer":"事業費でお示ししております約１１５億円のご質問です。こちらにつきましては、委員ご指摘のとおり、道路といった基盤整備に関わる費用として、約１１５億円がかかってまいるといった内容です。","voiceIndex":106,"id":"exchange-038"},{"speaker":"中塚委員","kind":"確認","question":"約１１５億円は、道路等の基盤整備ということで、道路を敷設したり、電柱を建てたり、電気やガスや上下水道や、そういうものということで、いわゆるＪＲ東日本や新庁舎や庁舎跡地の建物部分は含まれていないということでよいのか確認させてください。それともう一つ、誰がどう負担するのか、このＵＲが譲渡してというところで、私の不勉強もあってよく分からないので、もう少しご説明いただけたらと思います。","respondent":"泉広町事業調整担当課長","answer":"先ほどの費用捻出ですけれども、今回の土地区画整理事業につきましては、それぞれの土地権利者がそれぞれ土地を出し合って、保留地の設定ですとか、基盤を整備するところの道路の用地をそれぞれが出し合っているといったところになってございまして、その中で。","voiceIndex":108,"id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"今の約１１５億円のところですけれども、いつの時点でこの約１１５億円という数字が出てきたのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"約１１５億円と数字が示された時点ですけれども、こちらは令和４年６月２８日の建設委員会の資料といたしまして、約１１５億円の事業費といったところをご提示したものです。","voiceIndex":111,"id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"先ほどの、この約１１５億円を誰が負担するかというところで、ＵＲが保留地を譲渡、売却かと思いますけども売却するなどして確保していくというところですが、これ仮に、この約１１５億円の市場、どのくらいなのかというのはなかなか我々も分からないところなのですけれども、仮にこのＵＲが保留地を譲渡するときに、約１１５億円に足らなかった場合というのは、これは区の負担は出てくるのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"こちら、事業費、売却をしたときに約１１５億円が足らなかったらといったところですけれども、これはまた、事業の終盤に差しかかった段階で、そういった資金の精査を図ってまいりますので、そういった中で整理がなされまして、ＵＲ都市機構のほうと検討。","voiceIndex":113,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"それは、これからというのはなかなかちょっと、不思議かなと思うのが、何かしらこういう計画をつくるときに、ある程度の将来のリスク負担は検討してやっていくのが通常ではないかなというふうに思うのですけれども、それは、現段階では全く検討されていない、これ、約１１５億円で足りない場合に誰がどう負担するのかということが、全く現時点で協議されていないということなのでしょうか。","respondent":"泉広町事業調整担当課長、多並広町事業担当部長","answer":"この約１１５億円の部分に関するご質問ですけれども、この約１１５億円、その売却をするといったところの計画につきましては、将来的なまちづくりがなったときの、そのまちの在り方を見てそういった費用が出されているといったことと。ただ、これは具体的にはその事業者である、施行者であるＵＲ都市機構が、基本的にはそこについては全て、手続をこれから行っていきますので、権利者という立場でそれはこれから調整していくです。","voiceIndex":115,"id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"それで、この資金計画のところが、この陳情の中で出てきているかと思います。とにかく資金計画はとても大事なものかと思うのですけれども、これまでこの資金計画について、議会で区から説明というのはなかったというふうな記述がされておりますけど、なかったということでよろしいのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"こちらにつきましては、施行の認可後に、縦覧が必要になってくる図書といったところを基本としながら、これまでご説明をさせていただいたです。","voiceIndex":118,"id":"exchange-043"},{"speaker":"山本委員","kind":"質問","question":"行政として一般的なのでしょうか。分かれば教えてください。それから、行政財産の処分等は議決案件になるということは、これも陳情文に書かれていますが、品川区では、品川区が行政財産を含む土地区画整理事業をする場合、議決案件となるものなのでしょうかというところで教えてください。","respondent":"泉広町事業調整担当課長","answer":"地方公共団体が施行した場合の一般的な考え方といったところですけれども、これは、事業計画を縦覧しなければならないですとか施行規程を条例で定めるといったところは、土地区画整理法の中で定められているです。","voiceIndex":121,"id":"exchange-044"},{"speaker":"山本委員","kind":"質問","question":"認識にそごがないように、繰り返しになってしまうのですが、２つ目のほうの回答なのですけれども、今回、ＵＲが施行者であるので議決案件ではないということへの質問ではなくて、市区町村が直接、この土地区画整理事業をする場合だったらどうかということをお聞きしたいのですが、それでも変わらないということでよろしいですか。","respondent":"泉広町事業調整担当課長","answer":"現在の広町事業につきましては、個人施行で実施しているものですけれども、今、委員からご質問があった、地方自治体施行になった場合に、換地という行為が議決事項になるのかといったところですけれども、土地区画整理上の換地といったことになりますので。","voiceIndex":123,"id":"exchange-045"},{"speaker":"山本委員","kind":"意見","question":"今回、この事業の進め方が、関係当事者が多いということでＵＲが施行者となっているものと理解しております。ですので、今回、陳情者の方がおっしゃっているところが法令上、そのルール上、特に議決は必要ではないということであっても、やはり、同程度の開示は必要ではないかというところで考えました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-046"},{"speaker":"松本委員","kind":"質問","question":"これは、ある程度事前には、どうするのかというのは決まっているかと思うのですけれども、この点についてどのように決まっているのか、どこで決まっているのか、その決まっている点について議会でのご報告はあったのかお伺いいたします。","respondent":"泉広町事業調整担当課長","answer":"そういったことは基本協定の中で定められてありますけれども、区議会のほうにはその協定の内容につきまして、個別にご説明をした経緯はございません。","voiceIndex":127,"id":"exchange-047"},{"speaker":"筒井委員","kind":"質問","question":"この陳情書の２ページにある、この図表が分かりやすいかなと思うのですけれど、港区の田町事業で、この品川区の広町事業、例えば田町事業は事業計画書の案を出したというところと、品川区で広町事業では事業計画書概要案を提示したとか、いろいろこうした違いがあるのですけど、田町事業ではかなり詳細にやっているのかなと思うのですけども、品川区の広町事業で、田町事業と比べて。","respondent":"泉広町事業調整担当課長","answer":"広町事業と田町事業につきましては、それぞれ権利者の構成も異なりますので、そういったやり方は様々なのかということで認識しています。","voiceIndex":130,"id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"陳情者の方が言われている、どこまで報告するのかというところでの、もっとつまびらかにということなのですけれども、現状、私自身もこの広町の件に関して、これまで、議会に区のほうから説明は一定程度されて、適宜されているわけで、また、身近な区民の方から直接このことについて、こういったより詳細な、陳情をされているようなレベルにおけるような、説明を求めたい、知りたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-049"},{"speaker":"山本委員","kind":"意見","question":"しながわ未来では、情報公開を進めていくべきだと考えております。そして、品川区でも、大井町駅前の一等地である、この行政財産の本事業については、透明性、公平性、また、事前にしっかりとした意見聴取を持って進めていくべきだというふうに考えております。当該事業は、品川区にとって大きな行政財産の再開発であって、やはり、事前により丁寧な説明を行っていくべきだというふうに考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"本日結論を出すということと、趣旨採択でお願いします。理由ですけれども、現庁舎跡地について官民連携手法の導入は行うべきではありません。ただ、区民の方が、より丁寧に議会にも資料を出してほしい、丁寧に説明をしてほしいと、その趣旨はよく理解できますので、趣旨採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-051"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すということで、不採択とします。ご説明があったように、品川区としては議会に示したという点と、港区の田町事業との違いがありますので、この陳情を採択するまでの合理的な理由はなかったと判断をいたしました。ただ、この陳情者のお気持ちも分かる点がありますので、今後は、この行財政改革特別委員会等々で、議会に丁寧なご説明を求めていきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-052"},{"speaker":"松本委員","kind":"確認","question":"本日結論を出すで、採択でお願いいたします。本当に個人情報が書いてあるようなものであれば、出せないということは分かりますけれども、そうでもないというものが幾つかあるということが本日、確認した中でも分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"採択というふうに申し上げさせていただきましたが、陳情者の意向を考えるならば、きちんと議会で、少しでも陳情者の意向に沿う形というのが重要かと思いますので、当会派としても趣旨採択と意見を変えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":33286,"voices":147}},{"id":"r05-20230706-19","meetingId":"r05-cm07","date":"2023年7月6日","dateIso":"2023-07-06","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時４５分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"避難計画のところで伺いたいのですけれども、まず、確認なのですが、１番のところに在宅避難者とあって、住宅等の被害を受けているということが書かれているのですけれども、物資の関係で言えば、自宅に避難している方も支給はされると思うのですけれども、この在宅避難者というのはそういった方も含めたものなのか、そこを伺いたいと思います。連絡会議ごとの交流というのはされているのかどうか。","respondent":"平原防災課長、菅野高齢者福祉課長","answer":"そういった点で、在宅に避難されている方につきましても、当然物資の支援対象ということで私どもは考えてありますので、そのような形で対応させていただきたいと考えています。続きまして、避難の流れについてです。私のほうからは、福祉避難所における運営マニュアル等の整備についてお答えします。福祉避難所とは、区民避難所で他の避難者と共に生活を送ることが困難で、あらかじめ指定した避難行動要支援者を受け入れる、現在４３施設あります。","voiceIndex":13,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこだけ確認させていただきたいと思います。それで、在宅避難者については、住宅の被害を受けていない人も在宅避難者に入るということですね。分かりました。ぜひやっていただいて、いろいろな取組をやっていると思うのですけれども、狭いところだけでなく、より多くの取組を交流していただいて、より実践的な、実効性ある避難所運営訓練をしていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長、平原防災課長","answer":"令和２年度から福祉部では、災害時検討というのを進めておりまして、そこで４３の福祉避難所についてそれぞれ職員を割当てさせていただいて、現地といろいろやり取りをしている最中です。避難所連絡会議を超えての交流といったところですが、避難所連絡会議を地域別で集合させたものといたしまして、防災協議会という枠組みがあるのですけれども、地区別の防災協議会で総会を開いておりまして。","voiceIndex":16,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"備蓄についてなのですけれども、この間いろいろ拡充などされておりますけれども、簡易間仕切りのことで、全ての避難所に既に配備できるようになっているのか確認させていただきたいのと、あとテントですね、この間も災害が起きた時、各地ではテントを張ってやっているわけですけれども、品川区としてもぜひ導入していただきたいと思うのですが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長、平原防災課長","answer":"今、都の物資を一時的に民間倉庫のほうに保管できないかという協議を進めておりまして、そうすることで２日目、３日目以降の都からの物資を早急に、必要な場所に届けられるという体制が整いますので、こちらは今。東京都の物資ですけれども、大きくは２日目、３日目というお話になっているのですが、東京都でも都内各地に備蓄倉庫を持っておりまして、それぞれ分散と集中の考え方によって物資を管理していますが、例えば。","voiceIndex":19,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"備蓄のところでは、間仕切りは全ての避難所に５０台はあるということなので、地震の際にも間仕切りは、当初からといいます、最初から使っていくような形になっているのかどうかということを確認させていただきたいのと、あとテントは、屋外があると思うのですけれども、屋内でも使えるようなものとかあるのではないかと思うのですが、そういった点でも、各家庭のプライバシーも守られ。","respondent":"羽鳥防災体制整備担当課長","answer":"屋根つきのものですと、テントというイメージに近いのかなと思っています。そういった形で、プライバシーを守れるような間仕切りを備蓄しています。","voiceIndex":22,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々、避難所環境の改善を目指していただいて、取り組んでいっていただきたいと思います。続いて、要支援者のほうなのですけれども、すみません、数字が追えなかったのですが、障害者のところは３００件……、すみません、もう一度そこのところも、今、何件つくられているというところをご説明いただいて、障害別には、どの障害で何件来ているのかというところも伺いたいと思います。","respondent":"松山障害者支援課長、平原防災課長","answer":"令和４年度につきましては４０３人ということで、合計で４４７人分を既に作成しております。今年度につきましては、約３００人の方を対象に作成予定です。ワークショップは町会ごとに行わせていただいておりますが、令和４年度は６町会につきまして実施させていただきました。特に障害別の内訳というのはこちらでカウントしておらず、まずは障害福祉サービスをご利用の方を優先的にしようということで、作成しております。","voiceIndex":24,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者の方、それぞれいろいろな障害、さらに言えば、その人の障害の度合いによってもいろいろ違うと思いますので、一概には言えないわけですけども、しっかりと、それぞれに合った計画をつくっていっていただきたいと思うのですが、その障害別による課題というのでしょうか、この障害は難しいところがあるとか、そういうのはあるのでしょうか。伺いたいと思います。","respondent":"松山障害者支援課長、平原防災課長","answer":"障害別の課題というのは、障害特性によっては一般的にそれぞれあるかと思いますが、それよりも個別の、ご本人の事情やご家族の事情、住宅の事情とか、主な疾患であったり、どういった言葉かけによってどういう支援が必要か。避難誘導ワークショップの具体的な中身のご紹介ですけれども、例えば一番最初に、今年度どういう形の取組をしていくかといった認識合わせから始めさせていただきまして、それぞれのところでどういった課題があるのか。","voiceIndex":28,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"要支援者に対する支援というのは、なかなか大変なところがあると思いますけれども、実際に起こった際に対応できるような、実効性のあるものにしていっていただきたいということを要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"幾つか質問させてください。最初に、避難所開設運営についてというところで、もしかして聞き漏らしたかもしれないのですけれども、区民避難所５２か所、被害状況に応じて補完避難所を開設するというご説明だったかと思うのですが、その判断は、どういう方がどのように行って、決定をどうするのか、開設はどうするのかということを伺いたいと思います。例えば、正直、集まり過ぎてしまうときがあるのですよね。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"ただ、開設は区の職員が行いますけれども、その後の運営につきましては実際に避難される方の協力を仰ぎながら、共助の体制をつくっていくこととしております。トイレなどに関しましては各訓練の時に、参加された方に見本としてお渡しして実際に使っていただいたりという形で、どういった備蓄がされていて、実際に発災した時どういうふうに使ったらいいのかというのをふだんから。","voiceIndex":32,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆、自分たちで備蓄している物を持ってきて、水ですけれども、どこかに置いておかなければいけないから、保管のしやすさはどうかとか、そういうことをやったら、中には本当に使いにくいものがあって、これ、いざとなってから気がついたのでは遅いねということを、本当に改めて感じたことがあるので、ぜひ有効利用という意味ではそういう、無駄にしないということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほどのご説明の中で、避難所マニュアルというものが５２か所全てでつくられているというふうに言われていたと思いますが、５２か所にある避難所マニュアルというものは、地域から、町会とかから出された後に点検というか、アドバイザーとかそういった者の視点からの点検をされるということはあるのかということと、あと、２０１８年の災害対策担当部長からのご答弁では、区からアドバイザーを。","respondent":"平原防災課長","answer":"それに基づきまして、現在マニュアルを実際に運用していくといいましょうか、毎年それに基づきまして、訓練という形で点検を行っておりますが、また今後、地域防災計画の大規模な見直し等々もありますので、その先をどうしていくかというのはまだ。","voiceIndex":36,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ですので、例えば関連動画とか、今作られていると思いますけども、令和４年度の東京都と品川区での品川区合同防災訓練の動画とか、作られていると思いますけれども、これをワンタッチで各項目で、やり方の手順とか開設訓練の手順といったものがすぐに分かるように、もう１０分、２０分とかの動画じゃなくて、項目ごとに分かれて一、二分とか、そのぐらいでやり方がすぐ分かる。","respondent":"平原防災課長","answer":"そういった動画ですが、現在様々なもので動画を使っていくということは、委員ご指摘のとおり非常に有効だと考えていますので、一つ一つの避難所について個別の動画というのはなかなか難しいと思いますが、共通化できるところなどを考えていきながら。","voiceIndex":38,"id":"exchange-011"},{"speaker":"ゆきた委員","kind":"意見","question":"参集職員が避難所の運営会議に参加されるとか、まずは係長級がスタートになるということで、職員は原則参加ということで、今年１月のご答弁でいただいていると思いますが、そういったことも、避難所運営マニュアルをつくる上での連絡会議でのコミュニケーションを図っていくといったところでも、今後ともさらに力強く進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"何かあった時に、町会の防災区民組織の方たちだけではなく、それ以外の方も、区民避難所を開く時にしっかりと支援ができる体制を整えるためには、これまで会派としても５２か所の各避難所の運営マニュアルの公開ということを求めてまいりましたが、区民防災組織がそれぞれで作っているというところで、なかなか公開されないという課題もあったかと思うのですけれども。","respondent":"平原防災課長、羽鳥防災体制整備担当課長、松山障害者支援課長","answer":"それを受けて令和３年に、どちらかというと福祉の方で一時的な計画をつくっていただくということで、役割が少しずつ変わってきているところですが。液体ミルクの活用の現状ですけれど、液体ミルクは確かに期限が短くて、活用させていただいているのですけれど。一般的なものになってしまうのではないかというようなご意見もありますので、一体どういうものが実際に。","voiceIndex":41,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"それぞれ、ありがとうございました。備蓄に関しては現状確認をさせていただきました。ラップ式ポータブルトイレも各避難所に４台ずつ整備されているということも確認ができました。障害特性を踏まえたマニュアルにつきまして、それぞれ団体に確認していただいているということなのですが、他自治体でも、障害特性に応じたマニュアルが作成されている事例もあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"私から、３ページの避難行動要支援者支援について、幾つか質問させてください。そして、それに加えて、ここに差がある場合はなぜ同意を得られていないのか、同意を得られていない方々に対する今後の対応等について、聞かせてください。","respondent":"平原防災課長","answer":"避難行動要支援者の名簿ですけれども、令和４年度は１万２,０４５名の方につきまして、名簿作成をしたところです。そのうち同意が得られた方につきましては５,３４６名です。","voiceIndex":46,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"事前の準備というのは本当に大切だと思っておりまして、私も医療従事者として働いていた時、やはり患者様の把握ができないとその後の対策もなかなか難しい、先ほど障害者支援課長がおっしゃっていたように障害別ではなかなか難しく、そこに加えまして、多分個別性というところを意識して計画を立てているので、個別避難計画という名前になっているとは思うのですけれども、やはり事前の準備をするためには。","respondent":"松山障害者支援課長","answer":"区から提供する新たな防災地図ですとか、いろいろな制度の情報ですね、例えば、対応の仕方等も含めてまたきめ細かく、お一人おひとりと相談させていただいて、またバージョンアップしていくというふうな方法をとっております。","voiceIndex":48,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回防災に関することということで、避難の考え方、在宅避難ということをしっかり明記していただいたということは、私はよかったのではないかと思います。そういうときに、その方たちに対応できる方、看護等に対応できるような方もそこに派遣される計画というのは、お持ちなのでしょうか。いろいろ防災課でも、かなり煮詰められていると思うのですが、まずそこを１点、お聞かせください。","respondent":"平原防災課長","answer":"ただし、時間によってはそのようなことができないような場合については、様々な代用資機材を活用していただく、あるいはその方がお持ちのものを使っていただく、あるいは状況が許せばなのですけれども、介護タクシー等々が使えるような状況であれば。","voiceIndex":51,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"ここでは、マニュアル的には東京都からも支援が来ます、国からも物資支援来ます、云々書いてありますけれど、実際に現実論は難しいのではないかと思うのですが、どうなのでしょうか。それから、もう一回戻りますけれど、災害物資ですが、東京都の統一見解は３日間、皆さん、自分のところで備蓄してくださいよということですが、品川区は独自に１週間持ってくださいよと公表してはいけないのですか。","respondent":"羽鳥防災体制整備担当課長","answer":"外からの車の進入を防いだり、その道路上に車など放置されている物を移動させ、輸送車両が通れるような対策を国のほうとしてもとっておりますので、そういった形で、輸送がとどまることがないような体制は、とっているものというふうに認識しています。","voiceIndex":53,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"それを、だから逆にして、１週間分をもう持ってくださいというふうに言わないと駄目で、できれば１０日分確保してくださいよと。やはりそういう文言に変えたほうが、私はいいのではないかと。物資の供給も。というのは、今、課長がおっしゃったとおり、緊急輸送道路あります、でも、それ、誰が仕切るのですか。もう一旦止まってしまったら、緊急輸送道路など使えないのではないですか。現実論は。","respondent":"平原防災課長","answer":"そういうこともございまして、今ではなるべく１週間以上という言い方をしていますが、今後言い方についてはまた、いろいろ工夫してまいりたいと考えています。","voiceIndex":55,"id":"exchange-019"},{"speaker":"こしば委員","kind":"質問","question":"私のほうから、先ほどほかの委員からも質疑があったと思うのですけれども、避難所等の種類についてお聞きしたいと思います。そういう中で、まず一時集合場所についてお聞きしたいのですが、こちらのほうは、例えば災害が起こった時に、町会・自治会、区民組織単位で、まず初めに避難をする場所というふうに、防災地図にも書かれておりますけれども。その辺、教えてください。","respondent":"平原防災課長","answer":"そういったところで、我がまちの安全を確保する一番最初のところだというような認識を、まず持っていただきたいというふうに思っていますけれども、そういったところの認識が、というようなお話でございましたが、例えば今回新たに配布させていただきました「品川区防災地図」。","voiceIndex":58,"id":"exchange-020","title":"町会・自治会支援"},{"speaker":"こしば委員","kind":"質問","question":"そうしますと、まず最初に避難する場所は、一時集合場所という認識でよろしいでしょうか。","respondent":"平原防災課長","answer":"その後で、近所の方と様子を見て、避難が必要かどうかといったところを判断するための場所が、一時集合場所だというふうに考えてありますので、大地震が発生した時、何が何でも一時集合場所に直ちに集まるのではなく、まずは安全確保。","voiceIndex":60,"id":"exchange-021"},{"speaker":"こしば委員","kind":"質問","question":"そういう中で、先ほどほかの委員の質問に対する答弁の中で、たしか避難所の定員がキャパシティーオーバーした場合には、新たに補完避難所を設けるという答弁をされておったと思うのですけれども、以前、会派のほうの勉強会もしたことがありまして、その時に、例えば、Ａ学校とＢ学校があって、Ａ学校のキャパシティーがオーバーして、Ｂ学校はまだ２００人、３００人ぐらい空きがあると。","respondent":"平原防災課長","answer":"それ以外のところにつきましては、まさに御指摘のとおり、例えば大学でありますとか、都立の高校ですので、そういったところは順次、そういう施設が使えるかどうかの確認をした後に、開設していくということを考えてあります。","voiceIndex":62,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、既に何年かたっておりますし、さらに更新して、それをもう少しみんなが使えるように公表するお考えは、あるのかないのか伺いたいのと。全員の声というわけではないですけれども、そういうことに関心があって、そういう冊子を見たり、防災学校に参加したりする方たちの中から、そういうお声が出ているということなので、ぜひ検討していただきたいのですが、その辺についてお考えを伺いたいと思います。","respondent":"平原防災課長","answer":"訓練そのものの区の支援ですが、大変申し訳ございません、なかなか全てに対応というのが、こちらの人数的にも難しいところがございまして、やはり訓練の支援といいましても、その日だけではなくて事前の準備から後片づけのところまであるので、大変申し訳ございません。","voiceIndex":64,"id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"防災学校はハイブリッドのことを存じ上げなかったので、そういうのもあるらしいよということは、関心のある方たちにお伝えしたいと思いますので、今後とも、こういうものはどんどん広げていっていただきたいと思っての意見と質問ですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-024"},{"speaker":"澤田委員","kind":"質問","question":"１点目は避難施設の備蓄品についてなのですが、小学校などでの避難であれば、絵本や子ども向けの本などもあると思いますが、それ以外の施設では未就学児などが避難時に不安な気持ちを紛らわせることができるようなもの、絵本やパズル、クレヨンや塗り絵など、そういう備蓄品があれば、緊急時に自宅からたくさんのおもちゃなどを持っていかなくても。","respondent":"羽鳥防災体制整備担当課長","answer":"１点目のご質問ですけれど、避難所にお子様向けの絵本やクレヨン、パズルなど、そういった備蓄があるかですが、こちらは今のところ備蓄指定はございません。","voiceIndex":67,"id":"exchange-025"},{"speaker":"澤田委員","kind":"質問・要望","question":"自宅での充電池などの補助というのも、ぜひ検討していただけたらと思います。避難所ではもちろん必要ですけれども、自宅でも必要だと思いますので。以上、全て要望になってしまうのですが、ご検討のほどよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"今、若干質疑に出たのですが、それに関連して、マニュアルにも記載いただいているのですが、品川区の中では先ほど、マニュアル自体は５２か所全て整備されているのは分かりましたが、その中で子どもの遊びスペース、キッズスペース、夜間帯には勉強部屋として使用する等について、しっかりとマニュアルに記載をしている避難所の数を、把握していれば教えてください。","respondent":"平原防災課長","answer":"５２のマニュアルのうち、子どもスペース等々の数ですが、大変申し訳ございません、今、この段階では把握してございません。","voiceIndex":70,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"４月に国会の場で公明党の国会議員が、国のほうでも、ガイドライン、名称は忘れましたけれど、国のほうでつくっているものとか、そうしたところで、キッズスペースのプライオリティー、優先度を上げるべきだというようなこととか、今質疑がありましたそうした備蓄ですね、これについていろいろと求めた質問の中で、それを、整備、推進していくというような、政府としての答弁もあった中で、東京都。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"併せてございました子どもに対応するようなスタッフにつきましても、そういった専門的な知見を持ちの方としっかりと、今後協議を進めさせていただければと考えています。遊具につきましては、全て区で備蓄をするのかも含めて、また民間の協定なども活用して用意していくのか、いろいろな選択肢があると思いますので、そういったところを総合的に考えながら、進めていきたいと考えております。","voiceIndex":72,"id":"exchange-028"},{"speaker":"つる委員","kind":"意見","question":"では巻き看板は、今後もまた計画の中で、この避難所の看板、プラスアルファ、区民への情報の充実というところで、避難所の、例えば電柱だけに限らず、ふれあい掲示板とか町会の掲示板、その縁に、ＱＲコードだらけになってしまってもよくないのですけれど、そういう設置箇所も工夫がいろいろできるのかなと思いますので、ぜひ今後検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-029"},{"speaker":"せりざわ委員","kind":"提案","question":"手短に。私自身も恐らく、震度６とか、どんと来た時に、在宅避難と言われていても、多分一回外に出て、どうしようかという話になると思うのです。その情報発信の場として、今、つる委員がお話しされた巻き看板の話とかがあると思うのですけれど。例えばトランスに関しては道路課が許可してくれないとかいう話なのか、どういう状況なのかというのを、防災課のほうの感覚を少し教えてほしいです。","respondent":"羽鳥防災体制整備担当課長","answer":"避難看板の中に周辺の地図も載せる予定ですので、周辺がどういう形になっていて、どういった防災関係の施設があるとか、そういったところも、通りかかったときにふっと見ていただく、そういった形での効果も見込んで設置しています。","voiceIndex":76,"id":"exchange-030"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"もう１点だけ。私が、あまり災害時モードを見たことないから、実はやっているのかもしれないですけれど、もう少しハードルを下げてどんどんどんどん、日常と災害時の非日常の境界線を少しずつ近づけていくというのですか、日常寄りに災害時の情報というのを近寄らせていく、防災訓練でも何でもそうですけれど、そういった取組をぜひ、防災の皆さんで取り組んでいただければ。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-031"},{"speaker":"西村委員","kind":"質問・要望","question":"様々ご説明ありがとうございました。手短に２点だけ伺います。腎臓疾患のある方向けに、低たんぱく米の導入が拡充されていると伺いました。もう１点、先ほど子どもスペースのお話があったのですけれども、同じように授乳スペースに関しても設置予定があるのか、改めて全避難所をご確認いただきたいと考えています。これは要望ですけれども、何かございましたらお答えください。","respondent":"羽鳥防災体制整備担当課長、平原防災課長","answer":"私からは、１つ目の備蓄についてお答えします。管理方法につきましてですけれど、現在、物資の輸送から管理まで一事業者で一括で管理をしています。その中で、システムのほうで管理をしております。こちらにつきましては前回の検討の際に、そういったスペースの必要性というものはお話ししていますが、必ずしも全てのところで場所がきちっと指定されたわけではございませんけれども、そういうことがございましたので、先ほど来。","voiceIndex":79,"id":"exchange-032"},{"speaker":"西村委員","kind":"意見","question":"授乳スペースは、確かに屋根のある間仕切りで活用できると思いますので、準備していた、災害が来たと区民の方々が思えるように、引き続き体制の整備をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-033"},{"speaker":"鈴木副委員長","kind":"確認","question":"先ほど要支援者の名簿が１万２,０４５人で、同意をされた方が５,３４６人ということでご説明がありましたけれど、この要支援者名簿というのは、品川区の要配慮者支援全体計画の３ページに「避難行動要支援者とは」ということで書かれていて、例えば要介護度１から５とか、身体障害者１から３級とか、愛の手帳１から２度とかいうのがありますけれど、この６項目が要配慮者ということでの名簿ということで。","respondent":"平原防災課長","answer":"それと内訳ですけれども、ご本人が同意されたところですが、すみません、時点が違うもので、合計数字が一致しないところがあって申し訳ございませんが、要介護の方が２,３１１人、身体障害をお持ちの方が２,５４０人、それから。","voiceIndex":83,"id":"exchange-034"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そうしたら、同意をされた方は高齢者でいえば２,３１１人ということなのですけれど、先ほど高齢者の計画は、今年度でも５,０００件組んでいく、それまでも５,７００でしたか、かなりの数で組まれていますけれど、この計画というのは、同意された方が計画を組んでいくというのではなく、この同意の数字と計画の数字というのがどういうふうに関係しているのか、伺いたいと思います。","respondent":"菅野高齢者福祉課長、平原防災課長","answer":"今年度新たに３,０００件の原案をさらに作成する予定で、この原案のうち、先ほど最初の防災課長の説明にもありましたけれども、４年度末で約１,２００件が本計画のほうに移行していまして。全体計画の見直しのお話ですけれども、副委員長ご指摘のとおり平成２８年に策定したものでございまして、こちら、その後の災害対策基本法の見直し、あるいは今進めております地域防災計画の修正、こういったものを含めて。","voiceIndex":85,"id":"exchange-035"},{"speaker":"鈴木副委員長","kind":"確認","question":"新たな改定ということで、国のほうでも福祉避難所の確保・運営ガイドラインを出したり、かなりいろいろ自治体に対して、こういうふうに進めてくださいという方向が出されていると思うのですけれど、その中で、この避難所に対しての計画を立てて、指定福祉避難所はここにありますよと、そしてこの避難所に対してはこういう方が、何というのですか。","respondent":"平原防災課長","answer":"もう１点ですが、区内で例えば、新たに福祉法人が開設されるというようなお話を聞いたときには、その事業者の方と打合せをさせていただいて、福祉の部局と私ども防災の部局で、ご協力いただくというような形で進めさせていただきまして、災害時の協定などを結んで。","voiceIndex":88,"id":"exchange-036"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そうしますと、福祉避難所は今、４３か所ということですけれども、そこで受け入れる対象者も特定するということで、ここの福祉避難所にはこういう方に何人くらい来てもらえますよと、そういうことで決まっていると考えていいのでしょうか。そういうところが、現在どういう状況になっているのかを教えていただきたいのと。その資料編の、何ページにあるかというのが分かったら教えていただきたいのです。","respondent":"菅野高齢者福祉課長、平原防災課長","answer":"基本としましては、ケアマネジャーがどこを避難場所にするか決めるときには、住居の倒壊リスクとか、親族等の住居を避難先とすることが難しいなどの場合、福祉避難所を指定するということになっているのですが。個別避難計画に書かれている方の全てが福祉避難所ということではなくて、例えば介護度の低い方は、区民避難所の要配慮者スペースといったところも活用しながら、受入れを進めてまいりたいというふうに考えているところです。","voiceIndex":90,"id":"exchange-037"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"私はその当事者、団体の方とかも含めて、これは防災課も含めて障害者支援課、高齢者福祉課合わせて検討していかないといけないのかなと思うのですけれど、その検討の組織というのですか、そういうのはどういうふうに検討がされているのか、そしてそういうところに当事者の意見が入るような形で検討もしていただきたいと思っているのですけれど、当事者の意見を伺うような場所というのは。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"昨年度、防災課と共同しまして、区内の町会・自治会と、在宅介護支援センターを中心としたケアマネジャーの参加による、先ほど防災課長からも説明がありましたが、ワークショップなどといったところで。防災課のほうでやっている町会との避難行動要支援者の体制の構築事業、検討会ですけれども、それぞれの町会、防災課、障害者支援課、障害者の相談支援センター、あと当事者の方も実際に入りましてアドバイスをいただいたり。","voiceIndex":93,"id":"exchange-038"},{"speaker":"鈴木副委員長","kind":"質問","question":"品川区の場合は、原案をつくって、それから本計画にということで、２段階で計画をすることによって、新たな課題を本計画の中で具体化していくみたいな、そのような形で、ほかの区は何か１回だけで計画を立てて、するところもあるというふうに伺ったのですけれど、品川区の場合は２段階で計画するという、そこの意味というのは、原案をつくったことによってこういう課題を明らかにして。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"私からは、個別支援計画の作成過程についてのご説明をします。高齢者の場合はケアマネジャーによる主観による、原案の計画を作成しています。こちらの場合ですと、いきなり原案という形になります。一部、１０人弱ぐらいの方はなかなか同意が、残念ながら得られなかったというところがありますけれども、そちらは計画をつくるところまでは行っております。","voiceIndex":96,"id":"exchange-039"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"原案で３,０００円、本計画で４,０００円、合わせて７,０００円ということなのですけれど、ケアマネジャーの方々は、本当に介護の現場で日々ゆとりのない忙しい中でこれを組むというのはかなり、いろいろな分野にわたって検討せざるを得ない部分、調整だったりあって、１回の計画で７,０００円というのがモデルで区のほうでは書かれていましたけれども、これは自治体が独自に決めることができるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6636#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":53386,"voices":104}},{"id":"r05-20230710-10","meetingId":"r05-cm07","date":"2023年7月10日","dateIso":"2023-07-10","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点、委員会審査での写真撮影についての検討の要望なのですけれども、今回の定例会でも、請願・陳情が活発に出されまして、総務委員会、厚生委員会、行財政改革特別委員会で、傍聴人から写真撮影を求められて、その可否を議論する場面があったと伺っています。総務委員会で石田秀男委員から、こういったことは議会運営委員会で議論すべきだという発言もあったと伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-001"},{"speaker":"せりざわ委員","kind":"質問","question":"今お話があったところに対して、一言だけ意見を。その一方で、前例に従ってというと、少し堅苦しい話だと思うのですが、一定程度、課題があるから、こういう現状になっているというふうに少なくとも私は理解していて、それも以前、私もいろいろ教えていただいて、そうなのだなと初めて理解したところもあるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"課題が何かあるのだろうなということは、もちろんあると思うので、それは話し合う中で、その課題をどうするかという話合いもあると思いますし、それは大事な視点かなと思っています。それとあと、預からせていただきたいと、先ほど委員長におっしゃっていただいたのは、具体的にはどういう感じで進めていかれるのかだけお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":8193,"voices":39}},{"id":"r05-20230724-6","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"区民委員会","time":"午後 １時００分～午後 １時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年度八潮みらい懇談会","agenda":"令和５年度八潮みらい懇談会","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"ご報告ありがとうございました。八潮地区の地元の議員とちょっと話をしてきたのですけれども、確認をさせてください。今までの委員会で出てきていると思うのですけれども、八潮みらい懇談会の委員の構成というか、どのような方たちが、いわゆる懇談のメンバーとして何人ぐらいいらっしゃるのか、その背景も含めて教えてください。","respondent":"中西八潮まちづくり担当課長","answer":"人数としましては、２０名程度というところでやっているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど申し上げた、この建て替えに当たっては、各世帯がこれから先、そのような合意が取れるのか取れないかという問題もあるのですけれども、各世帯でやはりその分担金、負担金のようなものを負担していくとなっていった場合に、やはり世帯や所得によって考え方もいろいろ違うので、その辺りの、例えば分科会のような形でも結構ですが。","respondent":"中西八潮まちづくり担当課長","answer":"そういった中では今ＰＴＡの方が、保護者の方で参加をいただいている部分もありますし、あとは八潮自治会連合会の連合自治会長が交代されまして、今５０代の方がなっていらっしゃいますので、少しそういった意味では、今後ＮＰＯの方や、八潮のまちで活躍している若い世代。","voiceIndex":7,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"現在どのような年齢層になっているかということと、将来的にということも、やはり担当としては人口動態を押さえておかなければいけないと思うので、その辺についていかがでしょうかということ。懇談会の意見交換の中で、不審者の情報が複数というように出ているのだけれども、今八潮の地域の中の防犯カメラの状況というのはどうなっているのでしょうか。お伺いします。","respondent":"中西八潮まちづくり担当課長","answer":"１点目の人口動態についてです。この４月１日時点の数字というところになりますが、人口としましては、１万１,５８６名です。高齢者に関しましては４,３０１名ということで、高齢化率ということでいきますと、３７.１％というような数字です。","voiceIndex":10,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"高齢化、この高齢者の割合が３７.１％ですよね。品川区の平均からすると物すごく高いですよね。１０ポイント以上高いですよね。たしか３０％は切っていますよね。すると１０ポイントぐらい高いから、その辺について将来的にということはやはり考えておかないと、施策の中で人口動態が大事だから、その辺についていかがですかということが１点です。だから、その辺についてもいかがでしょうか。","respondent":"中西八潮まちづくり担当課長","answer":"１点目の高齢化率が進んでいるという中での取組ですが、実際、例えばおまつりをやるにしても、今なかなか皆さん、ご負担を感じていらっしゃる方も多くいらっしゃいますので、いかに若い世代の方々。","voiceIndex":12,"id":"exchange-004"},{"speaker":"藤原委員","kind":"確認","question":"一つ確認なのですけれども、防犯カメラに関しては生活安全担当課長のところで担当していると思っていたのですが、八潮地区に関しては八潮まちづくり担当課長のところでやっていくのか。であるならば、もし違うというのであるならば、生活安全担当課長、八潮地区についてはどのように考えているかということを、やはり生活安全担当課長から答弁していただければ幸いなのですけれども、いかがでしょうか。","respondent":"河合生活安全担当課長","answer":"設置場所等につきましては、こちらのほうも把握はしておりますけれども、助成の上で事前に警察の助言を求めておりまして、そちらでアングルと位置関係につきましては適正な場所を検討してくださっているということになります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"防犯というものは物すごく大事な要素の一つだと思っているので、八潮まちづくり担当課長と生活安全担当課長とがよく話して、もちろん地域も含めてですけれども、防犯カメラの設置を積極的にやっていただきたいと考えています。その辺についてはいかがでしょうか。","respondent":"中西八潮まちづくり担当課長","answer":"防犯カメラの件に関しましては、八潮みらい懇談会、八潮まちづくり担当課長としての職務、それから八潮地域センター所長として、防犯カメラをつける際の補助金の申請など、そういったところで窓口もやっておりますので。","voiceIndex":16,"id":"exchange-006"},{"speaker":"横山委員","kind":"質問","question":"３点お伺いいたします。３点目なのですけれども、八潮地区は高齢化とともに、外国人の方も割と多い地域かなと思っています。最近はどういった傾向になっているのか、先ほどほかの委員の質問の中で、何％とか、何名などというお話があったのですけれども、現在の状況を教えてください。","respondent":"中西八潮まちづくり担当課長","answer":"申し訳ございません、ちょっと具体的な数字を持ち合わせてはいないのですが、地域の方からは、やはりいろいろな人種の方が増えてきているというようなお話もありますので、その辺りをどのように連携していくかというところも検討課題かなとは思っております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"コロナ前とも人口の構成などが若干変わってきていることもあるかも分からないのですけれども、現在の状況を随時把握していただきながら、外国の方なども含めて、これから２０年後、３０年後の地域の未来をより具体的に地域の皆様にイメージしていただけるような、そういった環境づくりというか、また情報の提供など、そういったところを区のほうでセッティングしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"えのした委員","kind":"質問","question":"不審者ですから子どもたちの安全だけではないと思うのですけれども、品川区はまもるっちの協力者登録というものがあると思うのです。その辺、例えばまずメンバー２０名の方に登録をご協力いただいたり、またそこから自治会、またまちの関係者の皆さんに協力者登録をお願いしたり、そのような取組はされていらっしゃいますでしょうか。","respondent":"中西八潮まちづくり担当課長","answer":"まもるっちの協力者登録に関しましては、まだそこまでは話は広がっていないのですが、まずはＰＴＡのほうでもう１回見回りを始めようかですとか、八潮自治会連合会のほうでもやろうかというような話が出ておりますので、それを進めつつ。","voiceIndex":27,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"昨年度高島平団地も行っていますよね。行っていないですか。行っていないかどうか、それを。","respondent":"中西八潮まちづくり担当課長","answer":"昨年度は光が丘団地のみの視察です。たしかこの委員会の中で高島平団地のお話を少し出させていただいたという経緯はあります。視察に行ったのは光が丘団地だけです。","voiceIndex":31,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"高島平団地を視察するというのはすばらしいことだとは思うのですけれども、ただ、高島平団地は都営三田線の駅を出ると、目の前が高島平団地なのです。信号を渡ってすぐが。交通の便というところは八潮団地とは少し違うのです。というのは、全然違うではないですか。どのようなことを視察したいのかとか、どういう目的があってということを具体的に教えていただければ幸いです。","respondent":"中西八潮まちづくり担当課長","answer":"今後に関しましても、高島平団地も今ご意見としては出ているところではあるのですが、そのような単純にハード面だけを見に行くというよりは、どのような地域活動がされているかといったところも含めて、視察先は選定していきたいなと考えています。","voiceIndex":33,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、あえて言いますけれども、ハード面は物すごく大事です。ソフト面も大事だけれども、ハード面は、私は物すごく大事だと考えていますので、その辺も含めてしっかり視察してきていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"せらく委員","kind":"質問・要望","question":"今視察のお話が出ていましたけれども、八潮団地と似た成り立ちの光が丘団地に行かれたということで、逆に八潮団地に視察に来られた団体などがもしあったら、八潮地区のどのようなところを見られたとか、八潮地区のアピールポイントという部分もあれば教えていただきたいです。","respondent":"中西八潮まちづくり担当課長","answer":"ただ、八潮の地域の方々がよく八潮地区の特色としておっしゃるのは、いわゆる歩車分離というところで、車が通る道と歩行者が歩く道というところが完全に分離をしているといったところは、一つ八潮地区の特色としてあるということは、お話としてよく聞く話です。","voiceIndex":37,"id":"exchange-013"}]},{"id":"topic-02","title":"しながわシティラン実行委員会の設置","agenda":"しながわシティラン実行委員会の設置","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"いよいよ始まってきたかなとは思うところなのですが、現時点でこのコースが未確定というのは、スケジュール的に少し心配というか、どうなのかなというところと、実際いつ頃までに決まったらいいなではないですけれども、進行上、この辺ぐらいまでには決めないといけないと、何か一定の目安などがあれば教えていただければと思います。","respondent":"三井スポーツ推進課長","answer":"コースについては、まず実行委員会を年２回開く想定をしておりまして、順調にいけば１２月頃を予定しております。そのため、コースについてはその前までに決定をします。大枠はまず確定をしたいと。","voiceIndex":46,"id":"exchange-014"},{"speaker":"えのした委員","kind":"意見","question":"年内、１２月までということで、一つ安心材料になりましたけれども、これが全く逆のコースとなると、走る地域のコースの環境等、安全が一番だとは思いますけれども、やはり品川区の魅力、走りやすさ、区民の方が参加しやすいコースをぜひ熟考していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"私も詳しい方に何回かお話を聞いたのですが、ほかの自治体マラソンの場合には、やはり商店街等を走ることによって商店街の魅力を発信したいのだけれども、実際にその営業時間内に走ったりすることに非常にハードルがあるので、時間帯を物すごく早い時間帯に設定をする、営業時間にあまりかからないようなところにしたりとか、３月ですから気温の問題はそれほどないのだと思うのですが。","respondent":"三井スポーツ推進課長","answer":"品川区の魅力についてですが、基本的にはこちらの運河沿いになりますと、ウォーターフロントというか、そのような運河のところ、あとは旧東海道がありますので、歴史のあるまち並み、また公園等、大井ふ頭中央海浜公園が入っておりますので、オリンピックレガシーなどを含めて。","voiceIndex":49,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"今回メンバーの中に区の商店街連合会等も入っていらっしゃるということなので、これもまだこれから検討なのでしょうけれども、常々区とすると、いわゆる、一つ品川区の魅力は商店街にかかっているともおっしゃっておりますが、先ほど申し上げたようなことと兼ね合わせると、なかなかこう、やはり旧東海道を走るということはイコール商店街を走るということになりますけれども。","respondent":"三井スポーツ推進課長","answer":"その辺の具体的な内容は実行委員会でこれから検討するかと思いますが、そこも含めて品川区の魅力を発信できる大会にしたいと考えています。","voiceIndex":51,"id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"お伺いいたします。３月２８日にしながわシティランに向けたアイデアソンが開催されたかと思うのですけれども、その際にどういったお話があったのかというところと、区としてアイデアソンの内容、アイデアについても混ぜ合わせていい大会にしていきたいということで、ホームページに載っているのですが、その辺りの考え方を教えてください。","respondent":"三井スポーツ推進課長","answer":"アイデアソンは３月に実施させていただいて、主に魅力のあるコース設定だったり、ふだん走れないコース設定がいいＰＲになるということで聞いておりまして、コースについてはその辺の話を受けながら準備委員会のほうでも話をしまして。","voiceIndex":54,"id":"exchange-018"},{"speaker":"横山委員","kind":"確認","question":"とても期待が集まっているしながわシティランということで、様々ご意見もあるかと思いますので、そのアイデアソンなどの意見も反映していただきながらということだと思うのですけれども、あと、シティランの理念等はもう決まっているのでしょうか。案という形なのでしょうか。その辺りを確認させてください。","respondent":"三井スポーツ推進課長","answer":"それを今度は実行委員会にまた案として出した段階で検討していくというような形になります。","voiceIndex":56,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"理解いたしました。ランナーの方はもちろんのこと、ボランティアや応援など様々な機会を捉えて、健康づくりというか、そうしたところに皆さんの意識がいくような、そうした仕掛けもぜひ行っていただきたいなと思っていますので、総合的にその理念をどういった形で実現していくのかというところを実行委員会のほうではお話しいただきたいと期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-020"},{"speaker":"山本委員","kind":"確認","question":"もうご説明のところで、コース案についてはいろいろと検討の上で、安全性の面などで海側のほうを中心にご検討されてきていることではあると思うのですけれども、どうしても確認をしたいというところでいうと、やはり品川区のシティランということでいえば、品川区全域を走れるに越したことはないのかなと。","respondent":"三井スポーツ推進課長","answer":"今回、大井、荏原、品川、大崎など、幅広く走るルートを検討してまいりました。","voiceIndex":60,"id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"いろいろご検討をしての結論ということで理解しておりますが、やっていく中で区民の皆さんの理解が高まっていってコースを広げていくということも、取組としては、今後長い目で見るとあることかもしれないので、そういった意味でも、先の話になるかもしれませんが、検討いただきたいと思った次第です。ぜひ多くの区民の皆さんを巻き込んで、よいイベントにしていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16864,"voices":66}},{"id":"r05-20230724-7","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"厚生委員会","time":"午後 １時００分～午後 ２時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年陳情第２３号、利用できない区民のために、障害者施設の迅速な整備を求める陳情","agenda":"令和５年陳情第２３号、利用できない区民のために、障害者施設の迅速な整備を求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"ご説明、ありがとうあります。こちらの陳情にあります、例えば、「令和２年９月２３日の厚生委員会で」と続いておりますが、こちらの稼働率等、利用状況が３年前のものですので、現在の定員における稼働率等を教えていただければ、助かります。よろしくお願いします。","respondent":"松山障害者支援課長","answer":"直近の障害児者総合支援施設の稼働率につきまして、お答え申し上げます。令和５年３月末時点では、生活介護のハード上の定員における稼働率は６０％で、就労継続支援Ｂ型の稼働率は２０％と、稼働率は、どちらも順調に伸びております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"３年前に比べて、こちらの稼働率のほうは伸びているということですので、安心しておりますが、こちらの就労継続支援Ｂ型が低い理由は、希望がないのでしょうか。どのような感じで、低い数字なのでしょうか。","respondent":"松山障害者支援課長","answer":"例えば、障害児者総合支援施設をご希望された特別支援学校の令和５年度の卒業生ですと、ご希望どおり、生活介護については、お二人の方が、就労継続支援Ｂ型については、お一人の方がご希望されて、ご希望どおり、今、通所をされております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問・要望","question":"何点か質問をさせていただきたいと思います。区としての取組は、その足りないところについては、どのような取組をしているのか。年々、障害者の人数も増えているという現状があって、区内の施設に入れず、ほかの自治体の施設に通っている方もいると聞いているので、今後の障害者の増加をどのぐらいに見込んでいるのか、また、その増加に対しての具体的な計画等があれば教えてください。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"実はこの前提として、令和４年１０月から指定管理者となった福栄会が、生活介護と就労継続支援Ｂ型の利用ご家族を対象にして、家族見学会を予定しておりましたが、新型コロナウイルスの感染症状況を踏まえまして、書面開催とし。昨年は、１２月に、障害者のニーズのアンケート調査の結果を調査させていただきまして、障害者の今後の増加の推移等を、各年度における障害福祉サービスの見込量を設定しまして、その確保には十分努めてまいりたいと考えています。","voiceIndex":12,"id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ご説明、ありがとうございました。種類があって、その３種類の中で、グループホームという形でのところは、まだもう少し伸ばしていく必要があると理解をいたしました。２点目が、既存の施設のバリアフリーの状況についても、この陳情で書かれているので、その点についても、教えていただきたいと思います。そのできない問題点についても、聞かせていただければと思います。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"実際に福祉サービスの継続というものがなくてはならないものですので、例えば、施設の工事中には、通われている方に、どこか代替先を用意しまして、その先においても、安心安全に通所できて。現時点では、長寿命化の観点から、適切な点検や修繕を行って、建物における長寿命化を図り、安全性を確保しながら、維持していくという考えに至ります。","voiceIndex":15,"id":"exchange-004"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほどグループホームの話でもありましたが、民間の事業者といろいろと協力してやっていると思うのですが、区に寄せられた情報をぜひ共有していただいて、新たにできた施設、また、新しく整備するときにも、その意見をきちんと取り入れたような改修、また新設をしていただければ、今後、利用者が、利用しやすい施設が出来上がってくるのではないかと思いますので、その点については要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"何点か伺います。荏原地域にというところでは、この前の第６期品川区障害福祉計画・第２期品川区障害児福祉計画の地図に落として、９８ページに、どこに、どのような施設があるというものがあります。今、計画されているもので、区として整備する、そのような大きな施設はあるのか、ないのかについて、まず伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今後の整備計画としては、先ほどお伝えしたように、ニーズ調査や今後の障害者の増加の推移等を見ながら、各年度における障害福祉計画のサービスの見込量を設定していきますので、現段階で、荏原地区にこれと確実にお伝えできるものは、先ほどご説明させていただいたとおり。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"でも、区の補助金が、せっかく２,５００万円に増やされましたけれども、先日伺ったとき、その補助金を使って整備されたのは、多分、１件だけだったと思います。それが、なぜ、グループホームを造るのに、もっと使われないのか。その点をどう考えられているのかということも伺いたいと思います。心身障害者福祉会館は、築何年になるのかを教えていただきたい。","respondent":"川崎障害者施策推進課長","answer":"先ほど御説明したように、福祉保健施設の目安としては、大規模改修が３０年、建て替えの周期は６０年という目安で、改築となると、推計としては、耐用年数は、あと１４年とはなります。","voiceIndex":22,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"グループホームなのですけれども、もっと、もっとグループホームを誘致したいし、希望する人も多いし、地域移行というところからも、求められる施設だと思うのです。そのような形で、もっと使いやすいものにはできないのかと思うのですけれども、その点を伺います。その点は、このアンケートをどのように計画に反映させていくのか、それはどう考えられているのかについても伺いたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"他区でも、このような事例はありますので、そのような他自治体の例を参考にしながらも、今までの周知計画プラス新たなグループホーム整備促進の動きを検討していって。基礎調査は非常に幅広く行っているものですけれども、一方で、地域移行調査は、区内外の施設入所者が対象ということで、ご本人、ご家族、そして、施設の支援者に対して、本人が、ご希望があるのか、あるいは、家族がご希望があるのか。","voiceIndex":24,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ただ、区内は、もう満杯で、入るところがないので、区外を勧められて、区外に入らざるを得ないという状況になっている方が、これだけたくさんいるということを考えると、やはり、これから希望する人は、区内に入れるという方を、区としても、しっかりとつくっていくということが求められていると思いますので、このグループホームは、ぜひともしっかりと増設していただきたいと思います。","respondent":"川崎障害者施策推進課長","answer":"ただ、品川区総合実施計画の中におきまして、現行の計画では、令和６年度末までに４８名増ということで、定員数は、予定はしておりますので、総合実施計画上で示している数値ではありますけれども、そこに向けて、今、着実にグループホーム整備を進めているところになります。","voiceIndex":27,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"私は、このアンケートのところからも、１８４人という方が、今後利用したいと答えられている中で、４８人増で足りない……。障害者施策推進課としては、そこのところは、せっかくアンケートも取っているわけですから、これを反映した形での施設の増設計画を明確に持つべきだと思うのですけれども、その点を伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"品川区では、令和２年から令和４年にかけて、民間整備によって、グループホームは、８施設増加、５９人の定員増加につながりましたので、今後としても、このような整備費補助の強化であるとか、相談対応であるとか、区有地や都有地、民有地、例えばですけれども。","voiceIndex":29,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"土地の確保ということです。もう一つです。これは、施設を造るに当たり、質的なものも、かなり求められると思うのです。そのような点では、一段階、質的な部分でもアップさせていくことが必要であると、アップした施設を整備していくということが求められるのではないかと思うのですけれども、区としては、その点はどう考えるのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"先ほども御説明したとおり、ニーズ調査に基づき、また、今後の障害者の増加の推移といったものを、各年度における障害福祉サービスの見込みを設定して、その確保に十分努めていきたい。そこは、区としても、確実に努めていきたいと考えています。","voiceIndex":31,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"高次脳機能障害や発達障害というのは、歴史はそんなに古くなく、どんどん新たに明らかになってきた部分があると思うのです。発達障害は、これからやっていくという方向が出されていますけれども、高次脳機能障害の方に対してのサービスの確保だったり、そのような施設的な部分も含めての充実というところを、どう考えられているか。その点も伺います。","respondent":"川崎障害者施策推進課長","answer":"今回、第７期の障害福祉計画の策定委員の中に、公募区民の中に、発達障害の方、高次脳機能障害の方、当事者２名がおります。その当事者の方のご意見も踏まえまして、今後のサービスの見込量確保は、充実させていきたいと考えております。","voiceIndex":34,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"障害の方は、障害種別でも、本当にかなり違いますし、また、障害の中でも、それぞれの個々の状況は、違う部分がありますけれども、本当に障害者権利条約に書かれているように、一人一人の障害を持っても、合理的配慮もされ、社会的障壁もなくし、当たり前に生活できるということが求められて、第１回目の勧告も出されたところですので、そのようなところも踏まえて、質と量、でも伴うような形で、今回。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点確認なのですけれども、陳情にある「区長の目指すウェルビーイングが確保されていない状態であります」ということなのですけれども、森澤区長は、ウェルビーイングを推進されているということで、それを前提に、我々も計画を立てるということでよろしいでしょうか。区の考え方を聞かせてください。","respondent":"川崎障害者施策推進課長","answer":"はい、そのとおりです。品川区は、「誰もが生きがいを感じ、自分らしく暮らしていける品川」を目指して、区民の幸せ、ウェルビーイングを目指す施策づくりに取り組んでいます。","voiceIndex":39,"id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回の陳情ではなくて、もう基本理念として、ウェルビーイングを目指すということで、この陳情も含めて、今後もそのような取組であるということで承知しました。もう１点、質問です。お考えとして、これから障害者の推移といいますか、どのようになっていくとうような見込みをしていらっしゃいますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"障害者のどのような見込みということは、種別などということでしょうか。","voiceIndex":41,"id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"増減で、今後、増える傾向などといった推移の見込みをお伺いできればと思います。","respondent":"川崎障害者施策推進課長","answer":"ただ、愛の手帳所持者数は増加しておりますし、精神障害者保健福祉手帳所持者数も増加しておりますので、全体的には障害者の数は増加しているとは認識はしております。","voiceIndex":43,"id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"この陳情者の陳情の趣旨について、お伺いをしたいと思います。障害者施設の迅速な整備を求めておられるのですけれども、今現在、迅速に施設整備できるという、その環境にあるのか、現実問題としての可能性があるのかということをお聞きしたいと思います。","respondent":"川崎障害者施策推進課長","answer":"これを加速させるという意味でも、私どもも、引き続きグループホームの補助金の周知強化にも努め、また、公有地、都有地、区有地、また民有地などの洗い出しも検討をしてまいりたいと考えております。","voiceIndex":47,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"といいますと、迅速な整備を行っている。区としては、そのようなご認識だということでよろしいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"グループホーム以外でも、障害児の部分でも、放課後等デイサービスも、整備は促進されております。障害者、障害児ともに、必要なところの整備は、確実に、着実に進めていると認識しております。","voiceIndex":49,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"そのような施設ということでも、記者会見でしたでしょうか、新聞にも報道されたと思うのですけれども、具体的にウェルビーイングを満たす障害者施設というのは、どのような施設なのかを具体的にご説明いただけたら、ありがたいです。","respondent":"東野福祉計画課長","answer":"区長記者会見で行われました、産学官連携によるウェルビーイングを満たす施設造りは、あくまでも、高齢者施設を対象としたというところで、今まで、何もそのような知見がない中で、大学との連携、事業者との連携を進めていきましょうということで。","voiceIndex":52,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"具体的にウェルビーイングを満たす高齢者施設というのは、具体的にどのような方向の中身になるのか、いま一つイメージが、持てないのですけれども、どのようなことが変わるのでしょうか。変わる中身、充実される中身、そこら辺のところを、もう少しイメージを持っているような形で、ご説明いただけないでしょうか。","respondent":"東野福祉計画課長","answer":"今、想定できるものとしては、建物の快適性であったり、働く方、入所される方、その方々が、幸せ、ウェルビーイングというものをどう感じるかというところに重きを置いて、施設造りを進めていきましょうという段階で、具体的には、その後。","voiceIndex":54,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、建物の建て方というか、建築の在り方のところでのウェルビーイングと、そのようなところなのでしょうか。そこでの働き方など、そのようなソフトの面も含めて、それとも、ハードだけなのか。それが、障害者のほうまでは行かないで、まだ研究されていることが、高齢者からということなのか。","respondent":"東野福祉計画課長","answer":"高齢者施設からというところになります。ウェルビーイングを満たした施設づくりでの産学官協定ということになりますので、まずは、ハード面で、どのようなことができるかというところでの考え方をまとめていくというようなものです。","voiceIndex":56,"id":"exchange-021"},{"speaker":"こしば副委員長","kind":"質問","question":"結論を出すで、不採択でお願いします。これまで、この陳情の理由について、各委員から質疑応答がありまして、この陳情の理由と書かれていること全てが、必ずしも今の状況に沿っているとは言い難い面もあるかと感じました。それで、この陳情の理由については、今の状況を必ずしも反映していないということで、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すで、お願いしたいと思います。ほかの施設の整備なども、機会を捉えて、また、やはり、区民のための施設をどうしたらいいのかということを、常に念頭に置きながら取り組んでいるということを、質疑の中で、私は確認をさせていただきました。ですので、現状、そのような取組が確認できましたので、この陳情に対しては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-023"},{"speaker":"ひがし委員","kind":"質問・要望","question":"一方で、既存の施設のバリアフリー化については、構造上の問題もあって、入所しながらの工事が難しいという点も確認できましたので、その点につきましては、まずは、新しく造る際、また、できる範囲での改修を行う際には、利用者目線に立ったバリアフリーを目指し、当事者の意見をしっかりと取り入れて、利用者が安心して利用できる施設になるように取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今年、そのような障害者福祉の計画を立てるところで、改めてその整備をそこの中に取り入れた形での計画にしていただきたいという希望です。やはり、施設整備という点では、２３区の中でも、品川区は、まだまだ整備率は低い状態です。障害者権利条約の勧告が出されたという状況の中で、やはり、当たり前に障害者の方々が暮らせるためにも、ぜひ、施設の整備は、早急に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"本日結論出すで、不採択でお願いいたします。今までの質疑とご答弁を総合的に勘案をいたしまして、この陳情書の趣旨の理由に対して努力されているということで、本日結論を出すで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-026"},{"speaker":"おぎの委員","kind":"確認","question":"今回、この陳情に関しては、結論を出すで、不採択でお願いします。ですが、実際、どの程度のものであるかなどといったことで、今回、私も見に行きたいと思いました。実際、今、施設がどのような状況になっているのかを、私たち議員も、しっかりとこの目で確認をしたほうがいいと思います。区のほうでは、しっかりと改修工事をしていただいている。ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日、結論を出す。採択でお願いします。お話を伺っていて、品川区でも非常に取組をされているということは、十分理解させていただきました。その中で、やはり、当事者の方たちとのある程度の温度差を感じましたので、ぜひ、障害当事者の方、ご家族の方に、より寄り添った政策を行っていただきたいというようなことを感じましたので、採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-028"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"これ以上増やすということは、もう難しいという感じですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問","question":"厳しいですね。その期日までに出さなかったので、申し訳ないのですけれども、可能性として、もしも、あるのであれば、兵庫県で医療支援型のグループホームになっているというものがあったのですけれども、そのようなものが入る余地は、もう全くないですか。なかったら、なかったで、私は、期日までに出さなかったので、もう諦めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今回、初めて厚生委員になられたの方も結構いらっしゃるではないですか。それなので、例えばグループホームだったり、区内の平塚橋特別養護老人ホーム、平塚橋ゆうゆうプラザだったり、そのように、どのような施設がいいかは、また検討していただいて、区内施設も視察するということも、ゆとりがあるところで、計画に組んでいただけたらいいのではないかという希望です。","respondent":"松永委員長","answer":"ご意見として頂戴させていただいて、検討します。","voiceIndex":81,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3666#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":19512,"voices":85}},{"id":"r05-20230724-8","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"建設委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区自転車活用推進計画策定に向けた検討状況","agenda":"品川区自転車活用推進計画策定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、今回整備の対象路線がいろいろ追加や削除されているというところで、その中にこの自転車通行空間整備済路線として追加したというのがあったりするのですけれども、今のこのネットワークの中には、整備はされているけれども位置づけられていない、ネットワークの中に入っていないというものがほかにもあるのかどうか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"初めに、第３回協議会でいただいたご意見・ご質問等ですが、大分いろいろなご意見・ご質問をいただきまして、例えばご質問としましては、ネットワーク整備路線を案としてお示ししておりますが、この示された道路を拡幅していくようなイメージなのでしょうかというようなご質問や。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、今後の整備形態のところなのですが、私は一番分かりやすいのが、この青色の舗装をしていくというのが一番その方向・位置が分かりやすいと思うので、それがいいとは思うのですけれども、やはり幅員、幅の問題があると思いますので、そこは恐らく舗装をすると、道路交通法とか構造令とかの問題で幅とかが決まってきてしまうので、狭いところにはできないということだと思うのですけれども。","respondent":"鈴木都市計画課長","answer":"ネットワークの整備方法ですが、ブルーレーン、ナビマーク等の整備というところが基本になろうかと思うのですが、委員からご指摘・ご意見いただいたように、やはりその整備の方法というのはどうしても道路の幅員で変わってくるというところもありますが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"駐輪場の整備もそうですし、形態の通行位置の明示、分かりやすくというのも、やはり利用者を含め、あと車、歩行者を含め、そういった分かりやすくしていくということ、整備していくということが、やはり安全にもつながってくると思いますので、そこはしっかりとよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問させてください。委員の名簿です。見ると、区民公募１人なのですね。それに対して、何か広報とかサポートをすると進むことがあるのであれば、それも一つの自転車の活用。なのでそれをぜひ、どういう形なのかなというところが２つ目です。それと、結局この計画の目的は何でしょうか。前回もそうなのですけれども、これの目標・目的は何なのか、これは何をするためのものかというのを教えてください。","respondent":"鈴木都市計画課長","answer":"それから併せて、区内の６か所の駐輪場の利用者に直接アンケート用紙等をお配りして、アンケートを実施しているというところで、計画の策定にはそうした声もしっかり反映して計画の検討を進めていきたいというところとともに。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、要はネットワークという考え方なのですけれども、簡単に言うと自転車が使いやすいような道路の整備をするという形でいいのですか。しかも２０分ぐらいで持っていかれてしまう。持っていかれてしまうと三千幾らですか、四千円弱のお金がかかるわけです。でも自転車がないと買い物ができないというのもあるので、そこもうまくいろいろ計画の中に入れてもらいたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"やはり店の前で止めて、店をすぐ利用するというのは一番使い勝手としてはいいいのですが、そこを少し歩く形にはなりますが、例えばですが公共の駐輪場に止めていただいて、あるいは違う駐輪場に止めていただいて少し歩くけれども。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"西大井駅の前は駐輪場があります。でも、店舗もやはり責任という、自分たちのお店で買物しているわけだから、その人たちが利便性のいいように努力をするということが必要なのではないですか。ぜひそこをやってほしいので、よろしくお願いします。どうしても前から気になるのが、子どもを乗せっ放しで親が離れてしまう。そういうのもしっかり啓発してほしいです。何かご意見があれば、よろしくお願いします。","respondent":"鈴木都市計画課長","answer":"個々の商店街、様々な取組、各々でやられている方もいらっしゃるでしょうし、そうしたところもできるだけ好事例等も集めて、そうしたところも先ほどのママチャリでの安全な乗車というか利用というか、そうしたところも計画の中では啓発も含めてしっかり行っていきたいと思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"自転車に乗っている方が危険性を感じる場面というのは、恐らく道路、車との関係性だと思うのですけれども、その車の通行状況が自転車に乗っている方の感じ方に影響すると思うのですけれども、この調査のタイミングですが、品川区内で言えば、大きな道路の建設としては補助２６号線が開通したということで、それによって大きく自動車の流れが変わったと思うのです。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区民無作為抽出４,０００世帯のアンケート、それから駐輪場を利用されている方のアンケートというのが、令和４年１１月から令和５年度にかけてですので、もう既に補助２６号線が開通された以降での調査をかけしていますので。","voiceIndex":18,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"キックボードのことなのですけれども、自転車とは別の規制緩和によって、キックボードが自転車道路を走れるようになってということでありますが、逆に言うとその課題としては、自転車においての駐輪場の整備がなかなか進まないのでこういう状態になっていますけれども、今後はそうするとキックボード専用の駐輪場というのでしょうか、それも整備をするようにしていかないと。","respondent":"鈴木都市計画課長","answer":"電動キックボードについても利用の促進を計画の中で位置づけていくのかというご質問ですが、基本的にはこうした法改正によって、手軽に区民の方も利用できるというところは計画の中でお示しして、第一にはやはり安全に利用していただくというところ。","voiceIndex":20,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、またそういった意味での考え方というのでしょうか、要は自宅発ではなく集積場所からの移動ということも、また違うルートが見いだされてくると思いますので、具体的にどういう乗車行動になるのかというのはちょっと見えてこないのですけれども、１０ページの部分とシェアサイクルの部分というのは、自己所有のものなのかどうかとは切り離して考えていくことも。","respondent":"鈴木都市計画課長","answer":"この７ページの今後の取組のところは、これは商店街の方々にヒアリングの中で、ご意見としていただいたというところでございまして、区のほうで今都市計画道路用地を暫定の商店街の駐輪場として、区として東京都から借り受けて商店街に貸し出すというような考えは。","voiceIndex":22,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"要はシェアサイクルなりキックボードポートの関係で言うと、まさに自己所有のものは、途中どのようなところに放置をしたとしても、ほとんどが最終的には自宅に持ち帰りますけれども、逆にこういうレンタサイクルとかキックボードポートの場合は乗捨ての可能性が高くて、それを例えば商店街へ乗り捨ててしまったりすると、また新たな駐輪対策として、新たな課題が出てくる可能性もありますので。","respondent":"工藤交通安全担当課長","answer":"はこちらのほうで駐輪スペースを確保し、それでも駐輪場に止めなかった場合は撤去をするというような形でやっておりますので、引き続きそのような形でやらせていただければというように考えてあります。","voiceIndex":24,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"そうすると、やはり特に商店街を中心とした駐輪対策、違法駐輪の問題というのはなかなか改善されない、なかなか成果が上がらないことにもつながってしまうのではないかなとも思えますので、武蔵小山商店街が取り組んでいるというような記載ではありますが、決してまだまだこれで十分とは地元の者としては思えませんし、現状としては、例えばパチンコ屋に設置された駐輪場に自転車を止めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"何点か。比較的自動車乗車中が少ないですよねということで、見方をお聞きするのが１つです。この一方のお悩みというか課題の解消には至ってないというところと、ご意見・ご要望というのは、要するに例えば商店街とか商店単独ではなかなかマンパワー等も含めて先が見えないのだけれども、だからこういうまちづくりとか行政とか通行抑制とかということに、というふうに理解していいのかという確認です。","respondent":"鈴木都市計画課長","answer":"７ページのその他のところは、まさにこちらも委員ご指摘のとおりでございまして、ルール・マナーの啓発等は私も各商店街のホームページ等を見ましたが、それぞれでいろいろ工夫をされて。","voiceIndex":28,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"それから２点目のほうは、ずっと今この自転車についての計画のご説明があったのですけれども、商店街からは行政等に対して、そのような声が比較的強くあるのだけれどもというところで、区としてはその声をこれから反映させる、この計画以外のところになるのかなとも思うのですけれども、そういったところのお話というのは何かあるのでしょうか。","respondent":"鈴木都市計画課長","answer":"行政と商店街の連携のお話ですが、やはり計画の中には、例えばですが、先ほどほかの委員からもご指摘いただきましたが、これは商店街に限らずルール・マナーのしっかりした啓発等については計画の中でも位置づけて、具体的には行っていかなければいけない取組ですし。","voiceIndex":30,"id":"exchange-013"},{"speaker":"まつざわ副委員長","kind":"確認","question":"２点ほどお聞きしたいのが、資料２の６ページです。災害時における機動性が高いとあって、基本は災害発生時の交通避難というのは徒歩ですよね。何かこれを読み取ると、災害が発生したときは徒歩が原則という中で、これは自転車活用もありなのかなというふうに私は少し感じてしまったので、そこを確認させてください。私もおせっかいで声をかけると逆に怒られてしまうのですね。","respondent":"鈴木都市計画課長","answer":"安全利用のマナー啓発ですが、計画の中で書いて、それをどう具体的に実行していくかというところで、現在も交通安全の教室ですとか、そうしたことは区としても行っているわけですが。","voiceIndex":33,"id":"exchange-014"}]},{"id":"topic-02","title":"都市計画道路の計画変更およびそれに伴う用途地域等の変更に係る説明会の開催","agenda":"都市計画道路の計画変更およびそれに伴う用途地域等の変更に係る説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、現道に合わせるということなのですが、そうすると実際の現地としては変わるところはないということなのか、そこのあるのかないのかというところを伺いたいと思います。それが南側のところですか。先ほど、この変更によって既存不適格はないということだったのですけれども、ほかにも住民に考えられる影響などがあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"基本的には既存不適格について、用途地域等の変更によって、今建っている建物が法律的に不適格の状態にならないかどうかはしっかり確認をしておりまして、ならないというところでございまして、その後に所有者、あるいは居住者の方に何か影響が出るかというと。","voiceIndex":39,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"今、既存不適格のお話がございましたが、ないということですが、今回の変更に伴いまして、水色の部分は容積率が３００から５００に上がっていたり、オレンジのところも３００から４００に上がったり、一方で紫が４００から３００に下がったり、その下のピンクも４００から３００まで下がっているということなのですが、いわゆる固定資産税の観点で言うと、容積率がアップすれば評価は上がるように思えますし。","respondent":"鈴木都市計画課長","answer":"それぞれの権利者の方には、ご説明かあるいはオープンハウス型・教室型の中で、ご質問について丁寧に回答を差し上げたいというふうには考えていますが、例えばこの資料の中で、3)の紫の斜めのところにつきましては。","voiceIndex":42,"id":"exchange-016"}]},{"id":"topic-03","title":"品川区無電柱化推進計画の一部改定","agenda":"品川区無電柱化推進計画の一部改定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、新たに林試の森周辺の２路線を加えるということで、現在もこの無電柱化の候補路線というのがあるわけなのですが、そこを通り越してというか飛び越えて、今回この林試の森周辺を進めるということなのですけれども、その理由を伺いたいと思います。","respondent":"森道路課長","answer":"現在道路課のほうで執行委任を受けまして道路の設計を進めているのですけれども、それに合わせて無電柱化を実施することができればということで、今回その優先整備としての路線として挙げさせていただいたです。","voiceIndex":48,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、約７％ということで、なかなか道のりは長いという感じですけれども、ぜひこれは防災性の観点からも含めて進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"地図を見ると、ピンクのところ、これが候補ということで優先順位は低いのかなとは思っているのですが、具体的に申しますと滝王子通りとかまだなのかな、早くしてほしいという地域の切実な思いがあるのですけれども、無電柱化と同時に、街灯があると当然電柱がなくなっても意味がないです。それはどういう工夫をされるのでしょうか。","respondent":"森道路課長","answer":"街路灯です。電柱があるところについては、できるだけ電柱のところに共架と言いまして一緒につけさせていただいているというところで、夜間の安全を確保していますが、それが電柱がなくなってしまいますと、やはり街路灯として単独で設置をする必要があろうと思っています。","voiceIndex":52,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、このピンクのところのほかに次の候補というのはないのですか。例えば三間通りなどというのはバス通りのところもかなり狭いのです。そういう計画はあるのでしょうか。","respondent":"森道路課長","answer":"費用もたくさんかかってまいりますので、一つ一つ進めていくしかないのですけれども、区といたしましては、こういった木密整備推進課で行っておりますような防災性の向上に資する事業に合わせ、できるだけ無電柱化を進めていきたいと考えておりますので。","voiceIndex":54,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、無電柱化というのは非常に期待される部分だと思いますので、計画的にしていただきたいと思います。最後に整備方式というのがあるのですけれども、１８ページ辺りでしょうか。非常にコストがかかるというお話だったのですが、大分ここは改善されているのでしょうか。まだまだ、技術のほうが発展されてなくて、相変わらずコストがかかるという方向でしかないのか、その現状だけ教えてください。","respondent":"森道路課長","answer":"ですので、劇的な改善方法はなかなか難しいところですけれども、そういった使えるものを使っていったり、あるいは発注方法を考えたりとかというようなところで、フレキシブルな事業遂行ができればと思っています。","voiceIndex":56,"id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"あそこは分かるのですが、6)番のほうはこの下の拡大図の今のこの線形に並行して拡幅されるということでいいのでしょうか。そちら側への接道も、そこまで達すればまさに避難通路としての意味合いが出てくると思うのですが、なので確認したいのは、6)番のほうはこれで終わりということではなくて、今後も延長する可能性はあるのかというところを確認したいと思います。","respondent":"森道路課長","answer":"5)番につきましては、公園側に一方的に２ｍ程度拡幅を考えているところです。6)番につきましても、今財務省の旧官舎といいましょうか集合住宅がありますけれども、そちらの方向に２ｍ程度拡幅する予定です。","voiceIndex":59,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"それと、その検討中の4)のところなのですけれども、これはやさしいまちづくり推進計画事業の範囲にも入っていますし、まさにその同じ路線の中でのいわゆるやさしいまちとしてバリアフリー化を進める路線の中に、これが並行して地中化の対象にもなっているということなのですが、これもぜひやさしいまちづくりを進めるにあたって進めていただきたいのですが。","respondent":"森道路課長","answer":"歩道もございませんので、例えば地上機器を置くというよりは、戸越銀座であったり旧東海道のような、柱の上にトランスを載せるというような形になるのかなというふうには考えていますけれども、やはり商店街の皆様と一緒に進めていく必要がありますので。","voiceIndex":61,"id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"直接関わらないのですが、こういう拡幅も含めた道路整備というところで、点字ブロックの話になってしまいますけれども、点字ブロックというのは、旗の台商店街とかはたしかもう既に備わっていると思うのですけれども、個別にはまたいろいろ意見がありますけれども、ないところについては当然点字ブロックも同時に検討、敷設されるという理解でよろしいのでしょうか。","respondent":"森道路課長","answer":"無電柱化としては電柱が倒れないように、あるいは景観の面というところでの目的で電柱を撤去していこうと考えているところでございまして、点字ブロックにつきましては視覚障害者の方のためにバリアフリーというところで、旗の台のように重なるところもありますけれども。","voiceIndex":64,"id":"exchange-024"}]},{"id":"topic-04","title":"バリアフリー特定道路整備工事","agenda":"バリアフリー特定道路整備工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"どこがどうなるのかというところを伺いたいと思います。それで、工事期間が７月１４日からなので、もう工事が始まっているということなのですけれども、町会とか周辺住民への説明というのはどのように行われているのかと、理解が得られているのかどうかというところで伺いたいと思います。","respondent":"森道路課長","answer":"十分ご理解いただいているとは思いますけれども、工事にあたりまして、具体的なご要望も真摯に対応してまいりたいと考えております。","voiceIndex":70,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料のところでは、変更点は、そうするとだから今の歩道は３ｍよりもどこでも狭いということですね。変更点は分かりました。ということで、ぜひこうしたバリアフリー化というのを進めていっていただきたいと思います。先ほどあった中でも、区道のところは半分ぐらいという感じだったので、ぜひ、今ほかのところも検討しているということでしたけれども、それは進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"品川区で２４路線・区間あって、そのうち２１路線・区間が完成ということなのですが、すみません、私も少し不勉強で、完成したところが具体的にどういうところだったのかを見た上で質疑をすべきだったと思いますが、要はそもそものルート選定の基準が、国の取組なので国道から引っ込んだ路線が対象になるということ、ただ康済会病院だと都道だったりするので国道ではないのですが。","respondent":"森道路課長","answer":"国道からというふうに、区道の場合は国道からと申し上げておりますけれども、国道のほうも、五反田駅からそこに至るまでの国道と、そこからＮＴＴ東日本関東病院に入るまでの区道というような位置づけをされているところですので、国道と、都道もそうですけれども。","voiceIndex":74,"id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"確認ですが、そうすると、品川区におきましては２４路線がその対象であり、これが完成すれば、その目的は、もうこの法律に基づいた目的としては完成されるということで、新規の指定をする必要性のある場所はもうないという考え方でいいのでしょうか。","respondent":"森道路課長","answer":"東京都福祉のまちづくり条例に基づきまして、歩道の勾配の改善でありますとか、そういったものは道路改修のたびに進めていくべきものだろうと考えておりますので、それは必須だろうと考えておりますので、そういった道路改修工事の機会に合わせて。","voiceIndex":76,"id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"聞かれなかったので、２４分のこれで２２か所目が完成するということで、あと２か所はどこですか。","respondent":"森道路課長","answer":"そこにつきまして、路肩のカラー化であったり、誘導ブロックの整備であったりというようなものを進めていきたいと考えておりますけれども、今補助２６号線自体が歩道の整備の途中ですので、そういった機会、そういった部分の情報を逐次もらいながら。","voiceIndex":79,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":36801,"voices":87}},{"id":"r05-20230724-9","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"文教委員会","time":"午後 １時００分～午後 ３時３６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年度第１回家庭教育講演会","agenda":"令和５年度第１回家庭教育講演会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"内容や講師の選定などは事務局職員で行っているということなのですけれども、今回の講演の内容と講師を決めた考えというか理由を伺いたいなというのが１つです。第２回は子どものレジリエンスについて講演予定ということなのですが、これは同じ方なのでしょうか。最後に、周知なのですけれども、どのように行うのかというのを具体的にお願いします。","respondent":"宮尾庶務課長","answer":"第２回につきましては、資料に記載のとおり、子どものレジリエンスについて、同じ平野真理さんにご講演をいただく予定で、今、進めているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"関連して、これは区教育委員会がやるものですけれども、ＰＴＡに委託して実施している家庭教育学級なのですが、今年１月の文教委員会で、保護者の声を紹介して、ガイドラインについて伺ったのですが、そのとき、令和５年度に向けてガイドラインを最終的に今つくっているのですというご答弁でしたけれども、どのようなものになったのか、もし変更した点などあれば。","respondent":"宮尾庶務課長","answer":"毎年、ＰＴＡの皆様に向けて、事務的な書類の作り方ですとか、そういったものを中心にご案内しているガイドラインですけれども、１点、変更点といたしまして、例えば企画をいただくときに、特定の考え方、宗教ですとか。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"学校選択制の運用等","agenda":"学校選択制の運用等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１の１行目なのですけれども、住基人口と各学校の入学率より人口は緩やかに増加とありますけれども、この入学率というのはどういう意味なのか伺いたいのと、あと２行目ですが、これは区全体の話だと思うのですけれども、今後の再開発等マンション建設計画により、必要な教室数も増加とありますが、区教育委員会による区全体の必要教室数の予測検討において。","respondent":"柏木学務課長","answer":"影響を与える再開発ですが、今どれがというものはございませんけれども、大きなマンション計画、何百戸とかというものについては、それなりに影響を与えるものと考えています。","voiceIndex":14,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"再開発と書いているものですから、単なる一般的な民間のマンションではないのかなと思って、なおかつ、必要な教室数も増加という見通しを立てているもので、そこら辺、どういった再開発の計画を考慮に入れて、こういうことを書いているのかなということで伺いたいというのが一つ、後で教えてください。","respondent":"柏木学務課長","answer":"それと、最大２８教室以上の対応につきましては、３の(2)に記載していますけれども、学事制度審議会のほうで通学区域の変更を含めた学事制度を検討いただき、その結果を受けて、制度設計を考えてあります。","voiceIndex":16,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのが、１つ目が、この予測資料は誰が作成したのかというのが１つ。それと、表にある新１年生住基数というのは何を根拠に算出しているのかというのが２つ目。４つ目は、大型マンション建設計画というのは、どのようにこの予測に反映していくのか、どういう関係部署との連携になっているのか、そこら辺、具体的に伺いたいなと思います。","respondent":"柏木学務課長","answer":"ですので、その都度、内容等については教育委員会でも認識し、必要に応じて、計画１件１件について、まちづくりの所管のほうに意見としては出しています。","voiceIndex":18,"id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"最後のところなのですが、では、２の(1)の表というのは、そうした照会があった集合住宅の増加数を加味している内容だということなのかを確認したいのと、それと、照会とありましたけれども、どこから、どのようなタイミングで、どんな目的で照会が来るのか、そこら辺、お伺いします。","respondent":"柏木学務課長","answer":"加えていくという状況です。マンション等の計画ですが、４０戸以上のマンションの場合は、教育委員会にも、業者、デベロッパーというのですか、から直接照会が来ます。それに基づいて、教育委員会でも把握するという状況になってあります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"そうですかと思ったのですけれども、何のために、どんな内容で紹介が来るのかというのと、どんなことが聞かれているのかということを知りたいのと、あと、その都度、想定数に加味しているということなのですが、今出されている資料の時点でいうと、どこまでが加味されているものなのか。例えば何年後に建てるマンションが加味されているかとか、そこら辺を最後にお伺いしたいと思います。","respondent":"柏木学務課長","answer":"就学人口にどこまで加味しているかというと、今、計画されているものについては全て加味しているという状況になります。ですので、これから大型のものをつくるというものまでは、ここには入ってございません。","voiceIndex":22,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと答弁漏れがあったかなと思うので、もう１回聞くのですが、分かりました。照会というのは、何か聞かれているということですよね。区教育委員会としては、その照会があったときに何かを返す照会だったとしたら、そういう照会があったときに何を返しているのか、どういう回答をしているのかというのがもしあれば、伺います。","respondent":"柏木学務課長","answer":"こういう計画を提出する予定という形で、事業者のほうから今こういうものを計画していますという情報が来るです。","voiceIndex":24,"id":"exchange-008"},{"speaker":"吉田副委員長","kind":"質問","question":"となると、品川区は今、人口も増えておりますし、再開発も進む中で、当然子どもも増えていくということだと思うのですが、その辺を今後どのように見込んでおられるのか、まず伺いたいと思います。","respondent":"柏木学務課長","answer":"城南小学校のもともとの見込みですが、全部で１８学級という見込みと記憶しています。選択制を継続するのかということですけれども、現時点では、選択制はこのまま進めていくということで考えてあります。","voiceIndex":27,"id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問","question":"ということは、やはり城南小学校を建てたときの見込みは大きく狂ったと言わざるを得ないということなのでしょうか。そうなるのではないかなと思うのですけれども、その辺についてどうお考えなのでしょうか。それで、そう思うと、今、工事が進んでいる学校が幾つかありますよね。例えば浜川小学校とか第四日野小学校とか、その辺が今進んでいるのかなと思うのですが、その辺についても教えてください。","respondent":"柏木学務課長","answer":"城南小学校の見込みが間違っていたのではないかというご指摘かと思いますが、結果としては、見込みを大きく上回っているということがありますので、そういうご指摘を受けてもしようがないなという感想は持ってあります。","voiceIndex":29,"id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問","question":"どうしてもそこに住んでいる子どもたちには公教育が適切に提供されるべきだと思うのですけれども、例えば再開発や何かの計画のほうに、今のこの状況の、この地域で受け入れられる生徒数はここまでなので、その辺は考慮してほしいというような、そういう庁内での意見の出し方とかいうのはないものなのでしょうか。その辺が不思議なのですけれども、伺いたいと思います。","respondent":"柏木学務課長","answer":"ただ、その後につきましては、所管のほうでの検討、判断という形になりますので、教育委員会としては、意見は提出させていただいているところです。","voiceIndex":31,"id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"いろいろ地域の中で、学校の教室を活用すればこういう活動もできるというようなことはあると思いますので、ぜひそのことも加味して、想定よりも増えるということは加味して、子どもたちの最適な教育環境を維持するという方向で、ぜひ今後も学校の建て替えとか、そういうことは考えていただきたいと思います。もし何かコメントがあったら伺いたいのですが、いかがでしょうか。","respondent":"柏木学務課長","answer":"今改築している学校等につきましては、今後、就学人口が減った場合でも、そういう転用も含めて考えた上での設計、建設をしています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"何点かお伺いします。一番最後のところで、通学区域の変更を含めた学事制度の検討となっていますけれども、これはなかなか難しい現実があるのかなと思っている中で、今後、通学区域以外に何が考えられて、令和１１年、対応していくのか、ビジョンを教えていただきたいのと、区教育委員会として、新しい学校を建設するという考え方があるのかどうか、教えてください。","respondent":"柏木学務課長","answer":"学事制度のほうで、通学区域変更を含めた学事制度の検討を行っていただいておりますが、通学区域変更以外での方策についてですが、その点も含めて学事制度審議会で審議いただくです。","voiceIndex":36,"id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"人生において一番高いだろうと言われる住宅の購入に当たって、そういった一つの選択肢となるような事柄を、区としてもしっかりと情報提供してあげてほしいのと、それをなるべく早い段階で、このような想定をしたのであれば、早急にある一定の方向性を示してあげなければ、購入した後に、実はここ、区域を変えるのですよとなったら、非常に厳しい状況になってしまうので。","respondent":"柏木学務課長","answer":"今、委員からあった江東区ではないかというお話ですけれども、うちのほうに情報がないものですから、そこら辺は情報を得ながら研究してまいりたいと思います。","voiceIndex":38,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、城南小学校の例、また学校が新しくなれば、希望される、つまり引っ越してこられる方も出てくると思うので、その辺の浜川小学校の見込みをもうちょっと具体的にお願いしますというのが一つ。２つ、お願いします。","respondent":"柏木学務課長","answer":"浜川小学校の学級数の件ですが、今、浜川小学校は最大３０クラスまで対応できるような形でつくってあります。就学人口の見込み等でいきますと、それで十分だろうです。","voiceIndex":41,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。３０クラスマックスということで準備しているということですが、やはり城南小学校の例のように増えていく可能性もあるので、恐らく転用も含めて３０までいけるという計画を立てていらっしゃると思うのですが、そこを超えたときのことも併せて検討していきながら、今後の小学校の運営をしていただきたいと思いますが、その点、浜川小学校についてはいかがでしょうか。","respondent":"柏木学務課長","answer":"繰り返しになりますが、現在、推計いたしまして、３０クラスあれば、ある意味、それなりの余裕があるという部分ですので、今後、どこかで土地が生まれて、大型マンションができたとしても、ある程度までは対応できると考えています。","voiceIndex":43,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後、１つだけ付け加えて。浜川小学校は特別支援学級があるので、そこに所属というか入っているお子さんたちも増えてきているので、その子たちの教室に、しわ寄せがと言ったらいけないのですけれども、そういうことのないように、特別支援学級の教育環境はきちんと維持しながら、学級増に対応していただきたいと思いますが、その点、お願いします。","respondent":"柏木学務課長","answer":"今、委員からございましたように、普通学級を優先して特別支援が必要な子どもの対応にしわ寄せがいくというのは、教育としては最悪なパターンですので、当然そういうことはないようにしてまいります。","voiceIndex":45,"id":"exchange-017"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"精査の上、不正がということになりますと、結果についてもぜひ報告してもらいたいと思いますので、よろしくお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それから次は、先日、すまいるスクールのお弁当のことをお尋ねしたのですが、あれも、一般質問でほかの委員が質問して、私、尋ねたのですけれども、それがなくても、すまいるスクールの例のお弁当については多くの皆さん、多くの議員も期待しているので、そこでお話ししていただけなかったので、あえて質問したのですけれども、それが夏季休業に入ったので。","respondent":"染谷子ども家庭支援センター長、大澤子ども育成課長、中谷指導課長","answer":"併せて、９月に、予定ですけれども、お子さん向けのアンケート調査の実施等を予定している部分もありますので、８月の文教委員会の際に。すまいるスクールの仕出し弁当の件ですけれども、前回の文教委員会で、その他で報告を予定しておりましたが、所管質問で出ましたので。教職員の服務事故につきましては、教育委員会の非公表の場で報告させていただいているということがあります。","voiceIndex":57,"id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問","question":"ヤングケアラーのほうは、ぜひお願いします。それから２番目のすまいるスクールの仕出し弁当は、現状で分かるところで結構ですので、どれぐらい申込みの方がいらっしゃったのかぐらいは教えていただけると、もう夏季休業が始まってしまっているのですが、知りたいところではあります。ごめんなさい、現状の申込みというのですか。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"現在把握していないということで、分かりました。始まっていると勘違いしたので、申し訳ございませんでした。それはもちろんそれでいいと思うのです。件数だとか、こういうことで１名あったとかということは、非公表ですから議事録を見ても私たちは分からないので、もし可能ならば文教委員会でそういった報告もしていただけるとありがたいと思いますが、いかがでしょうか。","respondent":"米田教育次長","answer":"教員の服務事故に関しましては、教育委員会はそういうような形で非公表の場で行っているものです。文教委員会等の委員に際しましては、その内容に応じ、勘案しながら、確実に委員の皆様方に伝わるような方策について、今後、適切に対応していければと思ってあります。","voiceIndex":64,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5104#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":14934,"voices":67}},{"id":"r05-20230724-5","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"総務委員会","time":"午後 １時００分～午後 ２時０３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"行政評価","agenda":"行政評価","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ここにも書いてあるのですけれども、改めて導入した目的、なぜ実施するのかという背景とともにご説明いただきたい。ここにはまだ名前や名簿などは出ておりませんけれども、いずれにしても委員構成について、メンバーと、肩書というのでしょうか、学識経験者だったら、どこどこ大学の何とか学部とか、そういうのも、メンバーはしっかり公表していただきたいと思うのですけれども、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価の今までとの違いというところですけれども、今回、予算事務事業の全てを対象としているというところと、先ほど申し上げた新公会計制度基本方針に基づきまして実施するというところで、今までの人件費や減価償却費といったもののフルコストが把握できるですとか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろな外郭団体だったらコストや資産などを持っているでしょうけれども、区の一つ一つの事業となると、どういうふうになるのか、いまいち、まだイメージがよく分からないのですけれども、福祉を切り捨て、住民サービスを減らしていく。そうした評価は進めていただきたくないと思うのですけれども、一言、伺いたいと思います。それもご説明いただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"６番の評価のところの、所管評価、企画部評価というところで、先ほどお話にありました、Ａ、Ｂ、Ｃ、Ｄを、各所管あるいは企画部でつけていくという形です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"今回、行政評価シート、またいろいろ変わってきたのですが、これはどこかの自治体で何かやっているところを参考にされたのですか。それとも独自でこれをつくり上げたのか。それをお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"こちらの行政評価シートですけれども、他自治体が使っているもの、そのままということではなくて、そういった他自治体の動向や内容をしっかりと吟味させていただきながら、品川区の行政評価にふさわしいといいますか、かなうような形で、シートを作成・検討したものです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"区民の方は窓口に来て、受付、区のやり方、対処の仕方、処理の仕方、いろいろお願いに上がったときに、皆さん、私たちはどういうふうにすればいいのですかというときに、やはり区の方が、あそこに行けば、事業部に行けばいいんですよ、ここに行けばいいんですよなど、様々あると思うのですが、そういう区民の率直なご意見を、やはりどこかに取り入れていかないと。","respondent":"吉岡政策推進担当課長","answer":"これが、区議会議員の皆様のように精通している方なら説明がスムーズに済む部分もあるのですけれども、こういった外部の方にお願いするに当たっては、今回、事前勉強検討会というところを設けさせていただいて、２つの分野につきまして。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"何しろ、これは相当仕事が増えてしまうのではないかと思うので、すごく心配しているのです。それで、企画部でまたチェックするということですけれども、やはり人間関係というのがあるじゃないですか。やはり、お互い知り合い同士がチェックするということになると、どうしても少し、客観性に至るまでに、そこに気持ちが入ってしまうので、その辺を厳しく見ていただければありがたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"これについては、私は一般質問でもやったので、あれなのだけれども、私は今ではないと思っていて、もう少し先かと。私は最初のところで伺いたいのは、これはやってもいいのだけれども、今皆さんがやられてきたことは、非常にそれで、それはそれなりに合っていると思う。私はパフォーマンスで終わってほしくないと思っているので、きちんと実りあるものにしてほしいと思うのが１つ。だから、前もって聞きたい。","respondent":"吉岡政策推進担当課長","answer":"委員構成のところにつきましては、今年度から政策評価はまた改めて行うというところで、ご意見を頂いた部分につきましては、今後の選定、次年度以降のところで検討するというところと、まずはこの政策評価委員会で、皆さんが活発にご意見を頂けるような進行。","voiceIndex":16,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つは、どうしてもこういうことをやると、財源を何か生み出すための評価をして、財源をカットして、その財源がこれだけ出ました。それをここへ振り分けて、新しい事業へこういう展開ができましたということは、私はそこの評価はしてほしい。いろいろ評価をして、やるならいいけれども、そういう発言が出てくるようなやり方はやめてほしい。そう思うのは、要望だけにします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"本当に久しぶりというか、新しい取組になっていると思うので、やるからには充実したものになってほしいと思うのですけれども、評価シートのほうをお伺いしたいのですけれども、他の自治体ですと、人件費のところをある程度細かく見るということをやられている自治体が結構あるかと。","respondent":"吉岡政策推進担当課長","answer":"区の職員という形で、会計年度任用職員が幾らかなどといった話ではないのですけれども、こういった構成比が高いことによって、あるいは委託事業のところでできることはないかとか、そういった判断につながるというふうに、こちらとしては考えているところです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"多分もう、１回作られているシートなので、なかなか難しいところはあると思うのですけれども、その辺りもぜひ今後お考えいただければと思います。そうしたときに、その事業の達成度合いなど、どのぐらい頑張ったのかというところが、しっかりと見られるのかなとも思うのですけれども、その辺りは何か考慮されているのか、お願いいたします。","respondent":"吉岡政策推進担当課長","answer":"当然ながら、そこで実績が落ち込んでいるですとか、その前の実績というところに関しましては、取組内容の実績や指標の達成状況といった欄でしっかりと書いていただくことによって、令和２年度からの実績だけで判断するということではなくて、その前の実績。","voiceIndex":22,"id":"exchange-009"},{"speaker":"塚本副委員長","kind":"質問","question":"事務事業評価、(1)のほうですけれども、ここのスケジュールで６月から８月に所管部局の一次の評価があって、企画部が二次の評価ということで、こういう評価を来年度の予算案にどういうふうに反映していくのかというところをお聞きしたいのですけれども、ここで、ある程度、ＡとかＢとかというランクづけの評価が出てきていて、結局そこで、この事業については例えばもうなしとか。","respondent":"吉岡政策推進担当課長","answer":"ここは評価に基づいて、各所管でまた新しい施策の見直しや改善、あるいはそこから変わっていく事情といったこともありますので、やはりこの評価を踏まえたところで、予算要求、予算編成をしていくというようなところです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"塚本副委員長","kind":"質問","question":"そうすると、各所管へ、企画までの評価が終わって、それから総務委員会に報告もして頂くということになっていますけれども、また、議会への評価結果資料の提出。こういうものが、来年度の各所管の予算編成に、どの程度反映されるというか、影響されるかというのは、どのように期待されているというか、思われているのか。そこをお聞きしたい。","respondent":"吉岡政策推進担当課長","answer":"こういった改善や見直し、あるいはスクラップといいますか、廃止となる事業の評価をさせていただいたときに、やはりそれに、何というのでしょう、今後新しい展開が見込めないものに関しては、そういった評価をつけたものに予算編成をしていく形にはなるかと思うのですけれども。","voiceIndex":27,"id":"exchange-011"},{"speaker":"塚本副委員長","kind":"意見","question":"それとも、このテーマで、ある意味、ブレーンストーミング的に、何だろう、品川区のあそこは危ないねみたいな話も含めた形でやるのかというのが、イメージとして、どういう評価の中身というか、やり方をしていくのかと同時に、これをまた今度、区の政策に反映して落とし込んでいくというのは、どういう流れを見込んでいらっしゃるのかを、最後に聞きたいと思います。","respondent":"吉岡政策推進担当課長","answer":"政策評価の２つのテーマについてですけれども、イメージ的には、総合実施計画に載っている政策の柱の単位のところで、政策の評価を行っていくというところで、当然ながら政策だけだと抽象的な部分がありますので、こういった事務事業。","voiceIndex":29,"id":"exchange-012"}]},{"id":"topic-02","title":"大井第三地域センター・区民集会所移転に伴う内装工事請負契約","agenda":"大井第三地域センター・区民集会所移転に伴う内装工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回、区民集会所移転に伴う内装工事ということで、現在、民間の共同住宅を建てて、その道路側に、大井第三地域センター、新たに区民集会所をつくるのですが、ここの全体は民間の土地であり所有物なのですか。それとも、大井第三地域センターは、これはもう品川区のものなのだというような、所有区分はきちんとなっているのでしょうか。","respondent":"佐藤（聡）経理課長、小林施設整備課長","answer":"したがいまして、この地域センターおよび区民集会所部分については、賃借して区で利用するという形です。私から後段の部分について、一般論となりますが、こういった民間施設の場合ですと、いわゆるテナント工事と言われております、借りるほうが必要となる機能については、基本的には借りるほうで工事を行うというのが原則ですので。","voiceIndex":35,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"もしここを退去するときは、居抜きということで、そのまま残していっていいのですか。それとも、やはり区で全部、内装を現行に戻すというのは、もともとがないのだけれども、それはどういうふうに。参考のためにお聞かせください。","respondent":"小林施設整備課長","answer":"これも一般論となってしまいますが、基本的には原状復旧が原則になりますので、区で行った工事の部分については、区で撤去してお返しする形になります。","voiceIndex":38,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"居抜きで使ってくれてもいいけれども解体費分をどうやって、では逆に払うから売却金額から引いてくれとか、いろいろなやり方があると思うのだけれども、こういうのは原則、誰が考えるのか。企画部で考えるのか。誰が考えるのか。それは経理課で考えるのか、企画部の誰かが考えるのか、施設整備課長がやるのか分からないけれども、各所管でやるのか、どういう判断を品川区はしているのか。","respondent":"佐藤（聡）経理課長","answer":"ただ、申し上げたとおり、様々な形がありますので、その都度、検討して、検討体制についても検討されて、チェックしていくということになろうかと思います。","voiceIndex":41,"id":"exchange-015"},{"speaker":"澤田委員","kind":"質問・要望","question":"設計図のほうですけれども、質問が２点ほどありまして、まず授乳室が２階にあると思うのですが、授乳室の内容について教えていただきたいと思っています。おむつ替え台や電子レンジなどがあるのかという点です。すみません。もう一点ありました。この場所は一般開放できる場所なのか、それともできない場所なのかを教えてください。","respondent":"小林施設整備課長","answer":"３点のご質問のうち、まず授乳室ですが、２階に設置しておりますが、キッチン、いわゆる給湯関係は設置しております。授乳するための椅子等が設置されている状況です。ですので、いわゆるミルクをつくる機能は設置されております。","voiceIndex":44,"id":"exchange-016"},{"speaker":"澤田委員","kind":"質問","question":"最初の授乳室の件ですけれども、ミルクをつくる電子レンジなどは、聞き逃したのですけれども、給湯室にあるのですか。授乳用の椅子はあると今おっしゃられたと思うのですが、特におむつ替えなどの台はないということですか。","respondent":"小林施設整備課長","answer":"温めることもできるかと思います。それからおむつ台ですが、何でしょう、そんなに大きな授乳室ではございませんので、たしか各トイレに、おむつが替えられるシートを設けてありますので、そちらで対応できるかと考えています。","voiceIndex":46,"id":"exchange-017"},{"speaker":"澤田委員","kind":"質問","question":"屋上スペースの件ですけれども、太陽光パネルはあの部分だけで、あとの部分は特に何もしないというか、何か例えば、せっかくスペースが空いているので植栽したり、手入れが楽なハーブだったりを植えたり、そういうので緑を増やすことができたりするのではないかなどと思ったりする部分もあるのですが、一般開放は通常しないということですけれども、例えば太陽光パネルの部分に人が入らないようにして。","respondent":"小林施設整備課長","answer":"本施設につきましては、様々設計を進めていく中で、今回使用しないという判断ですので、今の設えの中では日常の中で開放することは想定してございませんが、当然、屋上には設備機器があったり太陽光パネルがあったりということで。","voiceIndex":48,"id":"exchange-018"},{"speaker":"澤田委員","kind":"質問・要望","question":"最後に要望ですけれども、事務室や会議室など、いろいろ施設はあるのですが、その中でちょっと座れるような場所が、設計図を見た限りではないので、もしあれだったら、スペースの問題もあると思うのですけれども、駅などにあるような、ふだんは収納されているのですけれども出したら座れる椅子みたいなものなどがあると、高齢者の方などが、少し休めたりするかと思うので、最後のは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-019"}]},{"id":"topic-03","title":"品川区立五反田産業文化施設内イベントホール舞台照明設置その他電気設備工事請負契約","agenda":"品川区立五反田産業文化施設内イベントホール舞台照明設置その他電気設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここも先ほどと同じような条件でお借りするのですが、先ほど石田秀男委員からも少し質問が出ましたけれども、こういう場所に民間が建てるものに対して、誰かやはり品川区の中で、そういう部署、人員、交渉人という人はいるのですか。民間に「ちょっと貸してください」とか、すごいことだと思うのです。それを分かる範囲で教えてください。教えてください。","respondent":"佐藤（聡）経理課長、小林施設整備課長","answer":"全庁の中でこういったところを専門にということですけれども、先ほどの案件のご回答にもつながりますけれども、基本的にはそれぞれの所管の所掌事務の中で受け持った事業の一つとして、各所管で。今回、区で行う工事につきましては、もともと行っている工事の施工者が終わった後にやる工事になりますので、もともとの工事、今やっている工事につきましては、今年の１２月までに終わる予定ですので、我々のほうにつきましては。","voiceIndex":55,"id":"exchange-020"}]},{"id":"topic-04","title":"バリアフリー特定道路整備工事請負契約","agenda":"バリアフリー特定道路整備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここの状況、現場を見た限りでは、すごくきちんと舗装されていて、整備もされていた状況でした。ですけれども、点字ブロック、視覚障害者誘導用、基本的には、それをつけるために、設置するために今回やるという考え方ですよね。その点についてお聞かせください。段差解消とか勾配の改善とかありましたけれども、そんなに問題ないかと思ったのですけれども、その点について分かる範囲で教えてください。","respondent":"佐藤（聡）経理課長","answer":"委員からもご指摘がありましたけれども、点字ブロックですとか、車道との段差を解消することによって、よりバリアフリーに使えるようにという意図で整備するところです。","voiceIndex":62,"id":"exchange-021"},{"speaker":"松本委員","kind":"質問","question":"今のところで、幅員の拡幅もするというようなお話かと思うのですけれども、写真を拝見すると、結構、植栽があるかと思いますので、道路の幅、歩道の幅を広げても、結構、植物があると、思った以上に狭いというところが、区内でも幾つかあるように見えておりまして、ここの部分は拡幅された上で、植栽、植物、街路樹を含めて、この辺りはどのぐらいのスペースを取るような計画になるのでしょうか。","respondent":"佐藤（聡）経理課長","answer":"聞いている限りということになってしまうので恐縮ですけれども、歩道に関しては、現行の１.８メートルから２メートルに拡幅すると聞いております。","voiceIndex":65,"id":"exchange-022"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"伺いたいことは、直近の委員会という意味では今日の総務委員会ですけれども、区議会、総務委員会への報告についてはどういうふうに考えているのかという点と、いずれにしても再発防止策、特に今回、管理職ということもありますので、さらに重いと思うのですけれども、その点についてはどう考えているのかという点をお伺いしたいと思います。","respondent":"崎村人事課長","answer":"懲戒処分の公表につきまして、委員会への報告についてというお話ですけれども、これまでの取扱いとして、総務委員会にご報告させていただいたものにつきましては、例えばマスコミ等で職員が逮捕されて報道があったものについて。","voiceIndex":72,"id":"exchange-023"},{"speaker":"中塚委員","kind":"意見","question":"決してあってはならないことだと思いますので、今、説明にもありましたが、綱紀粛正と服務規律の保持の徹底をよろしくお願いしたいと思います。区長もコメントを発表しておりますけれども、区長の任命を行った責任も、やはり生まれてくると思うのです。やはり４月２２日というのは重いと思うので、その点についても最後に一言コメントをいただけたらと思います。","respondent":"崎村人事課長","answer":"今お話にありましたように、事件発生から区への報告がかなり、２か月近く遅れていたということ、また今回の事案については、事件が発生してから、再度、飲酒によって職務に影響があったといったこともございましたので、この懲戒処分の公表のその他の部分にありますように。","voiceIndex":74,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"人事について少し、１点だけお伺いしたいのですが、今、マイナンバー総点検をやっていて、各自治体が点検作業に追われていて、すごく負担が増えているとお聞きしているのですが、品川区も総点検をもちろんしていると思うのですが、その辺に相当負担がいってしまっているのですか。人を回しているとか。少しその辺を、いや、全然やっていないのか、もう終わったのか。教えてください。","respondent":"崎村人事課長","answer":"特にマイナンバーの総点検に関して、所管から例えば人員の要求といったことでご相談というのはないですけれども、恐らく今後、点検の内容ですとか、詳細が国から示されるかと思いますので、そういったことについて戸籍住民課等から人員配置についてのご相談があったときには。","voiceIndex":78,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"その負担ということで、分かる範囲で教えてください。","respondent":"横田情報推進課長","answer":"現在、国から、どれぐらい負担があるか、どういう事務を行っていくかという調査が来ていまして、それを１回国に戻しまして、それから国からの調査が再度、こういう調査をしてくださいというのが秋頃の予定になっています。","voiceIndex":82,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2272#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":21281,"voices":85}},{"id":"r05-20230725-14","meetingId":"r05-cm07","date":"2023年7月25日","dateIso":"2023-07-25","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"午前中の新庁舎整備に係る説明会でも質疑が様々ありましたけれども、しっかりと受け止めていただきたいと、要望だけ言っておきます。新庁舎整備の基本計画について、午前中の資料も手元にあるのですけれども、品川区新庁舎整備基本計画の中でゾーニング計画というものがありまして、たしか４２ページだったと思うのです。そこで、エレベーターのことなのです。ご説明いただけますでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"しかしながら、このエレベーターの数につきましては、今後、低層・高層を分ける必要があるのかなど、様々な条件により、台数等々が変わってきますので固定ではありませんが、動線としては区分するような形で考えているところです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、様々、動線も検討されるということだと思います。今の説明の中で低層・高層の話がありましたけれども、低層部、執務機能、議会機能、屋上というところで、エレベーターとしては、低層と高層の２種類に分けるということでよいのか、確認させてください。その手引の作成に障害がある方の当事者も加えて、ぜひ当事者の意見が反映するように進めていただきたいと思いますけれども、併せていかがでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"３点目の質問で、基本設計の中で、アクセシビリティの手引を作成するのかという点につきましては、今年度というくくりではないのですけれども、基本設計が来年度の５月３１日まで実施する予定です。その中で、アクセシビリティの手引を作成していく予定です。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"この点についてご答弁いただきたいと思います。来年５月３１日までに手引を作るということであれば、障害別にしっかりと意見を聴取して、手引に反映していただきたいと思いますが、この点、改めて伺います。そうなると、区民協働・交流エリアというものが、今日の資料では少し狭くなっているように見えるのですけれども、ここはどのようなことなのか、ご説明いただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"その中に記載があるのですけれども、協働・交流スペースは広場と接続しやすい位置に配置しということで、まず、この道路レベルでも配置を検討しているというところ、また、広場レベルというのが、実は２階になりまして。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ伺いましたけれども、やはり縦長にしてしまったがために、移動の不便さ、分かりづらさがあるなと、改めて思いました。最後に、広町の部長・課長もいらっしゃるので、１点だけ確認したいことがあるのです。活用という言われ方はしているのですけれども、これはどのような意味なのか、伺いたいと思います。現状、決まっていることをご説明いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"中塚委員","kind":"確認","question":"第二庁舎については、今はよく分からないということです。ただ、いずれにしても、今の第二庁舎の機能としては、新しい庁舎に入ってくる。これは変わっていないということでよいのか、その点だけ確認させてください。","respondent":"山下新庁舎整備課長","answer":"今、ご質問のあった第二庁舎における行政機能につきましては、新庁舎への集約ということで考えているところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"提案","question":"それはそのとおりだと思うのですけれども、そのときの座長の提案で、議会機能以外の部分についての各会派の意見をまとめたものを当時の行財政改革特別委員会に送っているのです。去年の１月の段階です。それについては、今回、何か反映をされるのか、されないのかというのは、委員長でも結構なのですけれども、理事者側はそのような認識があるのか、ないのか、少しお伺いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"こんの委員長","kind":"確認","question":"私から、前回の行財政改革特別委員会で出されたものが、私としても未確認の状態ですが、それを１１月のまとめに反映するのか、どうなのかというところはご答弁をいただけるものでしょうか。","respondent":"山下新庁舎整備課長","answer":"数日後以降に始めていく基本設計でのご意見聴取の中で、議会機能部分については改めてご意見をいただいてまいりますけれども、もう既にいただいているご意見にアップデートといいますか、追加の事項があるようであれば、その部分につきましては。","voiceIndex":19,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"提案","question":"それに基づいて、幾つか質問をさせていただきたいのと、その大前提として、少し確認させてください。少しその辺りを教えていただきたい。例えば、食堂のことについては設計段階で決めていくというお話がありましたけれども、プロポーザルの段階で食堂についての提案等は、各５つの事業者からあったのかどうか、前提としてそれを伺いたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"続きまして、２点目のご質問なのですけれども、食堂につきましては、基本計画を基にプロポーザルを実施しております。基本的には、規模等々については様々でありますけれども、各社から食堂やカフェが入った形での提案を受けているという状況です。","voiceIndex":21,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"分かりました。今回、プロポーザルで選ばれたのがそれ以外のものだったというところを、今、私も初めて伺って、やはり想定外だなというところで、それも、先ほど、企画をした中で優れているということでこれを選ばれたのでしょう。そうすると、この配置がどう優れているのかということを教えていただきたいなというのが１つ。もししているのであれば、その場所がどこなのか教えてください。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"続きまして、ご質問の２点目なのですけれども、食堂の導入の検討状況につきましては、周辺に様々な飲食店等々ができるというところも踏まえ、規模などを精査していく中では、カフェでも十分ではないかというところもあり。１点だけ補足します。プロポーザルの提案内容に含まれた、どういった位置にあるかというところにつきましては、お答えを差し控えさせていただきたいと存じます。","voiceIndex":23,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"分かりました。この基本計画に書いてある３つの比較で見ると、少し細かいことですけれども、ダブルコアというものが非常に優れているような、３つの中ではこれが選ばれるのかな、これを提案してくるのかなと思っていたのですが、そうではないということです。それは基本設計にも関わってくると思いますので、そのことについても伺いたいと思います。もう一つだけ伺います。トイレの問題です。すみません。","respondent":"大友新庁舎建設担当課長","answer":"それを踏まえて、基本設計の中で反映させなければならない構造上に影響するようなものは、早期に反映させていくのですけれども、基本的には実施設計の中で実現できるように、検討のペースで進めていきたいと考えているところです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"我々からは、区民が最もアクセスしやすい正面フロアの近くに配置していただきたいということを要望させていただいています。基本計画等にもこのようなもののニュアンスは入っているのですが、今日は基本設計の提案ということで、委員長からもご示唆いただきましたので、この辺りについても、どのように基本設計に反映していただけるのか教えていただければと思います。","respondent":"大友新庁舎建設担当課長","answer":"２点目、憩える庁舎というところで、緑の考え方につきまして、基本計画でも緑豊かな開かれた空間を整備していくということで、外構が中心になっていくかと思うのですけれども、できるだけ緑を取り入れた整備を検討してまいりたいと考えているところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"提案","question":"すみません。これも基本計画に書いてありますけれども、一応、念のため伺います。これがどうなのか分かりませんが、我々の提案としては、ヘリポートを庁舎の屋上などに置けないのかということも申し上げました。職員用の防災備蓄スペースを十分に確保していただきたいということもご提案しています。前回の繰り返しになっているのですが、一応、会派の提案ということなので、念のため、確認します。","respondent":"大友新庁舎建設担当課長","answer":"太陽光パネルや、区民の広場として使う場所でもあり、こちらを比較検討して、どちらの機能でやっていくのかというところは、いろいろなところとつながりますので、検討させていただいて、導入機能を決めていきたいと考えているところです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。今、広場１号のところが整備されていまして、Ｂ１地区が、まさに新庁舎の建設予定地になっております。予定地は、ちょうど今、ＪＲのプレハブの周辺が、恐らく、庁舎の建設されるところだと考えています。これに至った理由。なぜこのような通常の免震工事ではなくて、技術的な面というのは、どのような面で優れていたのかということを教えていただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"日建設計で提案された地下柱頭免震と直接基礎を組み合わせた構造形式が大規模地震にどのような面で優れているのかというところなのですけれども、まず、地下から免震をしていくというところで、中間免震と言われる一般的な建物の５階の部分に免震層を入れるとか。","voiceIndex":35,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。もう一点なのですけれども、基本計画の３９ページです。恐らく、３５ｍから４０ｍぐらいがりんかい線が通っていて、りんかい線が通っているから、それに至った理由になった、そのような構造にしたのかなと思いました。深いところだから、建物を建設するに当たっては問題ないのかなとは思うのですけれども、もしお分かりになれば、りんかい線との関係性を教えていただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"こちらにつきましては、区分地上権の設定がございまして、荷重制限等の土地利用制限はありますけれども、その荷重内で建物を建てる形もできるような区分地上権でございまして、その制限の中で活用を図っていくということで設計を進めている状況です。","voiceIndex":37,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"建設するには特別の支障はないということでいいのですか。","respondent":"大友新庁舎建設担当課長","answer":"設計の段階で支障がないと言うと、りんかい線の部分には全て地下構造物を作れなくなってくるので、全くないかと言われると、制限はあるという形にはなります。その制限の上での整備、設計を進めていくという形になります。","voiceIndex":39,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問・要望","question":"今のりんかい線の部分で少しお伺いしたいのです。ただ、一方で、どうも思った以上にそこまで建築制限がかかるわけではなさそうなのかなと思います。その中で、少しお伺いしたいのが、これまでの基本計画だと、今回の資料で言うところのＢ－１地区は赤い外枠で囲まれていて、赤枠の中に長方形が２つあるかと思うのです。この２つの関係というのはどのように理解すればよろしいのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"過去、基本計画ですと、基本的には右側に四角が１個あるような状態だったかと思うのですけれども、これでいうと左側の部分についても、少し建物を建築していく考えで、今、設計を進めているところです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"そうすると、歩行者デッキの部分と動線がかぶってくるのかなと思うので、左側の部分に建てるのは、２階建てのものを建てる計画なのか、あるいは歩行者デッキをぶち抜いていく形で造ることを今のところ想定しているのか、どちらなのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"そこに広場をという考えも用意しなくてはならないところもありますので、この部分に高層棟をぽんと持ってくるということは、現実的には難しいのかなと思います。ですので、高くても２階、３階までのもの、もしくは平の１階になるのかなと考えています。","voiceIndex":45,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"先ほど、エレベーターの関係で、左側の６基あるものとは別に、北側に２基造るという想定をされている。そうすると、この低層部分の車止めの辺りは、１階に関しては外になっていて空いているけれども、２階と３階ぐらいからはせり上がってくるといいますか、はみ出してくるという構造を想定されているという理解でよろしいでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"今、お聞きした形ですと、委員のイメージどおりかと思うのですけれども、私からも少しご説明をすると、２階・３階部分につきましては、これからの検討にもなるかと思うのですけれども、車が入ってくるスペース、ロータリーの上部も建物になる。","voiceIndex":47,"id":"exchange-018"},{"speaker":"塚本委員","kind":"確認","question":"すみません。少し細かいところで確認させてください。最初はどこかというと、新庁舎建設想定規模の中での、国および都の機関が約１０,０００m2と計画されています。この間もいろいろ議論がありましたけれども、現庁舎にあります国および都の機関が過不足なく新しい庁舎にも入ってくるというところで、最終的にどうなっているのかということを教えてください。","respondent":"大友新庁舎建設担当課長","answer":"こちらは抽象的な話で申し訳ないのですけれども、国のどのような機能が入るのかというところにつきましては、調整段階というところでお答えさせていただければと思います。","voiceIndex":50,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、法務局がこの先どうなるかということについては、現段階では、まだ入るとも言えないし、入らないとも言えないという理解でよろしいでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"現機能をそのまま持っていくという前提で国との協議をしているところではありますけれども、確定的な形でのお答えができないというところで、ご理解いただければと思います。","voiceIndex":52,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"もう少し詳しく聞きたい気持ちもしますけれども、多分、お答えがそこまでなのだと思うので、この辺で分かりました。今後とも協議をよろしくお願いしたいと思います。新庁舎のどの位置にサテライトスタジオを置くかということは、いろいろな設備も整えなければいけないことも考えると、基本設計の段階で、ほぼこのフロアのこの位置というのは、もう決めていくという理解でよろしいでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"サテライトスタジオなど、設計に関わって導入する機能につきましては、導入するか、しないかも含めて、基本設計の段階で、配置検討まで含めて実施してまいります。","voiceIndex":54,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"平時はサテライトスタジオをどのように運用をするのだということとうまく統合しないといけないところが出てくるかもしれませんので、どちらをとるかみたいな議論も出てくるかと思うのですけれども、ぜひそこは重々検討していただきたいとお願いしたいと思うのです。再度、ご答弁をお願いいたします。","respondent":"大友新庁舎建設担当課長","answer":"近接にあるべき機能、連携を図るべき機能等につきましては、その連携なども含みで、設計段階で配置計画をしてまいりたいと考えています。","voiceIndex":56,"id":"exchange-022"},{"speaker":"筒井委員","kind":"提案","question":"基本的な確認になるかと思うのですけれども、今回の資料は、設計事業者選定プロポーザルでの提案内容を基に作成しておりますということです。Ａ－１地区、Ａ－２地区、Ｂ－１地区、Ｂ－２地区、Ｂ－３地区とあります。このＢ－１地区やＢ－２地区という地区名のつけ方というのは、便宜上、ＪＲ側の地区名のつけ方に倣ったのか。その辺りの確認をさせていただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"設計会社につきましては、ＪＲの設計会社は異なるとお聞きしています。ＪＲとは常に協議体、会議体を設けて、調整しながら連携などを図って設計を進めているところです。","voiceIndex":58,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"Ａ－１、Ａ－２地区はＪＲで、Ｂ－１、Ｂ－２、Ｂ－３地区は品川区ということなのだろうと思うのですけれども、ＪＲ側の再開発はプレス発表などもされておりまして、２０２５年度末開業の予定ということで、片や、品川区の区庁舎は２０２７年度に供用開始予定ということなのです。その辺りは、そのような理解でよろしいのでしょうか。","respondent":"泉広町事業調整担当課長、大友新庁舎建設担当課長","answer":"先ほどいただきましたＡ－１地区、Ａ－２地区などの地区名が決まっているものにつきましては、もともとこちらの地区につきましては、地区計画といったものが定まってあります。それぞれの建物の竣工時期の違いにつきましては、今、お話しいただいたとおり、ＪＲ側が先行してオープンするという形で、Ｂ－１地区の新庁舎のほうが１年か２年遅れて竣工することになってあります。","voiceIndex":60,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"地方の自治体などに行きますと、役所の建物が一番高い、大きいということがあります。その辺りの調整。これは区庁舎ですよという分かりやすい表示や区別の方法も考えなければいけないのかなと思っているのですけれども、その辺りを区としてはどのようにお考えなのでしょうか。ＪＲとの連携とおっしゃいますけれども、ＪＲ側との調整というか、そうしたお話もされているのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"周辺景観との連続性を確保することも大事なのですけれども、庁舎としてのシンボル性にも考慮し、外観デザインを検討して進めてまいりたいと考えているところです。","voiceIndex":63,"id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"コア配置について、ほかの委員からのご質問で、今、分散コアを検討しているということなのですけれども、これは、通常のセンターコアなどに比べて、ビルの強度やコスト面でどうなのかということを少し教えていただきたい。この分散コアは、特にコスト面などでデメリットはないのか少し気になっているので、メリットは先ほどお伺いしたのですが、デメリットがあれば教えていただきたいです。","respondent":"大友新庁舎建設担当課長","answer":"図でいうと左側にフロア面積を大きく確保することで、ワンフロア当たり３,３００m2や３,６００m2を確保することによって、当初予定よりも多少なりとも階高をある程度抑えられるのではないかなということで、少し複合的に絡んでいるところがあります。","voiceIndex":66,"id":"exchange-026"},{"speaker":"山本委員","kind":"確認","question":"最後のコア配置のところはよく分かりました。コア配置のところでの追加です。確認なのですけれども、日照というのは中側のフロアの日照、日当たりのことを言われているという理解でいいかどうかということ。コスト面です。こういった分散コアのほうが、何となくコスト高になるような印象を持つのですが、そういったコスト的なものは特には変わらないという見立てなのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"コストにつきましては、センターコアだから安い、高いというのは、基本的な考え方としては一部あるかもしれないのですけれども、確実に周辺分散コアだから高いということは、一概には答えられないところではあります。","voiceIndex":68,"id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"私から２点あって、１つは屋上部分についてです。多分、エアコンの室外機などかなということを想像してしまうのですが、そのことについて伺いたいと思います。この図を見ると、全部囲まれて、外が見えないのかなと思うのですが、少しその構造についてお知らせいただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"ぱっとページが出てこないのですけれども、コージェネレーションシステムという、通常、電気をつけるに当たっては、東京電力などの電力会社から線を持ってきて、照明等々に使っているという設備のほかに、災害時に電力が切れたときにどうするのかというところと。","voiceIndex":72,"id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"今の屋上のような感じではないということでよろしいですか。","respondent":"大友新庁舎建設担当課長","answer":"３６０度見渡せる屋上という形ではないという状況が今の検討段階の素案です。","voiceIndex":74,"id":"exchange-029"},{"speaker":"松永委員","kind":"質問・要望","question":"理解いたしました。最後に１点、喫煙所の問題なのですが、新庁舎について、喫煙スペースは造られるのかどうかということを伺いたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"基本的には、法律等々にのっとって整備する必要があり、整備できるのかどうかというところになってくるかと思うので、一応、施設整備上の規定によりますけれども、こちらについては今後の検討とする形になります。","voiceIndex":76,"id":"exchange-030"},{"speaker":"せお副委員長","kind":"質問","question":"すみません。１点だけ。先ほど、結構冒頭のほうかなと思うのですけれども、飲食などの食堂やカフェなどの質問のご答弁で、カフェなどで十分なのかなみたいなお話があったと思うのです。基本計画では、食堂やカフェなどの飲食スペースは、現庁舎の利用実態や希望調査、周辺の整備状況を踏まえ計画となっているので、ここが一緒になっている理由というか、そういったところの考え方を教えてください。","respondent":"山下新庁舎整備課長","answer":"今、ご紹介いただいたとおり、障害者就労の目線では、やはりカフェの設置というものを、先ほど、別の委員からもございましたけれども、区民がより目に触れやすい場所、来庁された方にすぐ届く場所に設置していくというところは。","voiceIndex":79,"id":"exchange-031"},{"speaker":"せお副委員長","kind":"質問・要望","question":"今後の目的や、今後、区民の皆様もそうですし、職員の皆様がどういった考え方というか、どういった方向性でいるのかというところも調査していただいて、そこは一緒にというよりは、私は目的で分けていただいて、調査していただきたいなと考えているところです。そこは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"すみません。２回目になりますけれども、１点だけ。区民協働・交流を促す仕組みというものが書いてあるのですが、議場の位置づけというのは、今までの基本計画に出ていて、４７都道府県、１,７００ある自治体の役所、役場のほとんどが上にある。５つの事業者があって、それが１つの選定理由で特筆されている理由というか、もし現状を教えていただけるようなニュアンスがあれば教えてください。","respondent":"大友新庁舎建設担当課長","answer":"Ａ３のカラー刷りの資料をご覧いただければと思うのです。右上の図の「展望機能・屋上」の下の「議会機能」とあるところに議場という提案をいただいてあります。ほかとの比較という話ではなく、この提案でのお話をしますが、議場上部が屋上に出ております。","voiceIndex":83,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"意見","question":"先ほど、区民を見下ろす、見下ろさないという話がありましたが、区民に上から見ていただいているということで、なるほど、特筆すべきだなというところで、ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-034"},{"speaker":"えのした委員","kind":"質問","question":"先ほど出ましたが、コア配置の比較で、周辺分散コア型の自由度が高いとお伺いしました。基本計画には、例えば、中央コアは豊島区、両端コアは中野区という事例がありますが、他の自治体でこういった事例はあるのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"自治体の事例といたしましては、把握してないところです。低層の２階や３階ではよくある話ではありますけれども、オフィス棟の実績等々は多分にあるというコアです。","voiceIndex":87,"id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"オフィスなどでは多いということで確認がとれました。もう一点、以前、この委員会で、２０２２年に世田谷区役所の視察をされているようです。区役所としても、ちょうど今整備中の中野区や、完成している他の自治体の庁舎の視察や聞き取り調査など、これからもしていく予定はありますでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"近隣区の視察、また、近隣区でなかったとしても、同規模の庁舎を建てた事例など、調査をしています。その調査の中での働き方なども含めて新庁舎の状況を確認しているところで、今後も継続して視察等々を進めていきたいと考えているところです。","voiceIndex":89,"id":"exchange-036"},{"speaker":"まつざわ委員","kind":"質問","question":"午前中もお話を聞いたので簡単に。基本設計をやってから、実施設計ですね。その間に、区民の皆様には、教室型やオープンハウス型説明会などをやっていくというお話があったのです。いろいろな人の声があります。本当に大きな事業の中で、例えば、もう遅いですけれども、区民アンケートなどもありました。例えば、オープンハウス型をやっても、全体を集めるのはなかなか難しい話です。そこだけお願いします。","respondent":"山下新庁舎整備課長","answer":"その際、広報しながわでしたり、ＳＮＳの活用が１つ大きいかなと思っておりまして、基本計画の際に用いた動画のように、皆様に普及できるような方法を今後も研究してまいりたいと考えています。","voiceIndex":93,"id":"exchange-037"},{"speaker":"まつざわ委員","kind":"意見","question":"ぜひ本当にいろいろな町会を回っていただいて、それこそ私たち議員も協力の下、何町会あってもいいと思うのです。地域センターでもいいと思っていますので、丁寧にしつこくやっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":27255,"voices":99}},{"id":"r05-20230726-19","meetingId":"r05-cm07","date":"2023年7月26日","dateIso":"2023-07-26","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6638#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":713,"voices":5}},{"id":"r05-20230727-10","meetingId":"r05-cm07","date":"2023年7月27日","dateIso":"2023-07-27","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"しながわシティラン実行委員の推薦","agenda":"しながわシティラン実行委員の推薦","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"選出方法の前に、７月２４日に議長に依頼が来たということで、７月２８日までというのは、議会内で議論する時間があまりにもなさ過ぎるので、議会としては区長のほうに、苦情ではないですけれども、意見というのは申し上げたのでしょうか。これはタイト過ぎると思うのですけれども、その辺はどうなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"議会として誰を選出するかということを考えるというか、議論する暇がなさ過ぎるのです。今後のこともあるので、これはぜひ議会側から意見を言っていただきたい。もう少し検討する時間の余裕を持って通知をしてほしいという意見は述べてほしいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"私は思うのですけれども、しながわシティラン実行委員会とは何なのか、どういうものなのか、そういうものも何も説明がなくて、いきなり議会で２名出してくださいというのは、ちょっと変な話ですよね。別に悪いことではないと思うけれども。それを、専門的な知識がほとんどない議員に、これに一緒に入ってくれというのは、頼むほうも頼むほうだけれども、受けるほうも、これを受けていいのですかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"令和５年第３回定例会","agenda":"令和５年第３回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"ですので、民生費とそれ以外のものということで、独立して日程を組む必要があるのではないかということを、何度か提案させていただいているのですけれども、議会運営委員会なのか、議会改革推進会議なのかというのはあると思うのですが、検討していただけるのだったら、ここでも検討していただきたいのですけれども、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"申し合わせ確認事項についても、必要であれば、議員がある程度議論をして変えればいいわけですし、少なくとも提案をしているわけですから、それをどこかで議論するという考え方はないのでしょうか。議論することもしないというお考えなのでしょうか。議会改革推進会議なのか、ここなのか分かりませんけれども、少なくとも正副委員長で、少しもんでいただきたいのですが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-005"}]},{"id":"topic-03","title":"令和６年度予算（議会費）","agenda":"令和６年度予算（議会費）","exchanges":[{"speaker":"せりざわ委員","kind":"質問・要望","question":"１点目、政務活動費の第三者機関設置。その際に、廊下でうろうろしながら電話をしているのですけれども、議員応接室を使ったりということも現状ではあって、例えばですが、今使っていない喫煙所の、改築になるのか分かりませんが、そういったところを使って、電話を気兼ねなくできるようなスペースというのをつくれないかという思いで、要望させていただきました。以上４点、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"公明党からは、３点です。３つ目は、これは港区が一つの例ですけれども、区議会独自のフェイスブック等のＳＮＳを駆使した定例会・委員会の情報発信、審議の経過や採決ということを、区議会だよりだけによらず、ＳＮＳ等を使ってということで行っていきたいということでの予算を要望したいということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"１、子ども向け議会の仕組み動画の作成に関する予算です。資料には書いていないのですが、２点ほど議論していたところがありまして、併せてお伝えさせていただきたいのですけれども、１つ目が政務活動費に関して、自民からもご提示いただいておりますが、適正利用を図るための第三者機関の設置に対する予算、これは当会派としても議論しておりまして、ここに記載はございませんが、要望したいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"実質使えないということだったので、議場を含めて、議会棟の女子トイレを増やすことを求めるものです。５は、討論の準備のために議事録の速記録を早めてほしいという内容なのですが、予算を増やせばすぐに実行できることだと伺っていますし、議会の機能強化を充実させる本丸の一つでもあると思いますので、ぜひお願いしたいと思います。ですので、予算を増やして対応してほしいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"私も事務局といろいろ相談することもあるのですけれども、こんなに厳しい上に、また第三者機関を付ける必要があるのですかというのを皆さんに問いかけたいのと、行財政改革というのを品川区でやっているのですけれども、なぜ品川区議会でも、区議会の予算の見直しとか、そういうことをやっていかないのかというのは、これも意見だけなのです。それと、委員会インターネット中継。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-010"}]},{"id":"topic-04","title":"その他の(1)議員研修会","agenda":"その他の(1)議員研修会","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"議長が一生懸命なのは分かるのです。これも研修、これも研修で、でも、どちらかにしてほしいのです。１日１本ぐらいにしてほしい。せっかく、例えば午後４時からあると聞いたので、すみませんと言ってキャンセルして、午前中にやろうと思ったら、今度は午前中も研修会が入ってきたとなると。皆さんもそうだと思うのです。予定を組んでいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":10810,"voices":44}},{"id":"r05-20230821-6","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"区民委員会","time":"午後 １時００分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"大井第三地域センター・区民集会所の移転","agenda":"大井第三地域センター・区民集会所の移転","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。地域センターの老朽化に関わる移転ということで、しっかり対応すべきことだと思っています。これについて、地元の、まさに利用者の皆さん、区民の皆さんや町会・自治会の皆さんからご意見、要望等をお聞きになっていらっしゃって、それを反映されているのかというところを教えてください。","respondent":"宮澤地域活動課長","answer":"地域センターが老朽化してきている中で、今後を見据えたときに、そのままその場所で建て替えという検討もありましたけれども、今回、近隣の場所で、また、ウェルカムセンター原が避難所となっているのですけれども、そこと近い場所にマンションができ、事業者と協議していく中で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西村委員長","kind":"提案","question":"私から１点だけ申し上げます。移転に関しましては、今後議案として提案される見込みですので、その際の来る議案審査においてもご質疑いただくことができます。それを踏まえていただければと思います。７月２４日の総務委員会におきまして、大井第三地域センター・区民集会所移転に伴う内装工事請負契約といったものも報告されておりますので、踏まえてご質疑いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"補足のご説明も含めてありがとうございました。議案審査として質疑ができるということで理解いたしました。今、質問に対してお答えいただいたのは１つ目と、３つ目の質問にはお答えいただいていましたか。","respondent":"宮澤地域活動課長","answer":"失礼いたしました。地域からの声としましては、防災機能の強化だとか図書館という声がありました。その中で、防災備蓄倉庫ということで、防災機能の強化という意見を含めたところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"ありがとうございました。区民の皆様の利用しやすい施設であり、ぜひ要望を取り入れていただきたいという思いがありますので、防災のところで取り入れていただいているというところで、よいなと思うところ。利用のところで、例えば、トイレの使いやすさとか、障害者の方にも使いやすいような実際の細部の設計とかもぜひ声を聞いて進めていただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"確認","question":"今の質疑の中で確認なのですけれども、全体で月額３３９万円余と聞こえたのですが、この確認が一つ。第三集会室は現在よりも小さくなるというところで、どのように考えればいいのかということが、要するに、全体的に狭くなってしまうのではないですかということが一つ。いわゆる今使っている多目的トイレというものがありますけれども、そこの考え方との違いを教えていただければと思います。","respondent":"宮澤地域活動課長","answer":"３点目のトイレにつきましては、平面図を見ていただきまして、トイレ機能というのは充実させております。１階にも男女別と、加えて、バリアフリーのトイレも設けております。２階部分に共用トイレというのも新たに設置いたしました。","voiceIndex":12,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"私もこの地域には住んでいないので、地元の議員に確認しました。どういう地域なのかというところで、先ほど月額３３９万８,０００円余ですか。全体とすれば広くはなっているということで、ただ、階数の関係で、第一集会室と第二集会室が逆になっているということで確認いたしました。それをどのように周知していくのかというところ、その辺りを教えていただければと思います。","respondent":"宮澤地域活動課長","answer":"金額という面です。西大井の、今回の移転先の近隣で同規模の平米数での事務所の賃料というのは、参考になるものはなかなかないところでありますけれども、大井町駅前とか、そういったところと比べても、適切な金額と認識しているところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"現状のマンション、場所はよく分かっているのですけれども、集会所ができると報告していますが、それだけの民間のマンションの中において、集会所として借りる形を取っているということは、設計段階から品川区としては集会所として借りるからというような、契約までいかなくても、下準備があったのでしょうか。その辺について教えてください。","respondent":"宮澤地域活動課長","answer":"町会・自治会支援もありますので、当然地域センターの管轄区域内での移転という形になるので、そこら辺、建て替えなのか、また、移転なのかという形で様々検討しているという状況です。","voiceIndex":19,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"１つ目の質問で、特別委員会で質疑があったという、でも、設計段階から予定に入っていますというのであるならば、この地域活動、町会等を所管している区民委員会には、そういう計画があるという時点できちんと報告すべきだと私は思います。課長、どう思いますか。そこの設計段階で、区と交渉している段階でこの常任委員会で言うべきだと私は思うのですけれども、その辺についていかがですか。","respondent":"宮澤地域活動課長","answer":"委員会報告すべきタイミングにつきましては、委員のご意見も踏まえて、今後、参考にさせていただきたいと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"参考ではなくて、どうですか。もう建ってしまっているでしょう。でなかったら、この区民委員会という委員会は何なのでしょうか。報告すべきことだと思います、私は。それが常任委員会なのだから。その辺についても、区民の皆様の税金を使って施策をしていくわけですから、その辺はしっかり区民委員会において報告をどんどんしていっていただきたいと思うのです。改めてその辺についていかがですか。","respondent":"宮澤地域活動課長","answer":"地域センターの改築に関わらず、当然、議会報告というのはしっかりと時期を見てさせていただきたいと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。幾つか確認なのですけれども、まず、建設のほうなのですが、建物自体の完成というのは１月頃なのでしょうか。いつ頃完成するのかというのを確認させてください。","respondent":"宮澤地域活動課長","answer":"この建物、マンション自体は８月末で完成します。そこから今度は地域センター、集会室のしつらえに変えるための内装工事を、９月から１月いっぱいをめどに工事が入ります。その後、まだ日にちは決まっていないのですが、２月に開所式をする予定という形です。授乳室です。","voiceIndex":26,"id":"exchange-010"},{"speaker":"せらく委員","kind":"質問・要望","question":"１点だけ質問させていただきたいと思います。今回、防災機能の整備をするということで、２階に防災備蓄倉庫というふうに平面図で確認いたしました。その点について伺えればと思います。","respondent":"宮澤地域活動課長","answer":"１階の会議室、なるべく１階で階段等を使わずに区民の方が利用できるように、１階にも集会室を設けたというところと、ある程度まとまったスペースを防災備蓄倉庫のほうで活用することになりますので、そういったところをいろいろ検討した上で、２階部分になったです。","voiceIndex":29,"id":"exchange-011"}]},{"id":"topic-02","title":"令和５年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和５年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"ご説明ありがとうございました。１つだけお伺いしたいと思います。子ども若者応援フリースペース、私も視察させていただいたことがありますけれども、大変実績のある団体だということで理解しているのですが、今回、トライ助成に関して、ヤングケアラーへの取り組みというテーマで応募をされたほかの団体というのはどれぐらいあったのか、教えていただければと思います。","respondent":"宮澤地域活動課長","answer":"その中でトライ助成につきまして申請をいただいたのは、今回選定された１団体のみでした。この区民活動助成の申請に当たっては、事前相談会等も開いております。その中では、お話を聞きにいらした団体はあったところではありますが、申請については１団体になったです。","voiceIndex":36,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"確認","question":"分かりました。私も拝見したことがあって、お話も代表理事の方から伺ったことがありますし、品川区の子ども若者支援に非常に貢献されているということは理解をしているのですが、そこで今回のこの2)のところで、これから実施する内容について端的に書いてありますけれども、一応確認のために聞かせてください。","respondent":"宮澤地域活動課長","answer":"事業の実施に関しての具体的な内容につきましては、それは実際に学校に行って、子どもたちを前にヤングケアラーについて説明をして、いわゆる認識のない方を含めた掘り起こしということで普及啓発をしていくです。","voiceIndex":38,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"確認","question":"繰り返しになりますが、実績がある団体というのは理解をした上で質問しておりますが、今回実質、応募に至ったのは１つの団体だけであって、ほかの団体と比べると、トライ助成の金額が大きいのですよね。周知啓発の方法もそれに含まれているという今のご説明だったのですけれども、区民委員会という場ですから、一応、どういう趣旨で選ばれたのかということは確認をさせていただければと思います。","respondent":"宮澤地域活動課長","answer":"申請にあります今年度９月以降の事業としては、小中学校で１校ずつ、高校で２校という申請でございました。その上で、基本的にトライ助成の期間は３年間です。","voiceIndex":40,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"確認","question":"そんな単純な計算ではないかもしれませんけれども。ということで、分かりました。当然、決算等でも、この使途についてはまた確認があるとは思いますけれども、少し金額が大きかったので、あと、期間が短いというところで、少し質問をさせていただきました。先ほどの繰り返しでこれも３回目になりますが、非常に実績のある団体だというのは理解しておりますので、これで終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"},{"speaker":"えのした委員","kind":"意見","question":"やはり助成金、結構、今のトライ助成などというのは高額ですので、分かりやすく説明して、また来年以降に続くような報告会をしていただけるとありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-016"}]},{"id":"topic-03","title":"物価高騰等総合支援資金（事業）の延長","agenda":"物価高騰等総合支援資金（事業）の延長","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"４の実績ですが、ご説明があったけれども、申請してから実行されるまで１か月余りというお話があった中においても、半分近く実行されていないわけではないですか。そういう考えでいいのか。１７６件、区があっ旋するわけですよね。１か月ぐらい遅れるかもしれないけれども。大体半分まではいかないけれども、実行されていないわけではないですか。その確認です。そういう考えでいいのですか。","respondent":"小林商業・ものづくり課長","answer":"今回、７月末現在ということで１７６件、実行に至っているものが９５件ですけれども、これがまた少し時間が経ちますと、融資実行に移されるものが出てきまして、これで否決される率は本当に低いですので。","voiceIndex":51,"id":"exchange-017"},{"speaker":"藤原委員","kind":"確認","question":"もう１回確認するけれども、７月末で１７６件ということで、あっ旋する数というものもまた上がってくるわけですよね。ただ、この数字だけを見てしまうと、半分ぐらいしか実行されていないではないかとなってしまうので、最終的には、あっ旋状を出したのと実行されるのは限りなく近いと思っていていいのですね。","respondent":"小林商業・ものづくり課長","answer":"ただいまの藤原委員のご指摘に近いというか、実際に、否決というのは確率的にかなり低いものでございまして、最終的にこれが年度末というか、最終的に集計の段階にいきますと、実行件数というのはあっ旋状況にかなり近くなってくるというご理解で結構だと思います。","voiceIndex":53,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"安心しました。最後に１点だけ伺いたいのですけれども、中小企業、個人事業主の方にもあっ旋、そして、このように資金繰りが厳しいところに助成をしてあげますよね。だって、個人の方が今、物価高騰していても、例えば、車に乗るのにガソリン代が高いからといって、個人にお金を出すなどということはしないわけではないですか。どのように押さえていっているのか、教えてください。","respondent":"小林商業・ものづくり課長","answer":"この融資あっ旋制度を使って中小企業の負担といいますか、支援をしているところではありますけれども、生産、消費、雇用、こういったものでやはり企業活動というのが安定的に継続できるということが、やはり区内経済にとって大事なポイントだと考えています。","voiceIndex":55,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"この予算を見ても、約２億６,０００万円を使うわけではないですか。区民の税金をこのように使って施策をするということで、私、もちろん賛成なのですよ。その辺の重みというのを思いつつ、感じつつ、この施策を、しっかり押さえてやっていっていただきたいと思いますので、今後ともよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-020"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問","question":"都市型観光は、コロナの令和２年、３年ですとか、すごく厳しい状況があったかと思います。質問なのですけれども、資料の２枚目の水辺関係のところ、令和５年度の「しながわ」宝探しの旅のところで、「小学校の意見を取り入れた学びにつながる」という記載があるのですけれども、この辺り、どういった形で小学校の意見を取り入れていくのかというところが気になりましたので、ご説明をいただければと思います。","respondent":"篠田文化観光課長","answer":"ですので、例えば、１つは、船に乗ることとともに、地域を歩いて実際に見て回るという形なのですけれども、基本的には、小学校の場合は３年生で区内を勉強するはずなのですが、どうしても区内全般になってしまうので、特に今回は品川の地域、品川神社ですとか品川宿。","voiceIndex":71,"id":"exchange-021"},{"speaker":"横山委員","kind":"意見","question":"今、探究ということが資料のイラストのところに載っているのですけれども、区民委員会は観光が所管ですけれども、子どもたちの探究の学習というところとコラボしたような形で、子どもたちのそういった意見というか、考えを深めるような授業であったり学びというものと一緒にやっていって、子どもたちの意見みたいなものも、観光であったり、区内の魅力の発見であったりとか。","respondent":"篠田文化観光課長","answer":"その辺を踏まえまして、また来年度以降、どういった形で実施、拡大できていくか分かりませんけれども、できるだけ広めていきたいという思いはありますので、来年度以降に活かしていけるような形で取りまとめをしていきたいと考えているところです。","voiceIndex":73,"id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"ですから、様々、こうしたチャレンジングなことを子どもたちと一緒に大人もチャレンジしていただいて、その中から成功と失敗というような二元論ではなくて、本来の目的をしっかり捉えていただきながら、そこから新たな考えを見つけていったり、区内の魅力を子どもの目線で様々見つけて、それを発展させたり、外国人の方であったり、国内であっても、隣の区のお友達であったりとか。","respondent":"篠田文化観光課長","answer":"今後も引き続きこの対応を続けていきまして、特に品川の場合には、うまくすれば、羽田空港に行かれる際の立ち寄り先等にも可能性はありますので、そういった地の利も含めた展開を考えていければと考えているところです。","voiceIndex":75,"id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"最後に、今後の展開と課題のところで、「地域資源をテーマごとに束ねて効果的にアピールし」という記載があるのですけれども、私、イメージがうまくできなかったのですが、地域資源をテーマごとに束ねるというのはどういったイメージを区としてお持ちなのかというところを教えてください。","respondent":"篠田文化観光課長","answer":"今、一番力を入れている部分で言えば、水辺関係等のテーマでまとめるとか、あるいは、地域でも、先ほど申し上げたような形で、蛇窪神社等の神社仏閣関係とか、いろいろな形で、一つ一つはそれほど有名ではなくても、まとまると一つの流れとして繋がってくるようなもの。","voiceIndex":77,"id":"exchange-024"},{"speaker":"横山委員","kind":"意見","question":"テーマのまとめ方、束ね方というのにもいろいろあるかと思うのですけれども、様々、外国人であったり、国内であったり、高齢者の方から若者の方々、お子さんであったりとか、いろいろなニーズがあるかと思いますので、そうした品川区に来てみたいと思ってくださる方々のそういったニーズ、目的であったりとか、そうしたところ、しっかり軸を捉えたテーマ設定をしていただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-025"},{"speaker":"えのした委員","kind":"質問","question":"私たちも、どの方がＳＮＳを発信しているというのは、例えば、「＃品川区」とか、「＃わ！しながわ」とか、発信するときにはこのようにするようにといった、そういった指示みたいなものは出ているのですか。","respondent":"篠田文化観光課長","answer":"しながわ」でまとめるとかということは難しい状況があります。ですので、逆に言うと、国内よりも海外に対して力を入れているところがあって、国内では、品川区民に対してやっていますというのはなかなかお知らせしづらいような形になっているのは間違いないところです。","voiceIndex":83,"id":"exchange-026"},{"speaker":"えのした委員","kind":"質問","question":"私も観光協会の方ですとか海外の方にお話を伺ったときに、ネットで調べるというよりもＳＮＳで見て調べて、その観光地に来られるという方が非常に多いということで、加えて、品川区というのは大使館が１２か国、領事館もありますけれども、その当時、私たちも地域の方に、先ほどおみこしを担いでいただくみたいな体験型で、近くの大使館にお願いして、そういった交流はどうですかみたいな話があって。","respondent":"篠田文化観光課長","answer":"なかなか役所的には、大使館の対応というのは平和・国際担当がやっているものですから、平和・国際担当とも私どももふだんから付き合いはあるので、様々な形でお願いができるかと思うのですけれども、大使館の方に対してそういった働きかけをしてきたことは。","voiceIndex":85,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"提案","question":"先ほど横山委員からも質問があったところで、「しながわ」宝探しの旅というところで、私どもの会派も観光協会などからいろいろお話を伺っていく中で、昨年度はＳＤＧｓの考えを取り入れたようなまち歩きのプログラムを開発して、それで試行してみたというようなご意見を伺いました。そこの辺り、今、品川区としてどうお考えになっているのか、教えていただければと思います。","respondent":"篠田文化観光課長","answer":"今年度実施する「しながわ」宝探しの旅、お子さん向けのツアーに関しましては、基本的に予算的には区の予算なのですけれども、観光協会の自主事業として使える一定の枠をお渡ししていますので、その中で実施をする事業ということで。","voiceIndex":89,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"提案","question":"今後の展開と課題のところに、最後の目的、観光というのは何のためにやるのかという、都市型観光、さらなる「区民の幸福」につなげていくという、かなりざっくりとした目標が書かれているのですけれども、その中で森澤区長もよくおっしゃっているウェルビーイングとかＳＤＧｓとかというところで、そういったものを地域で今までありそうでなかったもの。","respondent":"篠田文化観光課長","answer":"効果ですけれども、見ていただいてすぐにロケ等の引き合いがあるかというと、そこまではなかなかいかないのですけれども、件数としては、対応件数が、コロナの影響があったのかなかったのか、その辺は微妙なのですけれども、令和３年度で対応件数６８件、令和４年度で５７件。","voiceIndex":91,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"提案","question":"フィルムコミッションのところなのですけれども、最近、テレビを見る方がすごく減ってきていて、ネットに流れている。横山委員なども、映画の制作などでもフィルムコミッションですごく協力していただいたなどというお話も議会で伺いましたけれども、そこはぜひ着実に育てていっていただきたいというのが１つです。最後に１点だけ。品川区は、先ほどお祭りの話もありました。屋形船の話もありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-030"},{"speaker":"山本委員","kind":"質問","question":"ご説明ありがとうございました。そういったところでいうと、この辺のアクションの仕方としては、今回はたまたま小学校の校長先生がそういったつながりがあって広がったという話でしたけれども、例えば、そういう小学校の校長先生はどういう形でアプローチしていくと、こういうものにつながりやすいのかというところで、どういったやり方がいいのかというのを教えていただければと思います。","respondent":"篠田文化観光課長","answer":"学校への拡げ方というのはなかなか難しいところではあるのですけれども、一番効果的なのは、校長先生の口コミ、要は、こういうことをやってよかったという話が非常によいと聞いております。","voiceIndex":95,"id":"exchange-031"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。ぜひ多くの小学校の皆さんに拡げてもらえるように前向きにご検討いただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"私が質問した後の議論を踏まえましてお尋ねしたいと思うのですけれども、インフルエンサーの方、ＳＮＳやＹｏｕＴｕｂｅによる情報発信の部分なのですけれども、発信している方、インフルエンサーの方自体というのは、何歳ぐらいの方でいらっしゃるのかというのと、対象者は広く設定されていると思うのですけれども、大体どのくらいの年代の方に向けて発信をしているようなイメージなのか。","respondent":"篠田文化観光課長","answer":"中にはご結婚されて、ご家族がいらっしゃる方もいらっしゃいますので、視点はそれぞれ、独身の方はどちらかというと若い方向けに、面白そうだといったところを取り上げていただいたり、ご家族の方はファミリー向けによさそうなところを取り上げていただいたりという形で。","voiceIndex":99,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"この間、芝浦工業大学の原田曜平教授のお話を伺ってきたのですけれども、Ｚ世代とこれからのまちづくりというところで、それは観光の文脈というところに焦点を当てているというお話ではなかったのですけれども、やはりＺ世代、１０代後半から２０代前半ぐらいの方、二十五、六歳ぐらいまででしょうか。その辺りの方々というのが、拡散力がすごく高くていらっしゃるということでした。","respondent":"篠田文化観光課長","answer":"それで、拡散力の点でいけば、確かに若い方、恐らく非常に強いのだろうというところがあるので、そういった観点も持ちつつ、逆に、実際に来ていただくことを前提とすると、そういった方々に対する、例えば。","voiceIndex":101,"id":"exchange-034"},{"speaker":"西村委員長","kind":"質問","question":"今回、この所管事務調査として理事者にご準備いただいたのが、行政視察を見越してこの時期にという、正副委員長の思いもありましてご準備いただいたのですけれども、品川区が単独で集客力を持つ資源がないという中で、本当に今日様々ご意見が出ているのですが、体験型に大変魅力を感じておりまして、あくつ委員のご意見にも先ほどあったのですが、もちろんさらに磨いていく白地がありながらも。","respondent":"篠田文化観光課長","answer":"そういった方々のほかにも、これから先、特に品川区の場合、どうしても海寄りに観光地が多いものですから、そちらのほうで活動されている方がたくさんいらっしゃるのですけれども、内陸のほう、荏原の地域ですとか。","voiceIndex":103,"id":"exchange-035"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"ホッケータウン公式認定プログラムというのは、趣旨は分かったのですけれども、これに応募する条件とか、現状、このホッケータウンに公式認定されている都市が幾つぐらいあるのか、ちなみにそこはどこなのか、参考のために教えていただければと思います。","respondent":"三井スポーツ推進課長","answer":"既に公式認定をされているところがあるかまでは、すみません、調べ切れていないのですが、調べが終わりましたら個別にご説明するという形でよろしいでしょうか。","voiceIndex":111,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"分かりました。それと、先ほど条件として、ホッケーを品川区として非常に活用していくということが条件だと。品川区というか、都市としてですね。品川区としては、ホッケータウンになることについてどのようにお考えになっているのか、念のため確認をさせていただきたいと思います。","respondent":"三井スポーツ推進課長","answer":"ホッケータウンの認定を受けましたら、ホッケーを盛り上げながら、地域と一体になって、地域のにぎわいづくりを通して、スポーツを支える人口を増やすなど、そういうことについてつながりを持たせていければと考えています。","voiceIndex":113,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2966#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":43573,"voices":116}}]);
